    {
        scanf("%d%d",&p[i].x,&p[i].y);
        p[i].id=i;
    }

    sort(p+1,p+n+1,cmp1);
    for(int i=2; i<=n; i++)
        add(p[i-1].id,p[i].id,p[i].x-p[i-1].x);

    sort(p+1,p+n+1,cmp2);
    for(int i=2; i<=n; i++)
        add(p[i-1].id,p[i].id,p[i].y-p[i-1].y);

