i32 solve() {
    in(n);
    times(n, ni) {
        indef(i32, x, y);
        xs.append(make_pair(x, ni));
        ys.append(make_pair(y, ni));
    }
    sortall(xs);
    sortall(ys);
    times(n-1, ni) {
        es.append(make_tuple(xs[ni+1].first - xs[ni].first, xs[ni].second, xs[ni+1].second));
        es.append(make_tuple(ys[ni+1].first - ys[ni].first, ys[ni].second, ys[ni+1].second));
    }
    sortall(es);

    i32 ans = 0;
    unionfind uf(n);
    times(es.size(), ei) {
        i32 d, ni, nj;
        tie(d, ni, nj) = es[ei];
        if (uf.same(ni, nj)) continue;
        uf.unite(ni, nj);
        ans += d;
    }
    return ans;
}

