	}

	while(!st.empty())
	{
		pair<int,pair<int,int> > cur=*(st.begin());
		st.erase(cur);

		int u=cur.second.first,v=cur.second.second;

		ans+=(Onion(u,v)*(min((abs(x[u]-x[v])),(abs(y[u]-y[v])))));
	}

	cout<<ans;

	//printf("Time used = %.6f",(double)(clock())/CLOCKS_PER_SEC);
	return 0;
}

