#define in std::cin
#define out std::cout
#define rep(i,N) for(int i=0;i<N;++i)
typedef long long int LL;

LL N;
std::vector<std::pair<LL, LL>>xy;
std::vector<LL>res;
LL ans;

int main()
{
	in >> N;
	rep(i, N)
	{
		LL x_, y_;
		in >> x_ >> y_;
		xy.push_back({ x_,y_ });
	}

	xy.push_back({ -INF ,-INF });
	xy.push_back({ INF,INF });
	std::sort(xy.begin(), xy.end());
	for (int i = 1; i < xy.size() - 1; ++i)
	{
		auto x_num = xy[i + 1].first;
		auto y_num = xy[i + 1].second;
		auto next = std::min(abs(x_num - xy[i].first), abs(y_num - xy[i].second));
		x_num = xy[i - 1].first;
		y_num = xy[i - 1].second;
		auto prev = std::min(abs(x_num - xy[i].first), abs(y_num - xy[i].second));
		res.push_back(std::min(next, prev));
		if (next >= prev)
		{
			xy.erase(xy.begin() + i - 1);
		}
		else
		{
			xy.erase(xy.begin() + i);
		}
	}
	std::sort(res.begin(), res.end());
	rep(i, res.size()) { ans += res[i]; }

	out << ans << std::endl;
	return 0;
}

