    }
    sort(ind, ind + n, [&](int lhs, int rhs) {return y[lhs] <= y[rhs];});
    FOR0(i, n-1) {
        pq.push(mp(y[ind[i]] - y[ind[i+1]], mp(ind[i], ind[i+1])));
    }
    ll ans = 0;
    while(!pq.empty()) {
        int curw = pq.top().ff, u = pq.top().ss.ff, v = pq.top().ss.ss; pq.pop();
        if(sameSet(u, v)) continue;
        unite(u, v);
        ans += curw;
    }
    cout << -ans;
}

