	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) { //ｘの入ってる集合と yの入ってる集合を併合
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) { //xとyが同じ集合に入っているかどうかを判定
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	bool isroot(int x) {
		return data[x] < 0;
	}
	int size(int x) {
		return -data[root(x)];
	}
};
BiDGraph Kruskal(BiDGraph g) {//最小全域　森
	UnionFind uf(g.vn);
	priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> que;
	REP(i, g.g.size()) {
		for (auto itr : g.g[i]) {
			int f = i, t = itr.first;
			if (f < t)
				swap(f, t);
			que.push({ itr.second,{ f,t } });
		}
	}
	BiDGraph MST(g.vn);
	int alcou = 0;
	while (alcou < g.vn) {
		pair<int, pii> cur = que.top();
		que.pop();
		if (uf.findSet(cur.second.first, cur.second.second))
			continue;

		if (uf.data[cur.second.first] == -1)
			alcou++;
		if (uf.data[cur.second.second] == -1)
			alcou++;
		uf.unionSet(cur.second.first, cur.second.second);
		MST.con(cur.second.first, cur.second.second);
	}
	return MST;
}
signed main() {
	int n;

	scanf("%lld", &n);
	vector<pii> pos(n);
	vector<pii> x(n), y(n);
	REP(i, n) {
		scnaf("%lld %lld", &pos[i].first, &pos[i].second);
		x[i] = { pos[i].first,i };
		y[i] = { pos[i].second,i };
	}
	sort(ALL(x));
	sort(ALL(y));
	BiDGraph g(n);
	rep(i, 1, n) {
		g.con(x[i - 1].second, x[i].second, abs(x[i].first - x[i - 1].first));
		g.con(y[i - 1].second, y[i].second, abs(y[i].first - y[i - 1].first));
	}
	BiDGraph mst(Kruskal(g));
	ll ans = 0;
	REP(i, n) {
		for (auto itr : mst.g[i])
			ans += min(abs(pos[i].first - pos[itr.first].first), abs(pos[i].second - pos[itr.first].second));
	}
	printf("%lld\n", ans/2);
	return 0;
}

