template <typename T>
struct edge {
  int from, to;
  T cost;

  edge(int from, int to, T cost) : from(from), to(to), cost(cost) {
  }

  bool operator<(const edge& o) const {
    return cost < o.cost;
  }
};


/* O(E log V) */
template <typename T>
T Kruskal(vector<edge<T>>& G, int V) {
  sort(G.begin(), G.end());
  int E = G.size();
  UnionFind uf(V);
  T min_cost = 0;

  for (int ei = 0; ei < E; ei++) {
    edge<T> e = G[ei];
    if (!uf.issame(e.from, e.to)) {
      min_cost += e.cost;
      uf.unite(e.from, e.to);
    }
  }

  return min_cost;
}
