        p[i].id = i;
    }
    sort(p + 1, p + n + 1, [](point a, point b) {
        return a.x < b.x;
    });
    for(int i = 1; i < n; i++) {
        edge.push_back({p[i + 1].x - p[i].x, p[i].id, p[i + 1].id});
    }
    sort(p + 1, p + n + 1, [](point a, point b) {
        return a.y < b.y;
    });
    for(int i = 1; i < n; i++) {
        edge.push_back({p[i + 1].y - p[i].y, p[i].id, p[i + 1].id});
    }
