namespace Union_find {

	class union_find {
		int n;
		std::vector<int> par;
		std::vector<int> rank;
	public:
		union_find(int _n);
		int find(int x);
		void unite(int x, int y);
		bool same(int x, int y) { return find(x) == find(y); }
	};

	union_find::union_find(int _n) :n(_n), par(_n), rank(_n, 1) {
		for (int i = 0; i < n; i++) {
			par[i] = i;
		}
	};

	int union_find::find(int x) {
		if (par[x] == x)
			return x;
		else
			return par[x] = find(par[x]);
	}

	void union_find::unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;

		if (rank[x] < rank[y])
			par[x] = y;
		else
			par[y] = x;

		if (rank[x] == rank[y])
			rank[x]++;

		return;
	}
}

