struct UF
{
	vector<int> par; // 親
	// 初期化
	UF(int n):par(n) {
		for(int i = 0; i < n; i++){
			par[i] = i;
		}
	}
	// 木の根を求める
	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}
	// xとyの属する集合を併合
	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return;
		// 木の高さが高い方を代表ノードにする
		par[x] = y;
	}
	// xとyが同じ集合ならtrue
	bool same(int x, int y) { return find(x) == find(y); }
};

vector<pair<int,pair<int,int> > > v;

int kruskal(int n)
{
	sort(ALL(v));
	UF uf(n);

	int ret = 0;

	REP(i,v.size())
	{
		pair<int,pair<int,int> > e = v[i];
		if(!uf.same(e.SE.FI,e.SE.SE))
		{
			uf.unite(e.SE.FI,e.SE.SE);
			ret += e.FI;
		}
	}
	return ret;
}


