const int maxn = 1e5 + 5;
int n;
int x[maxn];
int y[maxn];

int dj[maxn];

void init() {
    FOR(i, 0, n) dj[i] = i;
}
int find(int u) {
    return dj[u] == u ? dj[u] : dj[u] = find(dj[u]);
}
int join(int u, int v) {
    int p = find(u);
    int q = find(v);
    if (p != q) {
        dj[p] = q;
        return 1;
    }
    return 0;
}

void solve() {
    cin >> n;
    vii vx, vy;
    FOR(i, 0, n) {
        cin >> x[i] >> y[i];
        vx.pb(mp(x[i], i));
        vy.pb(mp(y[i], i));
    }
    sort(all(vx)), sort(all(vy));
    priority_queue<pair<int, pi> > pq;
    FOR(i, 0, n - 1) {
        int u = vx[i].se;
        int v = vx[i + 1].se;
        pq.push(mp(-min(abs(x[u] - x[v]), abs(y[u] - y[v])), mp(u, v)));
        u = vy[i].se;
        v = vy[i + 1].se;
        pq.push(mp(-min(abs(x[u] - x[v]), abs(y[u] - y[v])), mp(u, v)));
    }
    init();
    long long ans = 0;
    while (sz(pq)) {
        int cost = -pq.top().fi;
        int u = pq.top().se.fi;
        int v = pq.top().se.se;
        pq.pop();
        if (join(u, v)) {
            ans += cost;
        }
    }
    cout << ans << "\n";
}

