int dist(int a, int b) {
    return min(abs(p[a].first - p[b].first), abs(p[a].second - p[b].second));
}

vector<PIP> edges;
int par[MAXN], siz[MAXN];


int fi(int x) {
    if (par[x] != par[par[x]])
        par[x] = fi(par[x]);
    return par[x];
}

int uni(int a, int b) {
    a = fi(a);
    b = fi(b);

    if (a == b) return 0;

    if (siz[a] > siz[b]) {
        siz[a] += siz[b];
        par[b] = a;
    } else {
        siz[b] += siz[a];
        par[a] = b;
    }
}

