    xy.PB(MT(x, y, i));
    yx.PB(MT(y, x, i));
  }
  sort(xy.begin(), xy.end());
  sort(yx.begin(), yx.end());
  map<int, vector<pair<int, int>>> gr;
  int u, v, c;
  REP(i, n - 1){
    u = get<2>(xy[i]);
    v = get<2>(xy[i + 1]);
    c = min(abs(get<0>(xy[i + 1]) - get<0>(xy[i])), abs(get<1>(xy[i + 1]) - get<1>(xy[i])));
    gr[u].PB(MP(-c, v));
    gr[v].PB(MP(-c, u));
    u = get<2>(yx[i]);
    v = get<2>(yx[i + 1]);
    c = min(abs(get<0>(yx[i + 1]) - get<0>(yx[i])), abs(get<1>(yx[i + 1]) - get<1>(yx[i])));
    gr[u].PB(MP(-c, v));
    gr[v].PB(MP(-c, u));
  }
  bool added[n + 1]; MSET(added, false);
  LL ans = 0;
  priority_queue<pair<int, int>> pq;
  pq.push(MP(0, 0));
  while (0 < SZ(pq)){
    c = pq.top().first;
    u = pq.top().second;
    pq.pop();
    if (!added[u]){
