    vector<pair<int, pair<int, int> > > distance;
    for(int i = 0; i < n - 1; i++){
        pair<int, pair<int, int> > in;
        in.second.first = x[i].second;
        in.second.second = x[i + 1].second;
        in.first = x[i + 1].first - x[i].first;
        distance.push_back(in);
        in.second.first = y[i].second;
        in.second.second = y[i + 1].second;
        in.first = y[i + 1].first - y[i].first;
        distance.push_back(in);
    }
    long long ans = 0;
    sort(distance.begin(), distance.end());
    for(int i = 1; i < n; i++){
        while(same(distance[0].second.first, distance[0].second.second)){
            distance.erase(distance.begin(), distance.begin() + 1);
        }
        ans += (long long)distance[0].first;
        unite(distance[0].second.first, distance[0].second.second);
        distance.erase(distance.begin(), distance.begin() + 1);
    }
    cout << ans << endl;
    return 0;
}

