        return dis < D.dis;
    }
};

const int N = (int)1e5 + 9;

int pi[N];
int sz[N];

int fin(int u){
    if(pi[u]==u)
        return u;
    return pi[u]=fin(pi[u]);
}

bool merge(int a, int b){
    a=fin(a);
    b=fin(b);
    if(a==b)
        return false;
    if(sz[a] > sz[b])
        swap(a, b);
    sz[b] += sz[a];
    pi[a] = b;
    return true;
}

