  rep(i, n - 1) {
    ll cost = abs(py.at(i).first - py.at(i + 1).first);
    Node node;
    node.cost = cost;
    node.from = py.at(i).second;
    node.to = py.at(i + 1).second;
    nodes.push_back(node);
  }
  sort(all(nodes));
  UnionFind unf(n);
  ll ans = 0;
  for (const auto &node : nodes) {
    if (not unf.isSame(node.from, node.to)) {
      unf.unite(node.from, node.to);
      ans += node.cost;
    }
  }

  cout << ans << endl;

  return 0;
}

