int N;

ll prim(vector<vector<ll> > &G){
    ll ans = 0ll;
    vector<bool> used(N,false);
    priority_queue<pair<int,int>, vector<pair<int,int> >, greater<pair<int,int> > > Q;

    Q.push(make_pair(0,0));
    while(!Q.empty()){
        int u;
        ll cost_u;
        tie(cost_u, u) = Q.top(); Q.pop();

        if(used[u]) continue;
        used[u] = true;
        ans += cost_u;
        for(int j=0;j<N;j++){
            Q.push(make_pair(G[u][j], j));
        }
    }
    return ans;
}

