                        Q mochi =v[p[i]][j];
                        ll dd= mochi.first;
                        P point= mochi.second;
                        if(p[i+1]==point){
                              uu=0;
                              if(dd>d) v[p[i]][j].first=d;
                        }
                  }
                  if(uu)v[p[i]].push_back({d,p[i+1]});
            }
            if(i!=0){
                  ll d=abs(p[i].second-p[i-1].second);
                  bool uu=1;
                  rep0(j,v[p[i]].size()){
                        Q mochi =v[p[i]][j];
                        ll dd= mochi.first;
                        P point= mochi.second;
                        if(p[i-1]==point){
                              uu=0;
                              if(dd>d) v[p[i]][j].first=d;
                        }
                  }
                  if(uu)v[p[i]].push_back({d,p[i-1]});
            }
      }
      /*rep0(i,N){
            cout<<i<<"  ";
            rep0(j,v[p[i]].size()){
                  cout<<v[p[i]][j].first<<" "<<v[p[i]][j].second.first<<" "<<v[p[i]][j].second.second<<"  ";
            }
            cout<<endl;
      }*/
      map<P,ll> d;
      map<P,bool> merged;
      rep0(i,N){
            d[p[i]]=longinf;
            merged[p[i]]=false;
      }
      d[p[0]]=0;
      priority_queue<Q,vector<Q>,greater<Q>> q;
      q.push({d[p[0]],p[0]});
      ll ans=0;
      while(q.size()){
            Q hoge = q.top();
            q.pop();
            ll di = hoge.first;
            P node = hoge.second;
            if(merged[node]) continue;
            ans+=di;
            merged[node]=true;
            for(int i=0;i<v[node].size();i++){
                  ll nd = v[node][i].first;
                  P np =v[node][i].second;
                  d[np]=min(d[np],nd);
                  q.push({d[np],np});
            }
      }
      cout<<ans<<endl;

      return 0;
}

