class Edge{
public:
  int from, to, cost;
  bool used;

  bool operator<(const Edge &b) const{
    if(cost < b.cost){
      return true;
    }else{
      return false;
    }
  }
};

int M=100000;
vector < vector < Edge > > edge;
int n;

void prim(){
  int start, index_i, index_j, add;
  vector < int > s;
  Edge min_cost;
  bool used[M]={0};

  for(int i=0; i<n; i++){
    sort(edge[i].begin(), edge[i].end());
  }

  start=0;
  s.push_back(start);
  used[start]=true;
  for(int i=0; i<n-1; i++){
    min_cost.cost=1<<31;
    min_cost.cost--;
    int sl=s.size();
    for(int j=0; j<sl; j++){
    	int l=edge[s[j]].size();
      for(int k=0; k<l; k++){
	if(used[edge[s[j]][k].to]==false && edge[s[j]][k].cost < min_cost.cost){
	  min_cost=edge[s[j]][k];
	  add=edge[s[j]][k].to;
	  index_i=s[j];
	  index_j=k;
	}
      }
    }
    edge[index_i][index_j].used=true;
    //edge[index_j][index_i].used=true;
    s.push_back(add);
    used[add]=true;
  }

}

