struct Dsu {
    vector<int> p;

    Dsu(int n): p(n) {
        iota(p.begin(), p.end(), 0);
    }

    int get(int v) {
        return v == p[v] ? v : p[v] = get(p[v]);
    }

    bool unite(int a, int b) {
        a = get(a);
        b = get(b);
        p[a] = b;
        return a != b;
    }
};

struct Edge {
    ll len;
    int a;
    int b;

    Edge(ll l, int aa, int bb): len(l), a(aa), b(bb) {}

    bool operator<(const Edge& e) const {
