int trace(int i)
{
    if (dsu[i] < 0)
        return i;
    dsu[i] = trace(dsu[i]);
    return dsu[i];
}

bool unity(int a, int b)
{
    int x = trace(a), y = trace(b);
    if (x == y)
        return 0;
    if (dsu[x] > dsu[y])
        swap(x, y);
    dsu[x] += dsu[y];
    dsu[y] = x;
    return 1;
}

