LL ans;

inline int Find(int u)
{
	if(par[u]!=u) return par[u]=Find(par[u]); else return u;
}

inline int merge(int u,int v)
{
	u=Find(u);
	v=Find(v);

	if(u==v) return 0;
	else
	{
		par[u]=v;
		return 1;
	}
}

inline int calc(int u,int v)
{
	return min(abs(x[u]-x[v]),abs(y[u]-y[v]));
}

int main()
{
	SF("%d",&n);
	rep(i,n)
	{
		SF("%d%d",&x[i],&y[i]);

		sortx[i]={x[i],i};
		sorty[i]={y[i],i};
		par[i]=i;
	}

	sort(sortx,sortx+n);
	sort(sorty,sorty+n);

	rep(i,n)
		s.insert({calc(sortx[i].sc,sortx[i+1].sc),{sortx[i].sc,sortx[i+1].sc}}),
		s.insert({calc(sorty[i].sc,sorty[i+1].sc),{sorty[i].sc,sorty[i+1].sc}});

	while(!s.empty())
	{
		pair<int,pair<int,int> > node=*(s.begin());s.erase(node);

		int v=node.sc.fs,u=node.sc.sc;
		ans+=LL(merge(u,v)*calc(u,v));
	}

	PF("%lld",ans);

	return 0;
}
