    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            ll cost = min(abs(towns[i].first - towns[j].first), abs(towns[i].second-towns[j].second));
            G[i][j] = cost;
        }
    }
    cout << prim() << endl;
    return 0;
}

