struct UnionFind {
    // 根には要素数を負の値で格納
    UnionFind(size_t n) : uni(n, -1), n_set(n) {}

    size_t size() const { return uni.size(); }

    // 集合の個数
    size_t set_count() const { return n_set; }

    int root(int x) {
        if(uni[x] < 0) return x;
        return uni[x] = root(uni[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if(rx != ry) {
            // 要素数が大きい方を根とする
            // (rx が根となる)
            if(uni[rx] > uni[ry])
                swap(rx,ry);
            uni[rx] += uni[ry];
            uni[ry] = rx;
            --n_set;
        }
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    vector<int> uni;
    size_t n_set;
};

/**
 * クラスカル法 (UnionFind が必要)
 *
 * 頂点数 n のグラフの辺集合 es から最小全域木を求め、それを構成する辺
 * 集合を返す。
 * es は関数内部でコストの昇順にソートされる。
 * 入力グラフが連結でない場合、結果は最小全域森となる。
 *
 * 最大全域木を求めたければ、辺のコストを符号反転すること。
 */
struct Edge {
    i64 from;
    i64 to;
    i64 cost;
    Edge(i64 f, i64 t, i64 c) : from(f), to(t), cost(c) {}
};
vector<Edge> kruskal(i64 n, vector<Edge>& es) {
    ALL(sort, es, [](const auto& lhs, const auto& rhs) {
        return lhs.cost < rhs.cost;
    });

    vector<Edge> res;
    res.reserve(n-1);

    UnionFind uf(n);
    for(const auto& e : es) {
        if(uf.same(e.from, e.to)) continue;
        res.emplace_back(e);
        uf.unite(e.from, e.to);
    }

    return res;
}

i64 N;
vector<i64> X;
vector<i64> Y;

vector<Edge> E;

i64 cost(i64 x1, i64 y1, i64 x2, i64 y2) {
    return min(abs_diff(x1,x2), abs_diff(y1,y2));
}

void solve() {
    E.reserve(N*N);
    REP(i, N) FOR(j, i+1, N) {
        E.emplace_back(i, j, cost(X[i], Y[i], X[j], Y[j]));
    }

    vector<Edge> mst = kruskal(N, E);

    i64 ans = 0;
    for(const auto& e : mst) {
        ans += e.cost;
    }
    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/) {
    RD(N);
    X.resize(N);
    Y.resize(N);

    REP(i, N) {
        RD(X[i]);
        RD(Y[i]);
    }

    solve();

    EXIT();
}

