inline int Find(R int x)
{
	return Fa[x] == x ? x : Fa[x] = Find(Fa[x]);
}
inline bool cmp1(const Poi &a, const Poi &b)
{
	return a.x < b.x;
}
inline bool cmp2(const Poi &a, const Poi &b)
{
	return a.y < b.y;
}
