const int N = 1e5 + 5;

ll dist[N];
vector<pair<ll, int>> node[N];
map<pii, int> idx;
set<pair<ll, int>> st;
vector<pii> vec;

int n, curr = 1;
ll dijkstra(int hoba)
{

	st.insert(
	{ 0, hoba });
	ll mx = 0;
	while (!st.empty())
	{
		int a = (*st.begin()).second;

		ll cost = (*st.begin()).first;

		st.erase(st.begin());

		if (dist[a] != -1)
			continue;
		dist[a] = cost;

		for (auto i : node[a])
		{
			if (dist[i.second] == -1)
				st.insert(
				{ cost + i.first, i.second });
		}
	}

	return mx;
}

int main()
{
	ios_base::sync_with_stdio(0);
	cin.tie(0);
	cin >> n;
	vec.resize(n);
	rep(i, 0, n)
	{
		int a, b;
		cin >> a >> b;

		if (!idx[
		{ a, b }])
			idx[
			{ a, b }] = curr++;
		vec[i] =
		{	a, b};
	}

	sort(all(vec));

	rep(i, 0, n-1)
	{
		int a = idx[vec[i]], b = idx[vec[i + 1]];
		int val = min(abs(vec[i].first - vec[i + 1].first),
				abs(vec[i].second - vec[i + 1].second));

		node[a].push_back(
		{ val, b });
		node[b].push_back(
		{ val, a });
	}

	rep(i, 0, n)
		swap(vec[i].first, vec[i].second);

	sort(all(vec));
	reset(dist, -1);
	rep(i, 0, n-1)
	{
		int a = idx[
		{ vec[i].second, vec[i].first }], b = idx[
		{ vec[i + 1].second, vec[i + 1].first }];

		int val = min(abs(vec[i].first - vec[i + 1].first),
				abs(vec[i].second - vec[i + 1].second));

		node[a].push_back(
		{ val, b });
		node[b].push_back(
		{ val, a });
	}
	ll sum = 0;
	rep(i, 1, curr)
	{
		if (dist[i] == -1)
			sum += dijkstra(i);
	}

	vector<ll> vec;

	rep(i, 1, curr)
		vec.push_back(dist[i]);

	sort(all(vec));

	rep(i, 0, sz(vec)-1)
		sum += vec[i];
	cout << sum << endl;
	return 0;
}

