struct edge
{
	ll from, to, cost;

	edge( ll from, ll to, ll cost )
	:	from(from), to(to), cost(cost)
	{}
};

struct UnionFind
{
	std::vector<int> data;

	UnionFind( int size )
	:	data(size, -1)
	{}

	bool unite(int x, int y)
	{
		x = root(x); y = root(y);

		if (x != y)
		{
			if (data[y] < data[x])
				std::swap(x, y);
			data[x] += data[y];
			data[y] = x;
		}

		return x != y;
	}

	bool same( int x, int y )
	{
		return root(x) == root(y);
	}

	int root(int x)
	{
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
};

int N;
