  for(int i = 0; i < tot && cnt < n; i++){
    int f = find(e[i].u);
    int t = find(e[i].v);
    if(f!=t){ans+=e[i].cost;p[f] = t;cnt++;}
  }
  printf("%lld\n", ans);
