	add(xp);
	add(yp);

	sort(ev.begin(),ev.end());

	lli ans = 0;
	REP(i,n)pa[i]=i;
	for(auto &e:ev){
		if(merge(e.u,e.v)){
			ans += e.w;
		}
	}

	cout<<ans<<endl;

	return 0;
}

