	for (int i = 0; i < V; ++i)
	{
		mincost[i] = 9999999999999;
	}
	memset(used, 0, V * sizeof(bool));
	mincost[0] = 0;
	priority_queue<P, vector<P>, greater<P> > que;
	que.push(P(0, 0));  
	while (!que.empty())
	{
		P p = que.top(); que.pop();
		LL v = p.second;  
		if (used[v] || p.first > mincost[v]) continue;
		used[v] = true;
		res += 1LL*mincost[v];
