		dy[i] = Q(P(y, x), i);
	}
	sort(dx.begin(), dx.end());
	sort(dy.begin(), dy.end());
	V = n;
	E = 0;
	for (long long int i = 1; i < n; i++) {
		edge e;
		e.u = dx[i-1].second;
		e.v = dx[i].second;
		e.cost = cost(dx[i-1].first, dx[i].first);
		es[E] = e;
		E++;
	}
	for (long long int i = 1; i < n; i++) {
		edge e;
		e.u = dy[i - 1].second;
		e.v = dy[i].second;
		e.cost = cost(dy[i - 1].first, dy[i].first);
		es[E] = e;
		E++;
	}
	cout << kruskal() << endl;

	return 0;
}

