typedef long long int LL;
typedef std::pair<LL, LL> P;
struct edge { LL to, cost; };

const LL inf = 1123456789012345;
LL N;
std::vector<std::pair<LL, LL>>xp, yp;
std::vector<std::vector<edge>>G;
std::vector<LL>dist;
std::map<LL, LL>tmp1, tmp2;

void dijkstra(LL s)
{
	std::priority_queue<P, std::vector<P>, std::greater<P>>que;
	std::fill(dist.begin(), dist.end(), inf);
	dist[s] = 0;
	que.push(P(0, s));
	while (!que.empty())
	{
		P p = que.top(); que.pop();
		LL v = p.second;
		if (dist[v] < p.first) { continue; }
		rep(i, G[v].size())
		{
			edge e = G[v][i];
			if (dist[e.to] > dist[v] + e.cost)
			{
				dist[e.to] = dist[v] + e.cost;
				que.push(P(dist[e.to], e.to));
			}
		}
	}
}

int main()
{
	in >> N;
	std::vector<LL>x(N), y(N);
	G.resize(2 * N + 1); dist.resize(2 * N + 1);
	rep(i, N)
	{
		in >> x[i] >> y[i];
		xp.push_back(std::make_pair(x[i], i + 1));
		yp.push_back(std::make_pair(y[i], i + 1 + N));
	}
	std::sort(xp.begin(), xp.end());
	std::sort(yp.begin(), yp.end());
	rep(i, N - 1)
	{
		G[i + 1].push_back({ i + 2,abs(xp[i].first - xp[i + 1].first) });
		G[i + 2].push_back({ i + 1,abs(xp[i].first - xp[i + 1].first) });
		G[i + 1 + N].push_back({ i + 2 + N,abs(yp[i].first - yp[i + 1].first) });
		G[i + 2 + N].push_back({ i + 1 + N,abs(yp[i].first - yp[i + 1].first) });
	}
	rep(i, N)
	{
		tmp1[xp[i].first] = i + 1;
		tmp2[yp[i].first] = i + 1 + N;
	}
	rep(i, N)
	{
		G[tmp1[x[i]]].push_back({ tmp2[y[i]],0 });
		G[tmp2[y[i]]].push_back({ tmp1[x[i]],0 });
	}
	G[0].push_back({ tmp1[x[0]],0 });
	G[0].push_back({ tmp2[y[0]],0 });
