ll dijkstra(vector<Edge>* g, ll n){ 
    ll sum = 0;

    priority_queue<Node> que;
    que.push({0, 0});
    vector<ll> res(n, 1e10);
    ll cnt = 0;
    while(!que.empty() && cnt < n){
        Node n = que.top(); que.pop();
        if(res[n.pos] == 1e10){
            res[n.pos] = n.cost;
            cnt++;
        }
        else    continue;

        for(auto e : g[n.pos]){
            que.push({e.to, e.cost});
        }
    }

    for(auto e : res)   sum += e;

    return sum;
}

