void makeset(int x){
    par[x] = x;
    rnk[x] = 1;
}
int get(int x){
    if(par[x] == x) return x;
    return (par[x] = get(par[x]));
}
void unite(int x, int y){
    int xr = get(x);
    int yr = get(y);
    if(xr == yr) return;
    if(rnk[xr] > rnk[yr]){
        par[yr] = xr;
        rnk[xr] += rnk[yr];
    } else {
        par[xr] = yr;
        rnk[yr] += rnk[xr];
    }
}
struct edge{
    int val, u, v;
    edge(){

    }
    edge(int _val, int _u, int _v){
        val = _val;
        u = _u;
        v = _v;
    }
