        e.val = ysorted[i + 1].first - ysorted[i].first;
        e.u = ysorted[i + 1].second;
        e.v = ysorted[i].second;
        edges.push_back(e);
    }
    sort(edges.begin(), edges.end());
    for(int i = 1; i <= n; i++) makeset(i);
    long long ans = 0;
    for(auto ed : edges){
