};

int cost (pos a, pos b) {
  return min(abs(a.x - b.x), abs(a.y - b.y));
}

int cost (vector<pos> g, pos a) {
  int mc = cost(g[0], a);
  for (pos p : g) {
    int tc = cost(p, a);
    if (tc < mc) {
      mc = tc;
    }
  }
  return mc;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  long n;
