  vector<pos> cs(n);

  for (int i = 0; i < n; i++) {
    cin >> cs[i].x >> cs[i].y;
  }

  vector<pos> g;

  g.push_back(cs[0]);
  cs.erase(cs.begin());

  int total_cost = 0;

  while(cs.size() > 0) {
    int mc = cost(g, cs[0]);
    int mi = 0;
    for (int i = 0; i < cs.size(); i++) {
      int tc = cost(g, cs[i]);
      if (tc < mc) {
        mi = i;
        mc = tc;
      }
    }

    total_cost += mc;
    g.push_back(cs[mi]);
    cs.erase(cs.begin() + mi);
  }

  cout << total_cost << endl;
  return 0;
}

