    }
    bool unite(int i, int j) {
        if ((i = root(i)) == (j = root(j))) return false;
        if (p[i] > p[j]) swap(i, j);
        p[i] += p[j]; p[j] = i;
        return true;
    }
    int kruskal() {
        p.assign(n, -1);
        sort(all(edges), [](edge x, edge y) {
            return x.weight < y.weight;
        });
        int result = 0;
        for (auto e: edges)
            if (unite(e.src, e.dst))
                result += e.weight;
        return result;
    }
};


