class UnionFind
{
private:
	vector<int> v;

public:
	UnionFind(int n)
	{
		v = vector<int>(n, -1);
	}

	int getparent(int x)
	{
		if(v[x] == -1) return x;
		return v[x] = getparent(v[x]);
	}

	bool add(int x, int y)
	{
		x = getparent(x);
		y = getparent(y);
		if(x == y) return false;
		if(x > y) swap(x, y);
		v[y] = x;
		return true;
	}
};

