int root(int v) { return (par[v] < 0) ? v : (par[v] = root(par[v])); }

void kruskal() {
   sort(E.begin(), E.end(), cmp);
   for (int i = 1; i <= n; ++i) par[i] = -1;
   int Count = 0; LL ans = 0;

   for (int i = 0; i < E.size(); ++i) {
      if (Count == n-1) break;

      int u = E[i].u, v = E[i].v;
      if ((u = root(u)) == (v = root(v))) continue;

      if (par[u] > par[v]) swap(u, v);
      par[u] += par[v]; par[v] = u;

      ans += E[i].w; Count++;
   }

   cout << ans << '\n';
}

