	ll from;
	ll to;
	ll cost;
	edge() {}
	edge(ll from, ll to, ll cost) :from(from), to(to), cost(cost) {}
	bool operator< (const edge& o) const{
		return o.cost < cost; // 昇順
	}
};

#define rep(i,n) for (int i=0; i < int(n); i++)

// 素集合データ構造
struct UnionFind
{
	// par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
	vector<int> par;
	// sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
	vector<int> sizes;

	UnionFind(int n) : par(n), sizes(n, 1) {
		// 最初は全てのデータiがグループiに存在するものとして初期化
		rep(i, n) par[i] = i;
	}

	// データxが属する木の根を得る
	int find(int x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
	}

	// 2つのデータx, yが属する木をマージする
	void unite(int x, int y) {
		// データの根ノードを得る
		x = find(x);
		y = find(y);

		// 既に同じ木に属しているならマージしない
		if (x == y) return;

		// xの木がyの木より大きくなるようにする
		if (sizes[x] < sizes[y]) swap(x, y);

		// xがyの親になるように連結する
		par[y] = x;
		sizes[x] += sizes[y];
		// sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい
	}

	// 2つのデータx, yが属する木が同じならtrueを返す
	bool same(int x, int y) {
		return find(x) == find(y);
	}

	// データxが含まれる木の大きさを返す
	int size(int x) {
		return sizes[find(x)];
	}
};

int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
	ll N; cin >> N;
	vector<pair<pll,int>> P1(N);
	vector<pair<pll,int>> P2(N);
	for (int i = 0; i < N;i++) {
		ll x, y; cin >> x >> y;
		P1[i] = { { x,y },i };
		P2[i] = { { y,x },i };
	}
	sort(P1.begin(), P1.end());
	sort(P2.begin(), P2.end());
	//vector<vector<ll>> G(N, vector<ll>(N,0));
	priority_queue<edge> pq;
	for (int i = 0; i < N - 1;i++) {
		ll cost1 = min(P1[i + 1].first.first - P1[i].first.first, abs(P1[i + 1].first.second - P1[i].first.second));
		ll cost2 = min(P2[i + 1].first.first - P2[i].first.first, abs(P2[i + 1].first.second - P2[i].first.second));
		pq.push(edge(P1[i].second, P1[i + 1].second, P1[i + 1].first.first - P1[i].first.first));
		pq.push(edge(P1[i].second, P1[i + 1].second, abs(P1[i + 1].first.second - P1[i].first.second)));
		pq.push(edge(P2[i].second, P2[i + 1].second, P2[i + 1].first.first - P2[i].first.first));
		pq.push(edge(P2[i].second, P2[i + 1].second, abs(P2[i + 1].first.second - P2[i].first.second)));
	}
	UnionFind uf(N);
	set<ll> used;
	ll ans = 0;
	while (!pq.empty()) {
		auto e = pq.top(); pq.pop();
		if (uf.same(e.from, e.to)) continue;
		uf.unite(e.from, e.to);
		used.insert(e.from); used.insert(e.to);
		ans += e.cost;
		if (used.size() == N)break;
	}
	cout << ans << endl;


	return 0;
}

