typedef long long ll;

struct UnionFind{
    vector<int> par, cnt;
    UnionFind(int NV){ 
        par.clear(); 
        cnt.resize(NV, 1); 
        rep(i, 0, NV) par.push_back(i);
    }
    void reset(){ 
        rep(i, 0, cnt.size()) cnt[i] = 1; 
        rep(i, 0, par.size()) par[i] = i; 
    }
    int operator[](int x) {
        if(par[x] == x){
            return x;
        }
        else{
            return par[x] = operator[](par[x]);
        }
    }
    void operator()(int x, int y) {
        x = operator[](x);
        y = operator[](y);
        if (x != y) {
            par[x] = y;
            cnt[y] += cnt[x];
        }
    }
};

