    long long cost;
    edge(int _from, int _to, long long _cost) : from(_from), to(_to), cost(_cost) {}
};

struct dsu {
    vector<int> p;
    vector<int> sz;
    int n;
    dsu(int _n)
        : n(_n) {
        p.resize(n);
        iota(p.begin(), p.end(), 0);
        sz.assign(n, 1);
    }

    inline int get(int x) {
        if (p[x] == x) {
            return x;
        } else {
            return p[x] = get(p[x]);
        }
    }
    inline bool unite(int x, int y) {
        x = get(x);
        y = get(y);
        if (x == y) {
            return false;
        }
        if (sz[x] < sz[y]) {
            swap(x, y);
        }
        p[x] = y;
        sz[y] += sz[x];
        return true;
    }
};

vector<int> min_span(vector<edge> edges, int n, long long &ans) {
    vector<int> order(edges.size());
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return edges[a].cost < edges[b].cost;
    });
    vector<int> res;
    ans = 0;
    dsu d(n);
    for (int id : order) {
        edge e = edges[id];
        if (d.get(e.from) != d.get(e.to)) {
            d.unite(e.from, e.to);
            res.emplace_back(id);
            ans += e.cost;
        }
    }
    if ((int)res.size() != n) {
        return vector<int>();
    }
    return res;
}

