  for (int i = 1 ; i <= tmp ; i++) {
    cin >> x >> y;
    p.insert({x, y});
  }
  N = 0;
  for (auto xy : p) {
    N++;
    ar_x[N] = xy.first;
    ar_y[N] = xy.second;
  }
}


void preprocess() {
  for (int i = 1 ; i <= N ; i++) {
    s_x.insert({ar_x[i], i});
    s_y.insert({ar_y[i], i});
  }
}


void solve() {
  ll ans = 0;
  set< pair < ll, int > > Q;
  vector<bool> visit(N+1, false);
  vector<ll> dist(N+1, INF);
  dist[1] = 0;
  Q.insert({0, 1});
  while (!Q.empty()) {
    int at = Q.begin()->second;
    ll d = Q.begin()->first;
    Q.erase(Q.begin());
    if (visit[at]) {
      continue;
    }
    //cerr << "At = " << at << ", D = " << d << "\n";
    ans += d;
    visit[at] = true;

    auto it = s_x.find({ar_x[at], at});
    if (it != s_x.begin()) {
      //cerr << "Getting x pred\n";
      it--;
      int nxt = it->second;
      //cerr << "Nxt = " << nxt << "\n";
      if (!visit[nxt]) {
        if (dist[nxt] > abs(ar_x[at]-ar_x[nxt])) {
          dist[nxt] = abs(ar_x[at] - ar_x[nxt]);
          Q.insert({dist[nxt], nxt});
        }
      }
      it++;
    }
    it++;
    if (it != s_x.end()) {
      //cerr << "Getting x suc\n";
      int nxt = it->second;
      //cerr << "Nxt = " << nxt << "\n";
      if (!visit[nxt]) {
        if (dist[nxt] > abs(ar_x[at]-ar_x[nxt])) {
          dist[nxt] = abs(ar_x[at] - ar_x[nxt]);
          Q.insert({dist[nxt], nxt});
        }
      }
      it--;
    }

    it = s_y.find({ar_y[at], at});
    if (it != s_y.begin()) {
      //cerr << "Getting y pred\n";
      it--;
      int nxt = it->second;
      //cerr << "Nxt = " << nxt << "\n";
      if (!visit[nxt]) {
        if (dist[nxt] > abs(ar_y[at]-ar_y[nxt])) {
          dist[nxt] = abs(ar_y[at] - ar_y[nxt]);
          Q.insert({dist[nxt], nxt});
        }
      }
      it++;
    }
    it++;
    if (it != s_y.end()) {
      //cerr << "Getting y suc\n";
      int nxt = it->second;
      //cerr << "Nxt = " << nxt << "\n";
      if (!visit[nxt]) {
        if (dist[nxt] > abs(ar_y[at]-ar_y[nxt])) {
          dist[nxt] = abs(ar_y[at] - ar_y[nxt]);
          Q.insert({dist[nxt], nxt});
        }
      }
      it--;
    }
  }
  cout << ans;
}


