//UnionFind 
struct UnionFind
{
    std::vector<ll> uni;
    ll num;
    UnionFind(ll s) : uni(s, -1),num(s) {}

    //頂点aが所属するグループ
    ll root(ll a)
    {
        if (uni[a] < 0)
        {
            return a;
        }
        return uni[a] = root(uni[a]);
    }

    //a,bをつなげる
    bool connect(ll a, ll b)
    {
        a = root(a);
        b = root(b);
        if (a == b)
        {
            return false;
        }

        if (uni[a] > uni[b])
        {
            std::swap(a, b);
        }

        uni[a] += uni[b];
        uni[b] = a;
        return true;
    }

    //a,bが同グループか確認
    bool isConnect(ll a, ll b)
    {
        return root(a) == root(b);
    }

    //aが属するグループの要素数
    ll size(ll a)
    {
        return -uni[root(a)];
    }

    //グループ数を返す
    ll groups()
    {
        std::set<ll> b;
        for (ll i = 0; i < num; i++)
        {
            b.insert(root(i));
        }
        return b.size();
    }
};

struct Edge{ll u,v,cost;};

bool comp(const Edge& e1,const Edge& e2){
    return e1.cost<e2.cost;
}

ll krustal(ll n,std::vector<Edge>& es){
    sort(all(es),comp);
    UnionFind path(n);
    ll res=0,e=es.size();
    rep(i,0,e){
        Edge temp=es[i];
        if(!path.isConnect(temp.u,temp.v)){
            path.connect(temp.u,temp.v);
            res+=temp.cost;
        }
    }
    return res;
}

