using int64 = long long;

class UnionFind {
 public:
  UnionFind(int64 n) : par_(n), sizes_(n, 1) {
    for (int64 i = 0; i < n; ++i) {
      par_[i] = i;
    }
  }

  int64 find(int64 x) {
    if (x == par_[x])
      return x;
    return par_[x] = find(par_[x]);
  }

  void unite(int64 x, int64 y) {
    x = find(x);
    y = find(y);
    if (x == y)
      return;

    if (sizes_[x] < sizes_[y])
      swap(x, y);

    par_[y] = x;
    sizes_[x] += sizes_[y];
  }

  int64 size(int64 x) {
    x = find(x);
    return sizes_[x];
  }

 private:
  vector<int64> par_;
  vector<int64> sizes_;
};

