		if (ity != vy.begin()) {
			add_edge(x[i], y[i], x[prev(ity)->ss], y[prev(ity)->ss]);
		}
		id[x[i] * MOD + y[i]] = x[i] * MOD + y[i];
	}
	sort(p, p + sz);
	ll ans = 0;
	for (int i = 0; i < sz; i++) {
		ll w = p[i].ff;
		ll u = p[i].ss.ff;
		ll v = p[i].ss.ss;
