	for(int i=0; i<n-1; ++i) {
		int a, x, y; tie(a, x, y)=p[i];
		int b, s, t; tie(b, s, t)=p[i+1];
		edges.emplace_back(min(abs(x-s), abs(y-t)), a, b);
	}
	sort(begin(p), end(p), [](auto& a, auto& b){ return get<2>(a)<get<2>(b);});
	for(int i=0; i<n-1; ++i) {
