    g.add_edge(xi[i].snd, xi[i + 1].snd, abs(xi[i].fst - xi[i + 1].fst));
    g.add_edge(yi[i].snd, yi[i + 1].snd, abs(yi[i].fst - yi[i + 1].fst));
  }
  int ret = g.kruskal();

  cout << ret << endl;
  return 0;
}

