using namespace std;

typedef pair< int, int > iP;
typedef pair< iP, int > iiP;

#define PREV(i, s) ((i - 1 + s) % s)
#define NEXT(i, s) ((i + 1) % s)

vector< iP > pp;
int prim(vector< vector< int > > &g) {
    int ret = 0;
    int s = g.size();
    priority_queue< iP, vector< iP >, greater< iP > > q;
    vector< int > v(s + 1, 0);
    q.push(iP(0, 0));
    while(!q.empty()) {
        iP p = q.top(); q.pop();
        if(v[p.second]++) continue;
        ret += p.first;
        int now = p.second;
        for(int i = 0; i < g[now].size(); i++) {
            q.push(iP(min(abs(pp[now].first - pp[g[now][i]].first), abs(pp[now].second - pp[g[now][i]].second)), g[now][i]));
        }
    }

    return ret;
}

int main() {

    int n;
    vector< iiP > g1, g2;
    vector< vector< int > > g0;

    cin >> n;
    g0.resize(n + 1);
    pp.resize(n);
    for(int i = 0; i < n; i++) {
        int x, y; cin >> x >> y;
        pp[i] = iP(x, y);
        g1.push_back(iiP(iP(x, y), i));
        g2.push_back(iiP(iP(y, x), i));
    }
    sort(g1.begin(), g1.end());
    sort(g2.begin(), g2.end());
    for(int i = 0; i < n; i++) {
        g0[i].push_back(g1[PREV(i, n)].second), g0[i].push_back(g1[NEXT(i, n)].second);
        g0[i].push_back(g2[PREV(i, n)].second), g0[i].push_back(g2[NEXT(i, n)].second);
    }

    cout << prim(g0) << endl;
}

#include<bits/stdc++.h>
using namespace std;

int N;
struct Point {
    int x, y, id;
};
vector<Point> P;

bool cmpx(Point a, Point b) {
    return a.x < b.x;
}
bool cmpy(Point a, Point b) {
    return a.y < b.y;
}

struct Edge {
    int u, v, w;
};
vector<Edge> edge;

bool cmpw(Edge a, Edge b) {
    return a.w < b.w;
}

struct DSU {
    vector<int> par, rnk;
    void init() {
        for(int i = 0; i < N; i++) {
            par.push_back(i);
            rnk.push_back(0);
        }
    }
    int f(int u) {
        if(par[u] == u) return u;
        else return par[u] = f(par[u]);
    }
    void mrg(int u, int v) {
        u = f(u);
        v = f(v);
        if(u == v) return;
        if(rnk[u] < rnk[v]) swap(u, v);
        par[v] = u;
        if(rnk[u] == rnk[v]) rnk[u]++;
    }
} dsu;

int main() {
    scanf("%d", &N);
    P.resize(N);
    for(int i = 0; i < N; i++) {
        scanf("%d %d", &P[i].x, &P[i].y);
        P[i].id = i;
    }
    sort(P.begin(), P.end(), cmpx);
    for(int i = 0; i < N - 1; i++) {
        edge.push_back( { P[i].id, P[i + 1].id, P[i + 1].x - P[i].x } );
    }
    sort(P.begin(), P.end(), cmpy);
    for(int i = 0; i < N - 1; i++) {
        edge.push_back( { P[i].id, P[i + 1].id, P[i + 1].y - P[i].y } );
    }
    sort(edge.begin(), edge.end(), cmpw);

    dsu.init();

    long long ans = 0;

    for(int i = 0; i < edge.size(); i++) {
        int u = edge[i].u;
        int v = edge[i].v;
        int w = edge[i].w;
        if(dsu.f(u) == dsu.f(v)) continue;
        ans += w;
        dsu.mrg(u, v);
    }

    printf("%lld", ans);
}

