map<pair<int,int >,int > mp;
int mincost[MAXN];		// 从集合X出发的边到每个顶点的最小权值
bool used[MAXN];		// 顶点i是否包含在集合X中
int V,m=0;					// 顶点数
// first 最短路径，second顶点编号
typedef pair<int, int> P;

LL prim()
{
	V = m;
	LL res = 0;
	memset(mincost, 0x3f, V * sizeof(int));
	memset(used, 0, V * sizeof(bool));
	mincost[0] = 0;
	priority_queue<P, vector<P>, greater<P> > que;
	que.push(P(0, 0));  
	while (!que.empty())
	{
		P p = que.top(); que.pop();
		int v = p.second;  
		if (used[v] || p.first > mincost[v]) continue;
		used[v] = true;
		res += 1LL*mincost[v];
		for (int i = 0; i < G[v].size(); ++i)
		{
			int to = G[v][i].first,cost = G[v][i].second;
			if (mincost[to] > cost)
			{
				mincost[to] = cost;
				que.push(P(mincost[to], to));
			}
		}
	}
	return res;
}
