int dist(int a, int b){
    return min(abs(p[a].first-p[b].first), abs(p[a].second-p[b].second));
}

void f(int z){
    g.insert(z); //
    c.erase(z);
    if(z-1>=0&&z-1<n){
        if(g.find(z-1)==g.end()){
            c.insert(z-1);
            d[z-1]=min(d[z-1], dist(z-1, z));
        }
    }
    if(z+1>=0&&z+1<n){
        if(g.find(z+1)==g.end()){
            c.insert(z+1);
            d[z+1]=min(d[z+1], dist(z+1, z));
        }
    }
    auto itrZ=s.find(P(p[z].second, z));
    if(itrZ!=s.end()){
        auto itrP=itrZ;
        itrP++;
        if(itrP!=s.end()){
            int zp=(*itrP).second;
            if(g.find(zp)==g.end()){
                c.insert(zp);
                d[zp]=min(d[zp], dist(zp, z));
            }
        }
        if(itrZ!=s.begin()){
            itrZ--;
            int zp=(*itrZ).second;
            if(g.find(zp)==g.end()){
                c.insert(zp);
                d[zp]=min(d[zp], dist(zp, z));
            }
        }
    }
}

