typedef pair<int, int> ii;
typedef pair<ii, int> iii;
typedef long long ll;
const ll inf = ll(1e9) + 7;

set<ii> x, y;
int mk[111111];

ii getMin(ii p){
	ii ret(inf, inf);
	auto it = x.insert(ii(p.X, -inf)).X;
	if(x.begin() != it){
		auto it2 = it;
		it2--;
		ret = min(ret, ii(abs(p.X - it2->X), it2->Y));
	}
	auto sv = it;
	it++;
	if(x.end() != it){
		ret = min(ret, ii(abs(p.X - it->X), it->Y));
	}
	x.erase(sv);
	it = y.insert(ii(p.Y, -inf)).X;
	if(y.begin() != it){
		auto it2 = it;
		it2--;
		ret = min(ret, ii(abs(p.Y - it2->X), it2->Y));
	}
	sv = it;
	it++;
	if(y.end() != it){
		ret = min(ret, ii(abs(p.Y - it->X), it->Y));
	}
	y.erase(sv);
	return ret;
}

