		y.erase(ii(p[tp.X.Y].Y, tp.X.Y));
		pq.push(iii(getMin(p[tp.Y]), tp.Y));
		pq.push(iii(getMin(p[tp.X.Y]), tp.X.Y));
	}
	cout << ans << endl;
	return 0;
}

