  bool operator < (const node &x) {
    return cost < x.cost;
  }
};
int get(int x) {
  if (p[x] == x) return x;
  return p[x] = get(p[x]);
}
bool unit(int x, int y) {
  int px = get(x), py = get(y);
  if (px == py) return 0;
  if (lvl[px] > lvl[py]) p[py] = px;
  else if (lvl[py] > lvl[px]) p[px] = py;
  else p[px] = py, lvl[px]++;
  return 1;
}
bool cmpx(pair <int, pair <int, int> > l, pair <int, pair <int, int> > r) {
  return l.s.f < r.s.f;
}
bool cmpy(pair <int, pair <int, int> > l, pair <int, pair <int, int> > r) {
