int prim() {
    priority_queue<pii> que;
    fill(used, used + MAX, false);
    que.push(pii(0, 0));
    int ret = 0;
    while (!que.empty()) {
        int  v = que.top().second;
        int cst = (-1)*(que.top().first);
        que.pop();
        if (used[v]) continue;
        used[v] = true;
        ret += cst;
        for (int i = 0; i < G[v].size(); i++)
            que.push(pii((G[v][i].first)*(-1), (G[v][i].second)));
    }
    return ret;
}
