int n;

void fInit(int n)
{
	for(int i=0;i<n;i++)
	{
		par[i]=i;
		Rank[i]=0;
	}
}

int fFind(int x)
{
	if(par[x]==x) return x;
	return par[x]=fFind(par[x]);
}

ll fUnite(int x,int y)
{
	x=fFind(x);y=fFind(y);
	if(x==y)return false;
	if(Rank[x]<Rank[y])par[x]=y;
	else
	{
		par[y]=x;
		if(Rank[x]==Rank[y])Rank[x]++;
	}
	return 1;
}

int know(int x,int y)
{
	return abs(x-y);
}

