int uni[1000010];
void init(int N){
  for(int i=0;i<N;i++){
    uni[i]=-1;
  }
}

int root(int a){
  if(uni[a] < 0)return a;
  else return uni[a] = root(uni[a]);
}
bool unite(int a,int b){
  a = root(a);
  b = root(b);
  if(a==b) return false;
  if(uni[a] > uni[b]) swap(a,b);
  uni[a]+=uni[b];
  uni[b]=a;
}
bool same(int a,int b){
  return root(a)==root(b);
}

