vll FactM(1, 1);
vll FactMI(1, 1);

ll PowM(ll a, ll b) {
	ll ans = 1, x = (a%MOD);
	FOR(i, 0, DigN2(b) - 1) {
		if (Dig2(b, i) == 1) ans = (ans*x) % MOD;
		if (i != (DigN2(b) - 1)) x = (x*x) % MOD;
	}
	return ans;
}

ll Mod(ll a) {
	a %= MOD;
	a = (a + MOD) % MOD;
	return a;
}

ll InvM(ll a) {
	a = Mod(a);
	a = PowM(a, MOD - 2);
	return a;
}

void CFactM(ll n) {
	if (FactM.sz <= n) {
		FOR(i, FactM.sz, n) {
			FactM.pb((FactM[i - 1] * (i%MOD)) % MOD);
		}
	}
	return;
}

void CFactMI(ll n) {
	CFactM(n);
	if (FactMI.sz < (n + 1)) FactMI.res(n + 1, -1);
	if (FactMI[n] == -1) FactMI[n] = PowM(FactM[n], MOD - 2);
	rFOR(i, 1, n - 1) {
		if (FactMI[i] != -1) break;
		FactMI[i] = ((FactMI[i + 1] * ((i + 1) % MOD)) % MOD);
	}
	return;
}

ll CombM(ll n, ll k) {
	if ((n < 0) || (k < 0)) return 0;
	if (n < k) return 0;
	if (n + 1 > FactMI.sz) CFactMI(n);
	return ((((FactMI[k] * FactMI[n - k]) % MOD)*FactM[n]) % MOD);
}

ll LIS(vll v, ll m = 0) {
	if (v.sz > 0) {
		ll ans = 0;
		vll dp(v.sz, INF);
		FOR(i, 0, v.sz - 1) {
			dp[m ? UPB(dp, v[i]) : LOWB(dp, v[i])] = v[i];
		}
		FOR(i, 0, v.sz - 1) {
			if (dp[i] == INF) break;
			ans++;
		}
		return ans;
	}
	else {
		return 0;
	}
}

void cmprs(vll& v) {
	if (v.sz == 0) return;
	vll vv(v);
	IOTA(vv, 0);
	sort(vv.bgn, vv.en, [&](ll v1, ll v2) {return v[v1] < v[v2]; });
	IOTA(v, 0);
	sort(v.bgn, v.en, [&](ll v1, ll v2) {return vv[v1] < vv[v2]; });
	return;
}

ll BblCnt(vll v) {
	cmprs(v);
	BIT b(v.sz);
	ll ans = 0;
	REP(i, v.sz) {
		ans += (i - b.sum(v[i]));
		b.add(v[i], 1);
	}
	return ans;
}

signed main() {
  ll n,xx,yy,d,r=0; // rは最終的に出力したい変数
  cin >> n;
  vpl4 x(n),y(n),l(n); // x座標と街番号のペア, y座標と街番号のペア, i番目の街のx・y座標
  vll c(2*n-2); // i番目のどの木に属しているか(i番目の初期値はi)
  IOTA(c,0); // ↑の初期値設定

  // x座標とy座標それぞれについてソートする
  REP(i,n){
    cin >> xx >> yy;
    x[i] = mp(xx,i);
    y[i] = mp(yy,i);
    l[i] = mp(xx,yy);
  }
  SORT(x);
  SORT(y);

  // x座標が近いもの、y座標が近いもの同士で辺をつくりsにいれる
  vector<pair<ll,pair<ll,ll> > > s; // 各辺について、座標の差(=コストである可能性が高い)と「街番号のペア」のペア
  REP(i,n-1){
    s.pb(mp(x[i+1].fi-x[i].fi,mp(x[i].se,x[i+1].se)));
  }
  REP(i,n-1){
    s.pb(mp(y[i+1].fi-y[i].fi,mp(y[i].se,y[i+1].se)));
  }

  // sを「座標の差」順にソート
  SORT(s);

  // 違う木に属している(=cの値が異なる)ときは、rにコストを追加した上でcの値を更新していく
  REP(i,2*n-2){
    if(c[s[i].se.fi]!=c[s[i].se.se]){
      r+=s[i].fi;
      d=c[s[i].se.se];
      REP(j,2*n-2){
        if(c[j]==d)c[j]=c[s[i].se.fi];
      }
    }
  }
  cout << r;
  return 0;
}

