int parent(int x){
   if(p[x] == x)
       return x;
   return p[x] = parent(p[x]);
}
bool isConnected(int x , int y){
   return parent(x) == parent(y);
}
void connect(int x , int y){
   if(isConnected(x,y))
       return;
   int pOfx = parent(x);
   int pOfy = parent(y);
   if(rnk[pOfx] > rnk[pOfy]){
       p[pOfy] = pOfx;
   }else if(rnk[pOfy] > rnk[pOfx]){
       p[pOfx] = pOfy;
   }else{
       p[pOfy] = pOfx;
       rnk[pOfx]++;
   }
}
void preDSU(){
   for(int i = 0;i<N;i++){
       p[i] = i;
   }
}

