    if(x==y){
        return;
    }
    if(rrank[x]<rrank[y]){
        ppar[x]=ppar[y];
    }else{
        ppar[y]=x;
        if(rrank[x]==rrank[y]){
            rrank[x]++;
        }
    }
}
