        this->id = id;
        this->x = x;
        this->y = y;
    }
};

struct Edge {
    int id;

    Point p1, p2;

    Edge() {
        this->id = id;
        this->p1 = Point();
        this->p2 = Point();
    }

    Edge(int id, Point p1, Point p2) {
        this->id = id;
        this->p1 = p1;
        this->p2 = p2;
    }

    int getLength() {
        return min(abs(p1.x - p2.x), abs(p1.y - p2.y));
    }

    friend bool operator < (Edge e1, Edge e2) {
        if (e1.getLength() < e2.getLength()) {
            return true;
        }

        if (e1.getLength() > e2.getLength()) {
            return false;
        }

        return e1.id < e2.id;
    }
};

