    REP(i,n-1){
        pq.push(mp(x[i+1].first-x[i].first,mp(x[i].second,x[i+1].second)));
        pq.push(mp(y[i+1].first-y[i].first,mp(y[i].second,y[i+1].second)));
    }
    UnionFind uf = UnionFind(n);
