  std::vector<bool> checked(N, false);
  long long int sumCost = 0;

  for(auto it = cost.begin(), end = cost.end(); it != end; ++it){
    if(!checked[it->left] || !checked[it->right]){
      sumCost += it->cost;
      checked[it->left] = checked[it->right] = true;
