using namespace std;

typedef long long ll;

const int N = 1e5 + 5;
int parent[N];
int rnk[N];

int getParent(int x)
{
  if(parent[x] == x)
    return x;
  return parent[x] = getParent(parent[x]);
}

void connect(int x, int y)
{
  x = getParent(x), y = getParent(y);
  if(x == y)
    return;
  if(rnk[x] <= rnk[y])
  {
    parent[x] = y;
    rnk[y] += rnk[x];
  }
  else
  {
    parent[y] = x;
    rnk[x] += rnk[y];
  }
}

bool isconnected(int x, int y)
{
  return getParent(x) == getParent(y);
}

int main()
{
