};

struct queInfo {
	queInfo(int a, int b) {
		idx = a;
		cost = b;
	}
	int idx;
	int cost;
};

bool cmpZahyou(P &a, P &b)
{
	return a.second < b.second;
}

// メイン
int main()
{
	int N;
	vector<P> zahyouX;
	vector<P> zahyouY;

	// 入力
	cin >> N;
	REP(i, N) {
		int x, y;
		cin >> x >> y;
		zahyouX.push_back(make_pair(i, x));
		zahyouY.push_back(make_pair(i, y));
	}

	// X方向のリスト
	static vector<edge> G[N_MAX];
	sort(zahyouX.begin(), zahyouX.end(), cmpZahyou);
	REP(i, N - 1) {
		int prevIdx = zahyouX[i].first;
		int nextIdx = zahyouX[i + 1].first;
		int kyori = zahyouX[i + 1].second - zahyouX[i].second;
		G[prevIdx].push_back(edge(nextIdx, kyori));
		G[nextIdx].push_back(edge(prevIdx, kyori));
	}

	// Y方向のリスト
	sort(zahyouY.begin(), zahyouY.end(), cmpZahyou);
	REP(i, N - 1) {
		int prevIdx = zahyouY[i].first;
		int nextIdx = zahyouY[i + 1].first;
		int kyori = zahyouY[i + 1].second - zahyouY[i].second;
		G[prevIdx].push_back(edge(nextIdx, kyori));
		G[nextIdx].push_back(edge(prevIdx, kyori));
	}

	// プライオリティーキュー（昇順、0,0から）
	auto pqCmp = [](queInfo a, queInfo b) { return a.cost > b.cost; };	// greaterがないので代わり
	priority_queue<queInfo, vector<queInfo>, decltype(pqCmp)> que;
	que.push(queInfo(0, 0));

	// プリム法
	QWORD ans = 0;
	vector<bool> isUsed(N, false);
	vector<DWORD> minCost(N, MAX_DWORD);
	while (!que.empty()) {
		// 一番小さいのからとれる
		queInfo point = que.top();
		que.pop();
		if (isUsed[point.idx]) {
			// すでに使用済み
			continue;
		}
		if (minCost[point.idx] < point.cost) {
			// もっと小さいのが入ってる
			continue;
		}

		// 頂点採用
		ans += point.cost;
		isUsed[point.idx] = true;

		for (auto egdeOne : G[point.idx]) {
			int nextCost = egdeOne.cost;
			if (minCost[egdeOne.to] > nextCost) {
				minCost[egdeOne.to] = nextCost;
				que.push(queInfo(egdeOne.to, nextCost));
			}
		}
	}

	cout << ans;
	cout << endl;
	return 0;
}

