using namespace std;

struct LessFirst {
    bool operator()(const pair<long, int>& x, const pair<long, int>& y) const
    {
        return x.first < y.first;
    }
};

using PairSet = set<pair<long, int>, LessFirst>;

tuple<long, int, int> findMin(const PairSet& S,
                              const PairSet& T)
{
    if (S.size() > T.size()) {
        long diff;
        int s, t;
        tie(diff, t, s) = findMin(T, S);
        return make_tuple(diff, s, t);
    }

    long bdiff = numeric_limits<long>::max();
    int bs = -1;
    int bt = -1;

    for (auto pr : S) {
        long vs;
        int s;
        tie(vs, s) = pr;

        PairSet::const_iterator lb, ub;
        tie(lb, ub) = T.equal_range({vs, -1});

        if (lb != ub) {
            bdiff = 0;
            bs = s;
            bt = lb->second;
            break;
        }

        if (lb != T.begin()) {
            --lb;
            if (bdiff > vs - lb->first) {
                bdiff = vs - lb->first;
                bs = s;
                bt = lb->second;
            }
        }

        if (ub != T.end()) {
            if (bdiff > ub->first - vs) {
                bdiff = ub->first - vs;
                bs = s;
                bt = ub->second;
            }
        }
    }

    return make_tuple(bdiff, bs, bt);
}

int main()
{
    int N;
    cin >> N;
    vector<long> X(N);
