    for (int i = 0; i < N; ++i)
        cin >> X[i] >> Y[i];

    set<int> added;
    set<int> notAdded;

    added.insert(0);
    for (int i = 1; i < N; ++i) {
        notAdded.insert(i);
    }

    PairSet addedX;
    PairSet notAddedX;
    addedX.insert({X[0], 0});
    for (int i = 1; i < N; ++i) {
        notAddedX.insert({X[i], i});
    }

    PairSet addedY;
    PairSet notAddedY;
    addedY.insert({Y[0], 0});
    for (int i = 1; i < N; ++i) {
        notAddedY.insert({Y[i], i});
    }

    long total = 0;
    while ((int)added.size() < N) {
        long xdiff;
        int xs, xt;
        tie(xdiff, xs, xt) = findMin(addedX, notAddedX);

        long ydiff;
        int ys, yt;
        tie(ydiff, ys, yt) = findMin(addedY, notAddedY);

        long diff = xdiff;
        //int s = xs;
        int t = xt;
        if (ydiff < xdiff) {
            diff = ydiff;
            // s = ys;
            t = yt;
        }

        total += diff;
        notAdded.erase(t);
        added.insert(t);
        notAddedX.erase({X[t], t});
        addedX.insert({X[t], t});
        notAddedY.erase({Y[t], t});
        addedY.insert({Y[t], t});
    }

    cout << total << '\n';

    return 0;
}

