    cin >> c[i].x >> c[i].y;
	c[i].id = i;
	}
    sort(c + 1 , c + n + 1 ,cmpx);
    for(int i = 1; i < n; ++i) edge.push_back(make_pair(c[i+1].x-c[i].x,make_pair(c[i+1].id,c[i].id)));
    sort(c + 1, c + n + 1, cmpy);
    for(int i = 1; i < n; ++i) edge.push_back(make_pair(c[i+1].y-c[i].y,make_pair(c[i+1].id,c[i].id)));
