	for (int i = 1; i < Y.size(); i++)Z.push_back(make_tuple(Y[i].first - Y[i - 1].first, Y[i].second, Y[i - 1].second));
	sort(Z.begin(), Z.end());
	QuickUnionFind UF(n); long long ret = 0;
	for (int i = 0; i < Z.size(); i++) {
