			fa[i]=i;
	}

	inline int Find(int a)
	{
		if(fa[a]!=a)
			return fa[a]=Find(fa[a]);
		return a;
	}

	inline void Union(int a,int b)//Add Edge a->b
	{
		a=Find(a);
		b=Find(b);
		if(a!=b)
			fa[a]=b;
	}
}rowl,rowr,coll,colr;

