	if(left>=1)
	{
//		printf("Case 1:%d %d\n",p,left);
		rowl.Union(p,left);
		Q.push(mp(-row[p].first+row[left].first,row[left].second));
	}
	if(right<=n)
	{
//		printf("Case 2: %d %d\n",p,right);
		rowr.Union(p,right);
		Q.push(mp(-row[right].first+row[p].first,row[right].second));
	}

	p=yp[cur];
	left=coll.Find(p-1),right=colr.Find(p+1);
	if(left>=1)
	{
