		v[i] = pi(P(y,x),i);
	}
	sort(all(u)), sort(all(v));
	rep(i,n-1){
		kr.add_edge(u[i].se,u[i+1].se,min(abs(u[i].fi.fi-u[i+1].fi.fi),abs(u[i].fi.se-u[i+1].fi.se)));
