	{
		return par[x] = find(par[x]);
	}
}

void unite(int x,int y)
{
	x = find(x);
	y = find(y);
	if(x == y) return;

	if(rank[x] < rank[y]){
		par[x] = y;
	} else{
		par[y] = x;
		if(rank[x] == rank[y])rank[y]++;
	}
}

