const int MAX_N = 10000;
class UnionFind {
private:
    int union_size[MAX_N];
    int rank[MAX_N];

public:
    int par[MAX_N];

    void init(int n)
    {
        for (int i=0; i<n; i++) {
            par[i]=i;
            rank[i]=0;
            union_size[i] = 1;
        }
    }

    int find(int x)
    {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }

    void merge(int x, int y)
    {
        x = find(x);
        y = find(y);
        if (x == y) return;

        union_size[x] += union_size[y];
        union_size[y] = union_size[x];

        if (rank[x] < rank[y]) {
            par[x] = y;
        } else {
            par[y] = x;
            if (rank[x] == rank[y]) rank[x]++;
        }
    }

    bool same(int x, int y)
    {
        return find(x) == find(y);
    }

    int getUnionSize(int x)
    {
        return union_size[find(x)];
    }
};

vector<Edge> G;
ll kruskal()
{
    UnionFind UF;
    sort(G.begin(), G.end());
    UF.init(N);
    ll res=0;
    for (Edge e : G) {
        if (!UF.same(e.u, e.v)) {
            UF.merge(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}

