		edges.emplace_back(p[i].id, p[i - 1].id);
	}
	sort(p, p + n, cmp2);
	for (int i = 1; i < n; ++i) edges.emplace_back(p[i].id, p[i - 1].id);
	buildEdges(0);
	for (int i = 0; i < n; ++i) swap(p[i].x, p[i].y);
