struct UnionFind{
	vector<int> par;
	UnionFind(int N){
		par.assign(N,0);
		rep(i,N) par[i]=i;
	}
	int find(int x){
		if(par[x]==x) return x;
		return par[x]=find(par[x]);
	}
	bool same(int x,int y){
		return find(x)==find(y);
	}
	void unite(int x,int y){
		x=find(x),y=find(y);
		if(x==y) return;
		par[y]=x;
	}
};
int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);		//DON'T USE scanf/printf/puts !!
	cout << fixed << setprecision(20);

	int N; cin >> N;
	V<int> x(N),y(N);
	rep(i,N) cin >> x[i] >> y[i];
	VV<ll> es;
	rep(_,2){
		V<int> idx(N); iota(all(idx),0);
		sort(all(idx),[&](int l,int r){return x[l]<x[r];});
		rep(i,N-1){
			int a = idx[i], b = idx[i+1];
			es.push_back({x[b]-x[a],a,b});
		}
		rep(i,N) swap(x[i],y[i]);
	}
	sort(all(es));
	UnionFind UF(N);
	ll ans=0;
	for(auto e: es){
		if(!UF.same(e[1],e[2])){
			UF.unite(e[1],e[2]);
			ans += e[0];
		}
	}
	cout << ans << endl;
}

