int Find(int x){
    return x==fa[x]?x:fa[x]=Find(fa[x]);
}

long long Kruskal(){
    for(int i=0;i<=n;i++)fa[i]=i;
    sort(E, E+cnt);
    long long ans=0;
    for(int i=0;i<cnt;i++){
        int fu=Find(E[i].u);
        int fv=Find(E[i].v);
        if(fu!=fv){
            ans+=E[i].cost;
            fa[fu]=fv;
        }
    }
    return ans;
}

