struct edge
{
    int x,y,cost;
};

struct pct
{
    int x,y,ind;
};

bool cmp1(pct a, pct b)
{
    return a.x<b.x;
}

bool cmp2(pct a, pct b)
{
    return a.y<b.y;
}

bool cmp(edge a, edge b)
{
    return a.cost<b.cost;
}

pct P[100005];
vector<edge> Edg;
int Pa[100005],Sz[100005];

int parent(int x)
{
    int cx=x;
    while(Pa[x]!=0)
        x=Pa[x];

    while(Pa[cx]!=0)
    {
        int aux=Pa[cx];
        Pa[cx]=x;
        cx=aux;
    }
    return x;
}

bool unite(int x, int y)
{
    x=parent(x);
    y=parent(y);

    if(x==y)
        return 0;

    if(Sz[x]>=Sz[y])
    {
        Sz[x]+=Sz[y];
        Pa[y]=x;
    }
    else
    {
        Sz[y]+=Sz[x];
        Pa[x]=y;
    }
    return 1;
}

