int prim(vector<vector<Edge>> g){
    int ans = 0;
    vb used(g.size(), false);
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
    pq.emplace(0, 0);
    while (!pq.empty()){
        auto p = pq.top();
        pq.pop();
        if (used[p.second]) continue;
        used[p.second] = true;
        ans += p.first;
        for (Edge &e : g[p.second]) {
            pq.emplace(e.cost, e.dest);
        }
    }
    return ans;
}

