int fpar(int a) {
  return (a == par[a] ? a : par[a] = fpar(par[a]));
}

void merge(int a, int b) {
  int pa, pb;
  pa = fpar(a);
  pb = fpar(b);
  if(pa == pb)
    return;
  if(sz[a] > sz[b])
    swap(a, b);
  par[pa] = pb;
  sz[pb] += sz[pa];
}

