struct sets
{
	int par[100010],num[100010];

	inline void INIT(int n)
	{
		rep(i,n) par[i]=i,num[i]=1;
	}

	inline int FIND(int x)
	{
		return x==par[x]?x:par[x]=FIND(par[x]);
	}

	inline bool unite(int x,int y)
	{
		x=FIND(x);
		y=FIND(y);
		if(x==y) return 0;

		if(num[x]>num[y]) swap(x,y);
		num[y]+=num[x];
		par[x]=y;
		return 1;
	}
}s;

