	REP(i, N-1){
		es.push_back({p[i].snd, p[i+1].snd, cost(p[i], p[i+1])});
	}

	sort(p, p+N, cmp2);
	REP(i, N-1){
		es.push_back({p[i].snd, p[i+1].snd, cost(p[i], p[i+1])});
	}

	Union_find uf(N);
