class UnionFind {
private:
	vector<int> parent, rank;
public:
	UnionFind(int n) {
		int i;
		for (i = 0; i < n; i++) {
			parent.push_back(i);
			rank.push_back(0);
		}
	}
	int root(int x) {
		if (parent[x] == x) return x;
		else return parent[x] = root(parent[x]);
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y) return;
		if (rank[x] < rank[y]) parent[x] = y;
		else {
			parent[y] = x;
			if (rank[x] == rank[y]) rank[x]++;
		}
	}
};
