ll nc;
ll rep[100000];
ll sz[100000];
ll maxx=1;
void StartDSU(ll n){
for(int i=0;i<=n;++i){
    rep[i]=i;
    sz[i]=1;
}
nc=n;
}
ll findu(ll u){
  if(rep[u]==u){return u;}
  else{return rep[u]=findu(rep[u]);}
}
void Join(ll a,ll b){
  a=findu(rep[a]);
  b=findu(rep[b]);
  if(a==b){return;}
  if(sz[a]<sz[b]){swap(a,b);}
  rep[b]=a;
  sz[a]+=sz[b];
  nc-=1;
  maxx=max(maxx,sz[a]);
}
