int prim(vector<vector<int> >list){
    vector<int> color(n,WHITE);
    vector<int> d(n,INFTY);
    vector<int> p(n,-1);

    d[0] = 0;

    while(true){
        int mincost = INFTY;
        int u = -1;
        for(int i=0;i<n;i++){
            if(color[i] != BLACK && d[i] < mincost){
                mincost = d[i];
                u = i;
            }
        }

        if(u == -1) break;
        color[u] = BLACK;
        for(int v=0;v<n;v++){
            if(color[v] != BLACK ){
                if(d[v] > list[u][v]){
                    d[v] = list[u][v];
                    p[v] = u;
                    color[v] = GRAY;
                }
            }
        }
    }

    int total = 0;
    for(int i=0;i<n;i++){
        if(p[i] != -1){
            total += list[i][p[i]];
        }
    }

    return total;
}

