{
	if(p[x]!=x) return p[x]=FIND(p[x]);
	return x;
}

bool UNION(int x,int y)
{
	int rx=FIND(x),ry=FIND(y);
	if(rx!=ry) 
	{
		p[rx]=p[ry];return 1;
	}
	return 0;
}

inline int dis(pii x,pii y)
