	par[x]=find(par[x]);
	return par[x];
}
bool issameset(int x,int y){
	return find(x)==find(y);
}
void Union(int x,int y){
	if(!issameset(x,y)){
		size[find(y)]+=size[find(x)];
		par[find(x)]=find(y);
	}
}
