// http://arc076.contest.atcoder.jp/tasks/arc076_b
typedef long long ll;
typedef pair<ll, ll> pll;

struct edge {
	ll from;
	ll to;
	ll cost;
	edge() {}
	edge(ll from, ll to, ll cost) :from(from), to(to), cost(cost) {}
	bool operator< (const edge& o) const{
		return o.cost < cost; // 昇順
	}
};

struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
	ll N; cin >> N;
	vector<pair<pll,int>> P1(N);
	vector<pair<pll,int>> P2(N);
	for (int i = 0; i < N;i++) {
		ll x, y; cin >> x >> y;
		P1[i] = { { x,y },i };
		P2[i] = { { y,x },i };
	}
	sort(P1.begin(), P1.end());
	sort(P2.begin(), P2.end());
	//vector<vector<ll>> G(N, vector<ll>(N,0));
	priority_queue<edge> pq;
	for (int i = 0; i < N - 1;i++) {
		ll cost1 = min(P1[i + 1].first.first - P1[i].first.first, abs(P1[i + 1].first.second - P1[i].first.second));
		ll cost2 = min(P2[i + 1].first.first - P2[i].first.first, abs(P2[i + 1].first.second - P2[i].first.second));
		pq.push(edge(P1[i].second, P1[i+1].second, cost1));
		pq.push(edge(P2[i].second, P2[i+1].second, cost2));
	}
	UnionFind uf(N);
	set<ll> used;
	ll ans = 0;
	while (!pq.empty()) {
		auto e = pq.top(); pq.pop();
		if (uf.findSet(e.from, e.to)) continue;
		uf.unionSet(e.from, e.to);
		used.insert(e.from); used.insert(e.to);
		ans += e.cost;
		if (used.size() == N)break;
	}
	cout << ans << endl;


	return 0;
}

