int ppar[200000];
int rrank[200000];

void init(int n){
    for(int i=0;i<n;i++){
        ppar[i]=i;
        rrank[i]=0;
    }
}

int find(int x){
    if(ppar[x]==x){
        return x;
    }else{
        return ppar[x]=find(ppar[x]);
    }
}

void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y){
        return;
    }
    if(rrank[x]<rrank[y]){
        ppar[x]=y;
    }else{
        ppar[y]=x;
        if(rrank[x]==rrank[y]){
            rrank[x]++;
        }
    }
}
bool same(int x,int y){
    return find(x)==find(y);
}

//kruskal
struct edge{
    int u;
    int v;
    int cost;
};

bool comp(edge& e1,edge& e2){
    return e1.cost < e2.cost;
}

edge es[200000];

int kruskal(int V,int E){//V:頂点数,E:辺数
    sort(es,es+E,comp);
    init(V);
    int res = 0;
    for(int i=0;i<E;i++){
        edge e = es[i];
        if(!same(e.u,e.v)){
            unite(e.u,e.v);
            res+=e.cost;
        }
    }
    return res;
}



