int up[100005];

void makesets()
{
	for (int i = 0; i < 100001; i++)
	{
		up[i] = -1;
	}
}

int Find(int x)
{
	if (up[x] < 0) return x;
	int root = Find(up[x]);
	up[x] = root;
	return root;
}

void Union(int x, int y)
{
	if (Find(x) == Find(y)) return;
	if (up[x] < up[y])
	{
		up[x] += up[y];
		up[y] = x;
	}
	else
	{
		up[y] += up[x];
		up[x] = y;
	}
}

