        a[i] = make_pair(i, p);
    }
    sort(a, a+n, cmp1);
    for(int i=1; i<n; i++) {
        int d = a[i].second.first - a[i-1].second.first;
        int u = a[i-1].first, v = a[i].first;
        g[v].push_back({d, u});
        g[u].push_back({d, v});
    }
    sort(a, a+n, cmp2);
    for(int i=1; i<n; i++) {
        int d = a[i].second.second - a[i-1].second.second;
        int u = a[i-1].first, v = a[i].first;
        g[u].push_back({d, v});
        g[v].push_back({d, u});
    }

    cout << MST() << endl;
}

