void gen(vector<pair<int, int> > &a, vector<pair<int, int> > &b) {

	sort(b.begin(), b.end());

	for (int i = 0; i < a.size(); i++) {

		auto it = lower_bound(b.begin(), b.end(), make_pair(a[i].first, -1));
		if (it != b.end()) {
			g[a[i].second].push_back(it->second);
			g[it->second].push_back(a[i].second);
		}
		if (it != b.begin()) {
			it--;

			g[a[i].second].push_back(it->second);
			g[it->second].push_back(a[i].second);
		}
	}
}
