viiiii edge;
int numset;
ii a[100005];
void init(int N)
{
	numset=N;
	for(int i=0 ; i<N ; i++)
	{
		p[a[i]] = a[i];
	}
}
ii find(ii i)
{
	if(p[i].fi == i.fi && p[i].se == i.se)
	return p[i];
	else return find(p[i]); 
}
bool same(ii i, ii j)
{
	ii u = find(i);
	ii v = find(j);
	if(u .fi == v .fi && u .se == v .se) return 1;
	return 0;
}
void joint(ii i, ii j)
{
	if(same(i,j)==0)
	{
		numset--;
		r[find(j)]+=r[find(i)];
		p[find(i)]=find(j);
	}
}
int size(ii i)
{
	return r[find(i)];
}
int kruskal(int V)
{
	sort(edge.begin(),edge.end());
	init(V);
	int cost = 0;
	for(int i=0 ; i < edge.size(); i++)
	{
		pair < int , pair < ii , ii > > front = edge[i];
		if(same(front.se.fi,front.se.se) == 0)
		{	
			cost += front.fi;
			joint(front.se.fi,front.se.se);
		}
	}
	return cost;
}

