int par[N],rnk[N];

void init(int n){
	for(int i = 0; i < n; ++i){
		par[i] = i;
	}
}

int find_par(int x){
	return (par[x] == x?x:par[x] = find_par(par[x]));
}

void unite(int x,int y){
	x = find_par(x);
	y = find_par(y);
	if(x != y){
		if(rnk[x] > rnk[y]){
			par[y] = x;
		}
		else{
			par[x] = y;
			rnk[y] = max(rnk[y], rnk[x] + 1);
		}
	}
}

