    SetX.insert(make_pair(x[i],i));
    SetY.insert(make_pair(y[i],i));
  }
  // 各頂点について一番安い所をつなぐ
  for (int i = 0; i < N; i++) {
    ll res = INF;
    ll num = -1;
    auto itr1 = SetX.lower_bound(make_pair(x[i],-1));
    SetX.erase(itr1);
    auto itr2 = SetY.lower_bound(make_pair(y[i],-1));
    SetY.erase(itr2);
    for (int j = 0; j < (int)Graph[i].size(); j++) {
      int s = Graph[i][j];
      auto itrx = SetX.lower_bound(make_pair(x[s],-1));
      auto itry = SetY.lower_bound(make_pair(y[s],-1));
      SetX.erase(itrx);
      SetY.erase(itry);
    }
    auto itr3 = SetX.lower_bound(make_pair(x[i],-1));
    if (itr3 != SetX.end()) {
      if (res > abs(x[i] - (*itr3).F)) {
        res = abs(x[i] - (*itr3).F);
        num = (*itr3).S;
      }
    }
    if (itr3 != SetX.begin()) {
      auto pre1 = prev(itr3,1);
      if (res > abs(x[i] - (*pre1).F)) {
        res = abs(x[i] - (*pre1).F);
        num = (*pre1).S;
      }
    }
