    if (itr4 != SetY.end()) {
      if (res > abs(y[i] - (*itr4).F)) {
        res = abs(y[i] - (*itr4).F);
        num = (*itr4).S;
      }
    }
    if (itr4 != SetY.begin()) {
      auto pre2 = prev(itr4,1);
      if (res > abs(y[i] - (*pre2).F)) {
        res = abs(y[i] - (*pre2).F);
        num = (*pre2).S;
      }
    }

    vec.push_back(res);
    SetX.insert(make_pair(x[i],i));
    SetY.insert(make_pair(y[i],i));
    for (int j = 0; j < (int)Graph[i].size(); j++) {
      int s = Graph[i][j];
      SetX.insert(make_pair(x[s],s));
      SetY.insert(make_pair(y[s],s));
    }
    Graph[i].push_back(num);
    Graph[num].push_back(i);
  }

  sort(vec.begin(),vec.end());

  ll ans = 0;
  for (int i = 0; i < (int)vec.size() - 1; i++) {
    ans += vec[i];
  }
  cout << ans << endl;
  return 0;
}

