// Union Find
struct UnionFind
{
	const LL N;
	VLL parent;
	VLL rank;

	UnionFind(LL n)
		:N(n)
	{
		parent = VLL(N);
		rank = VLL(N, 0);
		for (size_t i = 0; i < N; i++) {
			parent[i] = i;
		}
	}

	int root(LL i)
	{
		return parent[i] == i ? i : parent[i] = root(parent[i]);
	}

	bool same(LL i, LL j)
	{
		return root(i) == root(j);
	}

	void unite(LL i, LL j)
	{
		i = root(i);
		j = root(j);
		if (i == j) {
			return;
		}

		if (rank[i] < rank[j]) {
			parent[i] = j;
		}
		else {
			parent[j] = i;
			if (rank[i] == rank[j]) {
				rank[i]++;
			}
		}
	}

	bool isOne()
	{
		for (size_t i = 1; i < N; i++) {
			if (!same(0, i)) {
				return false;
			}
		}
		return true;
	}
};

