int da[200000];

int root(int x) {
	return da[x] < 0 ? x : da[x] = root(da[x]);
}
bool unionSet(int x, int y) {
	x = root(x); y = root(y);
	if (x != y) {
		if (da[y] < da[x]) swap(x, y);
		da[x] += da[y]; da[y] = x;
	}
	return  x != y;
}
bool findSet(int x, int y) {
	return root(x) == root(y);
}

int size(int x) {
	return -da[root(x)];
}

