const int MAX_E = 100 * 99 / 2; // 100C2
struct edge{ int u, v, cost; };
edge es[MAX_E];
int V, E; // 頂点数と辺数

//--------Union-Find木------------
vector<int> par; // 親
vector<int> rnk; // 深さ

// Union-Find木の初期化
void init_union_find(int n) {
  par  = vector<int>(n);
  rnk = vector<int>(n);
  for (int i = 0; i < n; i++) {
    par[i] = i;
    rnk[i] = 0;
  }
}

// 木の根を求める
int find(int x) {
  if (par[x] == x) {
    return x;
  } else {
    return par[x] = find(par[x]);
  }
}

// xとyの属する集合を併合
void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if (x == y) return;

  if (rnk[x] < rnk[y]) {
    par[x] = y;
  } else {
    par[y] = x;
    if (rnk[x] == rnk[y]) rnk[x]++;
  }
}

// xとyが同じ集合に属するか否か
bool same(int x, int y) {
  return find(x) == find(y);
}

//----------クラスカル法------------
bool comp(const edge& e1, const edge& e2) {
  return e1.cost < e2.cost;
}
int kruskal() {
  sort(es, es + E, comp); // edge.costの小さい順
  init_union_find(V); // Union-Findの初期化
  int res = 0;
  for (int i = 0; i < E; i++) {
    edge e = es[i];
    if (!same(e.u, e.v)) {
      unite(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}

int main() {
  // 初期化
  while ( cin >> V ) {
    E = V * (V-1) /2;
    int c;
    int k = 0;
    int x[V],y[V];
    for(int i=0;i<V;i++){
        cin >> x[i] >> y[i];
    }
    for(int i=0;i<V;i++){
        for(int j=0;j<i;j++){
            c=min(abs(x[i]-x[j]),abs(y[i]-y[j]));
            edge e={i,j,c};
            es[k++]=e;
        }
    }
    // 最小全域木をクラスカル法で求める
    int res = kruskal();
    // 出力
    cout << res << endl;
  }
  return 0;
}

