void go(){
	map<ll, vector<ll>> x_y;
	map<ll, vector<ll>> y_x;

	set<ll> y;
	set<ll> x;
	sort(p, p + n);
	for(int i = 0; i < n; i++){
		cin >> p[i].first >> p[i].second;
		x_y[p[i].first].push_back(p[i].second);
		y_x[p[i].second].push_back(p[i].first);
	}
	ll ans = 0;
	for(auto x : x_y[p[0].first]){
		y.insert(x);
	}
	for(auto yy : y_x[p[0].second]){
		x.insert(yy);
	}



	for(int i = 1 ; i < n; i++){
		auto cur = p[i];
		auto l = y.lower_bound(p[i].second);
		auto lll = x.lower_bound(p[i].first);

		if(l == y.end()) l--;
		if(lll == x.end()) lll--;

		if(*l != p[i].second || *lll != p[i].first){
			ll m1 = abs(p[i].second - *l);
			if(l != y.begin()){
				l--;
				m1 = min(m1, abs(p[i].second - *l));
			}

			ll m2 = abs(p[i].first - *lll);
			if(lll != x.begin()){
				lll--;
				m2 = min(m2, abs(p[i].first - *lll));
			}
			ans += min(m1, m2);
		}

		if(y.count(p[i].second) == 0){
			for(auto x : x_y[p[i].first]){
				y.insert(x);
			}
		}

		if(x.count(p[i].first) == 0){
			for(auto y : y_x[p[i].second]){
				x.insert(y);
			}
		}

	}

	answer = min(ans, answer);
}
