using ll = long long int;
typedef vector<ll> vll;
typedef vector<vll> vvll;
typedef vector<vvll> vvvll;
const int MOD=1000000007;
//const int MOD=998244353;
const int INTMAX=2147483647;
const ll LLMAX=9223372036854775807;

bool comp(vll a,vll b){
    return a[0]<b[0];
}

class UnionFind {
public:
    vector<ll> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(ll N) : par(N) { //最初は全てが根であるとして初期化
        for(ll i = 0; i < N; i++) par[i] = i;
    }

    ll root(ll x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(ll x, ll y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(ll x, ll y) { // 2つのデータx, yが属する木が同じならtrueを返す
        ll rx = root(x);
        ll ry = root(y);
        return rx == ry;
    }
};

bool comp4Kruskal(vll a,vll b){
    return a[2]<b[2];
}

//最小全域木 クラスカル O(N+MlogM)
ll kruskal(vll s,vll t,vll c,ll N){
    ll ret=0;
    vvll stc(s.size(),vll(3));
    for(ll i=0;i<s.size();i++){
        stc[i][0]=s[i];stc[i][1]=t[i];stc[i][2]=c[i];
    }

    sort(ALL(stc),comp4Kruskal);

    UnionFind uf(N);

    for(ll i=0;i<s.size();i++){
        if(!uf.same(stc[i][0],stc[i][1])){
            uf.unite(stc[i][0],stc[i][1]);
            ret+=stc[i][2];
        }
    }
    return ret;
}



int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    ll N;
    cin>>N;
    vvll x(N,vll(2)),y(N,vll(2));
    for(ll i=0;i<N;i++){
        cin>>x[i][0]>>y[i][0];
        x[i][1]=i;y[i][1]=i;
    }

    sort(ALL(x),comp);sort(ALL(y),comp);

    vvll cost(N,vll(N,LLMAX));
    for(ll i=0;i<N-1;i++){
        cost[x[i][1]][x[i+1][1]]=x[i+1][0]-x[i][0];
        cost[x[i+1][1]][x[i][1]]=x[i+1][0]-x[i][0];
    }
    for(ll i=0;i<N-1;i++){
        cost[y[i][1]][y[i+1][1]]=y[i+1][0]-y[i][0];
        cost[y[i+1][1]][y[i][1]]=y[i+1][0]-y[i][0];
    }

    vll s(2*N-2),t(2*N-2),c(2*N-2);
    for(ll i=0;i<N-1;i++){
        s[i]=x[i][1];
        t[i]=x[i+1][1];
        c[i]=x[i+1][0]-x[i][0];
    }
    for(ll i=0;i<N-1;i++){
        s[i+N-1]=y[i][1];
        t[i+N-1]=y[i+1][1];
        c[i+N-1]=y[i+1][0]-y[i][0];
    }

    cout<<kruskal(s,t,c,N)<<endl;

    return 0;
}

