struct UnionFind {
    vector<int> par;

    UnionFind(int n) : par(n, -1) { }
    void init(int n) { par.assign(n, -1); }

    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y); // merge technique
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    int size(int x) {
        return -par[root(x)];
    }
};

struct edge{
    int u,v;
    ll cost;
};
bool comp(const edge& e1,const edge& e2){
    return e1.cost<e2.cost;
}

int n,e;
edge es[200010];

int kruskal(){
    sort(es,es+e,comp);
    UnionFind uf(n+1);
    ll res=0;
    for (int i=0;i<e;i++){
        edge e1=es[i];
        if (!uf.issame(e1.u,e1.v)){
            uf.merge(e1.u,e1.v);
            res+=e1.cost;
        }

    }
    return res;
}

