class ufind
{
    vector<int> f,r;
    public:
    ufind(int n)
    {
        f.reserve(N);
        r.assign(N,1);
        for(int i=1;i<=n;++i) f[i]=i;
    }
    int find(int x)
    {
        if (x==f[x]) return x;
        else x=f[x];
    }
    bool unite(int x,int y)
    {
        x=find(x);y=find(y);
        if (x==y) return false;
        if (r[x]<r[y]) swap(x,y);
        f[y]=x;
        if (r[x]==r[y]) r[x]++;
        return true;
    }
};
