struct edge { int to; int cost; };
vector<edge> G[100100];
int mincost[100100];
int res = 0;
bool used[100100];

int prim() {
	for (int i = 0; i < 100100; i++) {
		mincost[i] = INF;
		used[i] = false;
	}
	mincost[0] = 0;

	priority_queue<P, vector<P>, greater<P>> que;
	que.push(P(0, 0));

	while (que.size()) {
		P p = que.top(); que.pop();
		int v = p.second;

		if (used[v])continue;

		used[v] = 1;

		for (int i = 0; i < G[v].size(); i++) {
			edge e = G[v][i];
			if (used[e.to])continue;
			if (mincost[e.to] > e.cost) {
				mincost[e.to] = e.cost;
				que.push(P(e.cost, e.to));
			}
		}
	}

	REP(i, n) {
		//cout << mincost[i] << endl;
		res += mincost[i];
	}
	return res;
}

