struct DisjointSet
{
	VI parent, rank;
	DisjointSet(int n) : parent(n), rank(n, 1)
	{
		for(int i = 0; i < n; ++i)
			parent[i] = i;
	}
	int find(int u)
	{
		if(parent[u] == u)
			return u;
		return parent[u] = find(parent[u]);
	}

	void merge(int u, int v)
	{
		u = find(u), v = find(v);
		if(u == v) return;

		if(rank[u] > rank[v]) swap(u, v);

		parent[u] = v;
		if(rank[v] == rank[u])
			++rank[v];
	}
};

int n;
VPII X, Y;
LL kruskal(vector<pair<LL, PII>>& edges)
{
	LL ret = 0;
	sort(ALL(edges));

	VB used(n, false);	
	DisjointSet ds(n);
	for(int i = 0; i < sz(edges); ++i)
	{
		LL cost = edges[i].first;
		int u = edges[i].second.first, v = edges[i].second.second;
		if(ds.find(u) == ds.find(v))
			continue;
		if(used[u] == true && used[v] == true)
			continue;

		ds.merge(u, v);
		used[u] = used[v] = true;
		ret += cost;
	}
	return ret;
}

LL minCost()
{
	sort(ALL(X));
	sort(ALL(Y));

	vector<pair<LL, PII>> edges;
	for(int i = 1; i < n; ++i)
	{
		LL cost = abs(X[i - 1].first - X[i].first);
		int u = X[i - 1].second, v = X[i].second;
		edges.emplace_back(pair<LL, PII>(cost, PII(u, v)));

		cost = abs(Y[i - 1].first - Y[i].first);
		u = Y[i - 1].second, v = Y[i].second;
		edges.emplace_back(pair<LL, PII>(cost, PII(u, v)));
	}

	return kruskal(edges);	
}

