struct UnionFind
{
	vector<int> par;
	vector<int> sizes;

	UnionFind(int n) : par(n), sizes(n, 1)
	{
		REP(i, n) par[i] = i;
	}

	int find(int x)
	{
		if (x == par[x]) return x;
		return par[x] = find(par[x]);  
	}


	void unite(int x, int y)
	{
		x = find(x);
		y = find(y);

		if (x == y) return;

		if (sizes[x] < sizes[y]) swap(x, y);

		par[y] = x;
		sizes[x] += sizes[y];
	}

	bool same(int x, int y)
	{
		return find(x) == find(y);
	}

	int size(int x)
	{
		return sizes[find(x)];
	}
};

struct Edge
{
	int a, b, cost;

	bool operator<(const Edge& o) const
	{
		return cost < o.cost;
	}
};

