bool cmp1(pair<PII, int> lhs, pair<PII, int> rhs){
	return lhs.fst.fst < rhs.fst.fst;
}
struct edge{ int u, v, cost; };

bool cmp2(pair<PII, int> lhs, pair<PII, int> rhs){
	return lhs.fst.snd < rhs.fst.snd;
}

int cost(pair<PII, int> lhs, pair<PII, int> rhs){
	return min(abs(lhs.fst.fst-rhs.fst.fst), abs(lhs.fst.snd-rhs.fst.snd));
}

bool cmp3(const edge& e1, const edge& e2){
	return e1.cost < e2.cost;
}


