        sx.push_back(make_pair(x, i));
        sy.push_back(make_pair(y, i));
    }

    SORT(sx);
    SORT(sy);

    Graph g;
    g.n = V;
    REP(i, V-1) {
        Edge e;
        e.a = sx[i].second;
        e.b = sx[i+1].second;
