const ll MAX = 101010;
ll par[MAX];
ll rnk[MAX];

void init(ll n) {
	for (ll i = 0; i < n; i++) {
		par[i] = i;
		rnk[i] = 0;
	}
}

ll find(ll x) {
	if (par[x] == x)
		return x;
	else
		return par[x] = find(par[x]);
}

void unite(ll x, ll y) {
	x = find(x);
	y = find(y);
	if (x == y)
		return;

	if (rnk[x] < rnk[y])
		par[x] = y;
	else {
		par[y] = x;
		if (rnk[x] == rnk[y])
			rnk[x]++;
	}
}

bool same(ll x, ll y) {
	return find(x) == find(y);
}

struct edge {
	ll u, v, cost;
	edge() {}
	edge(ll u, ll v, ll cost) : u(u), v(v), cost(cost) {}
};

bool comp(const edge& e1, const edge& e2) {
	return e1.cost < e2.cost;
}

ll kruskal(vector<edge> es, ll V) {
	ll E = es.size();
	sort(all(es), comp);
	init(V);
	ll res = 0;
	for (ll i = 0; i < E; i++) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
	return res;
}

int main() {

	cin.tie(0);
	ios::sync_with_stdio(false);

	ll N;
	cin >> N;

	typedef pair<ll, pll> pl3; // (idx, point)
	vector<pl3> pts(N);
	for (int i = 0; i < N; i++) {
		pts[i].first = i;
		cin >> pts[i].second;
	}

	vector<edge> es;

	// sort by x
	sort(all(pts), [&](const pl3& a, const pl3& b) {
		return a.second.first < b.second.first;
	});
	// add edges
	for (int i = 0; i < N - 1; i++) {
		ll cost = pts[i + 1].second.first - pts[i].second.first;
		ll v = pts[i].first, w = pts[i + 1].first;
		if (v > w)
			swap(v, w);
		es.push_back(edge(v, w, cost));
	}

	// sort by y
	sort(all(pts), [&](const pl3& a, const pl3& b) {
		return a.second.second < b.second.second;
	});
	// add edges
	for (int i = 0; i < N - 1; i++) {
		ll cost = pts[i + 1].second.second - pts[i].second.second;
		ll v = pts[i].first, w = pts[i + 1].first;
		if (v > w)
			swap(v, w);
		es.push_back(edge(v, w, cost));
	}

	cout << kruskal(es, N) << endl;

	return 0;
}

