  //vll c(2*n-2); // i番目のどの木に属しているか(i番目の初期値はi) ←外に出しました
  IOTA(c,0); // ↑の初期値設定

  // x座標とy座標それぞれについてソートする
  REP(i,n){
    cin >> xx >> yy;
    x[i] = mp(xx,i);
    y[i] = mp(yy,i);
    l[i] = mp(xx,yy);
  }
  SORT(x);
