ll nc;
ll rep[100005];
ll sz[100005];
ll maxx=1;
void StartDSU(ll n){
for(int i=0;i<=n;++i){
    rep[i]=i;
    sz[i]=1;
}
nc=n;
}
ll findu(ll u){
  if(rep[u]==u){return u;}
  else{return rep[u]=findu(rep[u]);}
}
void Join(ll a,ll b){
  a=findu(rep[a]);
  b=findu(rep[b]);
  if(a==b){return;}
  if(sz[a]<sz[b]){swap(a,b);}
  rep[b]=a;
  sz[a]+=sz[b];
  nc-=1;
  maxx=max(maxx,sz[a]);
}
vector<pair<ll,pair<ll,ll> > >edges;

ll kruskal(ll n){
 ll cost=0;
 StartDSU(n);

 for(int i=0;i<edges.size();++i){
    ll from=edges[i].second.first;
    ll to=edges[i].second.second;
    ll w=edges[i].first;
    if(findu(from)==findu(to)){continue;}
    else{
        Join(from,to);
        cost+=w;

    }
 }
 return cost;
}
