    ll n;
    cin>>n;
    ll num=0;
    vector<pair<ll,ll> >xx,yy;
    map<pair<ll,ll>,ll>id;
    for(ll i=0;i<n;++i){
        ll a,b;
        cin>>a>>b;
        pair<ll,ll>p(a,b),pp(b,a);
        xx.push_back(p);
