int tol = 0;
void addEdge(int u, int v, int w)
{
    edge[tol].u = u;
    edge[tol].v = v;
    edge[tol].w = w;
    tol ++;
}
bool cmp(Edge a, Edge b)
{
    return a.w  < b.w;
}
int find(int x)
{
    if(par[x] == -1) return x;
    return par[x] = find(par[x]);
}
int kruskal(int n)
{
    memset(par, -1, sizeof(par));
    sort(edge ,edge + tol, cmp);
    int cnt = 0, ans = 0;
    for(int i = 0; i < tol; i++)
    {
        int u = edge[i].u;
        int v = edge[i].v;
        int w = edge[i].w;
        int t1 = find(u);
        int t2 = find(v);
        if(t1 != t2)
        {
            ans += w;
            par[t1] = t2;
            cnt ++;
        }
        if(cnt == n - 1)
            break;
    }
    if(cnt < n - 1) return -1;
    return ans;
}
