};
int TDiam(BiDGraph& graph) {
	function<pii(int, int, int)> dfs = [&](int cur, int dis, int from) {
		pii Max = { dis,cur };
		REP(i, (int)graph.g[cur].size()) {
			if (graph.g[cur][i].first != from) {
				Max = max(Max, dfs(graph.g[cur][i].first, dis + graph.g[cur][i].second, cur));
			}
		}

		return Max;
	};

	pii S = dfs(0, 0, -1);
	pii G = dfs(S.second, 0, -1);

	return G.first;
}

template<typename T>
class Lazy_Segment_Tree {//0-indexed 半開
public:
	vector<T> data, lazy;
	int n;
	Lazy_Segment_Tree(int a) :n(1) {
		while (n < a) n *= 2;
		data.resize(n * 2 - 1);
		lazy.resize(n * 2 - 1);
	}

	void add(int a, int b, T ad, int num = 0, int base = 1) {
		int l = (num + 1 - base) * (n / base), r = l + n / base;
		if (a == l && b == r)
			lazy[num] += ad;
		else {
			data[num] += ad*(b - a);
			int nr = (l + r) / 2;
			if (nr > a) add(a, min(b, nr), ad, num * 2 + 1, base * 2);
			if (nr < b) add(max(a, nr), b, ad, num * 2 + 2, base * 2);
		}
	}

	T sum(int a, int b, int num = 0, int base = 1) {
		int l = (num + 1 - base) * (n / base), r = l + n / base;
		data[num] += lazy[num] * (r - l);
		if (num < n - 1) lazy[num * 2 + 1] += lazy[num], lazy[num * 2 + 2] += lazy[num];
		lazy[num] = T();
		if (a == l && b == r)
			return data[num];
		else {
			int nr = (l + r) / 2;
			T ret = T();
			if (nr > a) ret += sum(a, min(b, nr), num * 2 + 1, base * 2);
			if (nr < b) ret += sum(max(a, nr), b, num * 2 + 2, base * 2);
			return ret;
		}
	}
};
class Heavy_Light_Decomposition {
public:
	BiDGraph g, compg;
	vector<int> sz, depth, chain, par;

	int bn = 0;
	vector<int> bvn, inbn;
	vector<vector<int>> bv;

	Heavy_Light_Decomposition(BiDGraph graph, int root) :
		g(graph), compg(graph.vn), sz(graph.vn, 1), depth(graph.vn), chain(graph.vn), par(graph.vn),
		bvn(graph.vn), inbn(graph.vn) {
		getsz(root, root);
		bv.push_back(vector<int>());
		HLD(root, -1, root, 0);
	}

	int getsz(int cur, int p) {
		par[cur] = p;
		for (auto itr : g.g[cur])
			if (p != itr.first)
				depth[itr.first] = depth[cur] + 1, sz[cur] += getsz(itr.first, cur);
		return sz[cur];
	}

	void HLD(int cur, int p, int head, int num) {
		chain[cur] = head, bvn[cur] = num;
		inbn[cur] = bv[num].size(), bv[num].push_back(cur);
		pii Maxc = { -1,-1 };
		for (auto itr : g.g[cur])
			if (itr.first != p)
				Maxc = max(Maxc, { sz[itr.first], itr.first });


		for (auto itr : g.g[cur])
			if (itr.first != p) {
				int nb = num;
				if (itr.first != Maxc.second) {
					bv.push_back(vector<int>());
					nb = ++bn;
				}
				HLD(itr.first, cur, itr.first == Maxc.second ? head : itr.first, nb);
			}
	}


	int lca(int a, int b) {
		if (chain[a] == chain[b]) return depth[a] < depth[b] ? a : b;
		if (depth[chain[a]] > depth[chain[b]])
			return lca(par[chain[a]], b);
		return lca(a, par[chain[b]]);
	}

	void for_each_edge(int a, int b, function<void(int, int)> func) {
		if (chain[a] == chain[b]) return func(inbn[a] < inbn[b] ? a : b, inbn[a] < inbn[b] ? b : a);
		if (depth[chain[a]] < depth[chain[b]]) swap(a, b);
		for_each_edge(a, chain[a], func), for_each_edge(par[chain[a]], b, func);
	}
};
struct UnionFind {
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) { //ｘの入ってる集合と yの入ってる集合を併合
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) { //xとyが同じ集合に入っているかどうかを判定
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	bool isroot(int x) {
		return data[x] < 0;
	}
	int size(int x) {
		return -data[root(x)];
	}
};
BiDGraph Kruskal(BiDGraph g) {//最小全域　森
	UnionFind uf(g.vn);
	priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>>> que;
	REP(i, g.g.size()) {
		for (auto itr : g.g[i]) {
			int f = i, t = itr.first;
			if (f < t)
				swap(f, t);
			que.push({ itr.second,{ f,t } });
		}
	}
	BiDGraph MST(g.vn);
	int alcou = 0;
	while (alcou < g.vn) {
		pair<int, pii> cur = que.top();
		que.pop();
		if (uf.findSet(cur.second.first, cur.second.second))
			continue;

		if (uf.data[cur.second.first] == -1)
			alcou++;
		if (uf.data[cur.second.second] == -1)
			alcou++;
		uf.unionSet(cur.second.first, cur.second.second);
		MST.con(cur.second.first, cur.second.second);
	}
	return MST;
}
