int rank[114514];
vector<Pair> xs;
vector<Pair> ys;
vector<Edge> es;

int find(int v) {
  if (par[v] == v) return v;
  return par[v] = find(par[v]);
}

int same(int u, int v) {
  return find(u) == find(v);
}

void unite(int u, int v) {
  u = find(u);
  v = find(v);
  if (u == v) return;
  if (rank[u] > rank[v]) par[v] = u;
  else {
    par[u] = v;
    if (rank[u] == rank[v]) rank[v]++;
  }
}

