inline LL kruskal(int n,int m) {
    sort(b+1,b+m+1);
    int res=0,cnt=0;
    FOR(i,1,m) {
        krus e=b[i];
        int x=fi(e.u),y=fi(e.v);
        if(x!=y)par[x]=y,res+=e.cost,++cnt;
        if(cnt==n-1)break;
    }
    return res;
}

