using namespace std;
typedef long long LL;

const LL maxn=200010,inf=LONG_LONG_MAX;
LL d[maxn],vis[maxn],x[maxn],y[maxn];
struct edge
{
    LL to,len;
    edge(LL to,LL len):to(to),len(len){}
};
struct node
{
    LL v,dist;
    node(LL x,LL y):v(x),dist(y){}
    friend bool operator <(node a,node b)
    {
        return a.dist>b.dist;
    }
};
vector<edge>G[maxn];
LL prim()
{
    LL ans=0;
    fill(vis,vis+maxn,0);
    fill(d,d+maxn,inf);
    priority_queue<node>q;
    q.push(node(0,0));
    while(q.size())
    {
        node t=q.top();q.pop();
        if(vis[t.v]) continue;
        vis[t.v]=1;
        ans+=t.dist;
        for(LL i=0;i<G[t.v].size();i++)
        {
            edge e=G[t.v][i];
            if(vis[e.to]) continue;
            if(e.len<d[e.to]) d[e.to]=e.len,q.push(node(e.to,e.len));
        }
    }
    return ans;
}

struct point
{
    LL x,y;
}p[maxn];

bool cmp(point a,point b)
{
    return a.x<b.x;
}

bool cmpp(point a,point b)
{
    return a.y<b.y;
}

map<pair<LL,LL > , LL> mp;

int main()
{
    LL n;
    while(cin>>n)
    {
        mp.clear();
        for(LL i=0;i<maxn;i++) G[i].clear();
        for(LL i=0;i<n;i++)
            cin>>p[i].x>>p[i].y,mp[make_pair(p[i].x,p[i].y)]=i;
        for(LL i=1;i<n;i++)
        {
            LL len = min(abs(p[i].x-p[0].x),abs(p[i].y-p[0].y));
            G[0].push_back(edge(i,len));
            G[i].push_back(edge(0,len));
        }
        sort(p,p+n,cmp);
        for(LL i=1;i<n;i++)
        {
            LL u=mp[make_pair(p[i].x,p[i].y)],v=mp[make_pair(p[i-1].x,p[i-1].y)];
            if(u==0 || v==0) continue;
            LL len = abs(p[i].x-p[i-1].x);
            G[u].push_back(edge(v,len));
            G[v].push_back(edge(u,len));
        }
        sort(p,p+n,cmpp);
        for(LL i=1;i<n;i++)
        {
            LL u=mp[make_pair(p[i].x,p[i].y)],v=mp[make_pair(p[i-1].x,p[i-1].y)];
            if(u==0 || v==0) continue;
            LL len = abs(p[i].y-p[i-1].y);
            G[u].push_back(edge(v,len));
            G[v].push_back(edge(u,len));
        }
        cout<<prim()<<endl;
    }
    return 0;
}

