const int maxn = 1e5*3+20;

int f[maxn];

int n,_,q,k;

struct P{
	int x; int y; int id;
};
vector<P> pts;
vector<P> byx;
vector<P> byy;

struct Edge{
	int fr; int to; int w;
};
vector<Edge> edges;


int dist(P p1, P p2){
	return min(abs(p1.x - p2.x), abs(p1.y - p2.y));
}

int find(int x){
    if(f[x]==x)return x;
    return f[x]=find(f[x]);
}
void unite(int x,int y){
    x=find(x);y=find(y);
    if(x==y)return;
    f[x]=y;
}

void solve(){
	cin >> n;
	FF(i,1,n){
		int t1,t2; cin >> t1 >> t2;
		pts.eb((P){t1,t2,i});
	}
	byx = pts;
	byy = pts;
	sort(all(byx), [](P p1, P p2){
		return p1.x < p2.x;
	});
	sort(all(byy), [](P p1, P p2){
		return p1.y < p2.y;
	});

	//build edges
	F(i,0,sz(byx)){
		P curr = byx[i];
		if(i-1 >= 0){
			P lft = byx[i-1];
			Edge ne = (Edge){curr.id, lft.id, dist(lft,curr)};
			edges.eb(ne);
		}
		if(i+1 < sz(byx)){
			P rt = byx[i+1];
			Edge ne = (Edge){curr.id, rt.id, dist(rt,curr)};
			edges.eb(ne);
		}
	}
	F(i,0,sz(byy)){
		P curr = byy[i];
		if(i-1 >= 0){
			P lft = byy[i-1];
			Edge ne = (Edge){curr.id, lft.id, dist(lft,curr)};
			edges.eb(ne);
		}
		if(i+1 < sz(byy)){
			P rt = byy[i+1];
			Edge ne = (Edge){curr.id, rt.id, dist(rt,curr)};
			edges.eb(ne);
		}
	}

	for(int i = 0; i < n; i++){
		f[i] = i;
	}
	sort(all(edges), [](Edge e1, Edge e2){
		return e1.w < e2.w;
	});	
	int sum = 0;
	dbg(sz(edges));
	for(Edge te : edges){
		if(find(te.fr) != find(te.to)){
			f[find(te.fr)] = f[find(te.to)];
			sum += te.w;
		}
	}
	cout << sum;


}

signed main(){
  //clock_t t1 = clock();  
	IOS
	solve();

  //cout << "THE ALGORITHM TOOK: " << (clock() - t1) * 1.0 / CLOCKS_PER_SEC * 1000 << "ms"<< endl;
	return 0;
}

