        px.PB(MP(x,i));
        py.PB(MP(y,i));
    }
    SORT(px);SORT(py);
    edge e;
    E=0;
    REP(i,N-1){
        edge e;
        e.u=px[i].second;e.v=px[i+1].second;e.cost=px[i+1].first-px[i].first;
        es[E]=e;E++;
        e.u=py[i].second;e.v=py[i+1].second;e.cost=py[i+1].first-py[i].first;
        es[E]=e;E++;
    }

    cout<<kruskal()<<endl;
    return 0;
}

