ll prim(int N, vector<vector<pii >> edge) {
    priority_queue<pii, vector<pii >, greater<pii>> pq;
    vb used(N, false);
    pq.push(pii(0, 0));
    ll total = 0;
    while (!pq.empty()) {
        int dis, t;
        tie(dis, t) = pq.top();
