  map< pair<int,int>,int > m;
  fillmap(xs,m);
  fillmap(ys,m);

  priority_queue< pair< int, pair<int,int> > > pq;

  for(auto &&kv:m) pq.push(make_pair(-kv.second,kv.first));

  auto uf = UnionFind(N+1);
  ll ans=0;
