        int ni = it->second;
        edges.emplace(min(abs(xy[ni].first - xy[i].first), abs(xy[ni].second - xy[i].second)), ni);
    }
    if(it != sxi.begin()){
        auto nit = next(it, -1);
        int ni = nit->second;
        edges.emplace(min(abs(xy[ni].first - xy[i].first), abs(xy[ni].second - xy[i].second)), ni);
    }
    it = syi.upper_bound(P(xy[i].second, i));
