        edges.emplace(min(abs(xy[ni].first - xy[i].first), abs(xy[ni].second - xy[i].second)), ni);
    }
    if(it != syi.begin()){
        auto nit = next(it, -1);
        int ni = nit->second;
        edges.emplace(min(abs(xy[ni].first - xy[i].first), abs(xy[ni].second - xy[i].second)), ni);
