        used[p.second] = true;
        ans += p.first;
        sxi.erase(P(xy[p.second].first, p.second));
        syi.erase(P(xy[p.second].second, p.second));
        add_edge(p.second);
        count++;
    }

    cout << ans << endl;

    return 0;
}

