// T (typename) : グラフの頂点を表す型, (int)parent, (int)size を持つ必要あり
template <typename T>
struct UnionFind {
    vector<T> &u;
    UnionFind(vector<T> &u) : u(u) {
        for (int i = 0; i < u.size(); i++) {
            u[i].parent = i;
        }
    }
    int root(int x) {
        if (x < 0 || u.size() <= x)
            return -1;
        else if (x == u[x].parent)
            return x;
        else
            return u[x].parent = root(u[x].parent);
    }
    bool connect(int a, int b) {
        a = root(a), b = root(b);
        if (a == b || a < 0 || b < 0) return false;
        { /* do something */
        }
        u[b].parent = a;
        return true;
    }
    // O(u.size())
    void count(map<int, int> &ret) {
        for (int i = 0; i < u.size(); i++) {
            int tmp = u[i].parent;
            if (!ret.count(tmp)) {
                ret[tmp] = 0;
            }
            ret[tmp]++;
        }
    }
};

template <typename Edge>
void Kruskal(vector<Edge> &edge, int N, vector<Edge> &ans) {
    struct Node {
        int parent;
    };
    rev_priority_queue<Edge> q;
    vector<Node> node(N);
    UnionFind<Node> uf(node);
    for (auto e : edge) q.push(e);
    while (!q.empty()) {
        Edge e = q.top();
        q.pop();
        if (uf.root(e.v1) != uf.root(e.v2)) {
            uf.connect(e.v1, e.v2);
            ans.push_back(e);
        }
    }
}

struct Edge {
    int v1, v2;
    i64 cost;
    bool operator>(const Edge &e) const {
        return cost > e.cost;
    }
};

