    vector<pair<i64, int>> X(N), Y(N);
    for(int i = 0; i < N; i++) {
        i64 x, y;
        cin >> x >> y;
        X[i] = {x, i}, Y[i] = {y, i};
    }
    sort(WHOLE(X)), sort(WHOLE(Y));
    vector<Edge> e;
    for(int b = 0; b < 2; b++) {
        for(int i = 0; i < N - 1; i++) {
            auto s = X[i], t = X[i + 1];
            e.push_back({s.second, t.second, t.first - s.first});
        }
        swap(X, Y);
    }
    vector<Edge> span;
    i64 ans = 0;
    Kruskal(e, N, span);
    for(auto x : span) ans += x.cost;
    cout << ans << endl;
    return 0;
}

