int fs(int u) {
  return (p[u] == u ? u : p[u] = fs(p[u]));
}

inline bool cmp(const open &a, const open &b) {
  if (a.x != b.x) {
    return a.x < b.x;
  }
  return a.y < b.y;
}

inline bool cmp2(const open &a, const open &b) {
  if (a.y != b.y) {
    return a.y < b.y;
  }
  return a.x < b.x;
}

