bool gt(const pair<int, int> &a, const pair<int, int> &b){
  return a.second < b.second;
}

bool gt2(const pair<pair<int, int>, int> &a, const pair<pair<int, int>, int> &b){
  return a.second < b.second;
}

int group(vector<int> &did, int a){
  while(did[a] >= 0){
    a = did[a];
  }
  return a;
}
void unite(vector<int> &did, int a, int b){
  a = group(did, a);
  b = group(did, b);
  did[b]--;
  did[a] = b;
}

