ll solve(int n, vector<int>&x, vector<int>&y) {
//    UnionFind uf(n);
    assert(x.size() == n && y.size() == n);

    vector<bool> vis(n, false);
    multimap<int, int> xx, yy;
    rep(i, n) {
        xx.insert(ii(x[i], i));
        yy.insert(ii(y[i], i));
    }

    priority_queue<pair<int,ii>> pqx, pqy;

    auto jet = [](int i, vector<bool>& vis, vector<int>& x, multimap<int, int>& xx, priority_queue<pair<int,ii>>& pq, const char *x_y) {
        assert(vis[i]);
#ifdef VERBOSE
        printf("jet<%s>: i=%d\n", x_y, i);
#endif
        auto ax = xx.equal_range(x[i]);
        for (auto it=ax.first; it!=ax.second; ++it) {
            if (it->second != i) continue;
            assert(it != xx.end());

            for (auto a=it; ;) {
                int j = a->second;
                if (j != i && !vis[j]) {
                    pq.push(make_pair(-abs(x[j]-x[i]), ii(i,j)));
#ifdef VERBOSE
                    printf(" +%d\n", j);
#endif
                    break;
                }
                if (a == xx.begin()) break;
                --a;
            }
            for (auto b=it; b!=xx.end(); ++b) {
                int j = b->second;
                if (j != i && !vis[j]) {
                    pq.push(make_pair(-abs(x[j]-x[i]), ii(i,j)));
#ifdef VERBOSE
                    printf(" +%d\n", j);
#endif
                    break;
                }
            }
            break;
        }
    };

    vis[0] = true;
    ll cost = 0;
    jet(0, vis,x,xx,pqx, "x");
    jet(0, vis,y,yy,pqy, "y");

    auto get_nearest = [](vector<bool>& vis, priority_queue<pair<int,ii>>& pq) -> int {
        while (!pq.empty()) {
            int u = pq.top().second.first, v = pq.top().second.second;
#ifdef VERBOSE
            printf("u=%d, v=%d\n", u, v);
#endif
            assert(vis[u]);
            if (vis[v]) {
                pq.pop(); continue;
            } else {
                return -pq.top().first;
            }
        }
        return INT_MAX;
    };

    for (int z=1; z<n; ++z) {
#ifdef VERBOSE
        printf("z=%d\n", z);
#endif
        int x_nearest = get_nearest(vis, pqx);
        int y_nearest = get_nearest(vis, pqy);
        if (x_nearest == INT_MAX && y_nearest == INT_MAX) {
            assert(false);
            break;
        }
#ifdef VERBOSE
        printf("nearest=%d or %d\n", x_nearest, y_nearest);
#endif
        auto fn0 = [](vector<bool>& vis, priority_queue<pair<int,ii>>& pq) {
            int v = pq.top().second.first, a = pq.top().second.second;
            pq.pop();
            return ii(v, a);
        };

        int v, a, d;
        if (x_nearest < y_nearest) {
            ii va = fn0(vis, pqx);
            v = va.first; a = va.second;
            d = x_nearest;
        } else {
            ii va = fn0(vis, pqy);
            v = va.first; a = va.second;
            d = y_nearest;
        }

        assert(vis[v] && !vis[a]);
#ifdef VERBOSE
        printf("take (%d-)%d. cost += %d.\n", v, a, d);
#endif
        vis[a] = true;
        cost += d;

        jet(a, vis,x,xx,pqx, "x");
        jet(a, vis,y,yy,pqy, "y");
    }
    return cost;
}

