ll prim(vvll cost,ll N) {
    vll mincost(N);
    vector<bool> done(N);
    for(ll i=0; i<N; ++i) {
        mincost[i] = LLMAX;
        done[i] = false;
    }
    mincost[0] = 0;
    ll res = 0;

    while(true) {
        ll v = -1;
        for(ll i=0;i<N;i++) {
            if(!done[i] && (v==-1 || mincost[i] < mincost[v])) v = i;
