struct town{
  int x, y, num;

  town(int xx, int yy, int nn) : x(xx), y(yy), num(nn) {}

  bool operator < (const town& oth) const {
  if(x != oth.x) return x < oth.x;
  else if(y != oth.y) return y < oth.y;
  return num < oth.num;
  }
};

struct edge{int from, to, cost;

  edge(int f, int t, int c) : from(f), to(t), cost(c) {}

  bool operator < (const edge& oth) const {
    if(cost != oth.cost) return cost < oth.cost;
    else if(from != oth.from) return from < oth.from;
    return to < oth.to;
  }

};

vector<town> g;
vector<edge> s;
int n;
int par[100005];
int Rank[100005];
ll ans;
void init(int n) {
  for(int i = 0; i < n; i++) {
    par[i] = i;
    Rank[i] = 0;
  }
}

int find(int x) {
  return x == par[x] ? x : par[x] = find(par[x]);
}

void Union(int x, int y) {
  int a = find(x);
  int b = find(y);
  if(a == b) return;

  if(Rank[a] > Rank[b]) par[b] = a;
  else {
    par[a] = b;
    if(Rank[a] == Rank[b]) Rank[b]++;
  }
}

