const LL maxn=100010,inf=LONG_LONG_MAX;
LL d[maxn],vis[maxn],x[maxn],y[maxn];
struct edge
{
    LL to,len;
    edge(LL to,LL len):to(to),len(len){}
};
struct node
{
    LL v,dist;
    node(LL x,LL y):v(x),dist(y){}
    friend bool operator <(node a,node b)
    {
        return a.dist>b.dist;
    }
};
vector<edge>G[maxn];
LL prim()
{
    LL ans=0;
    fill(vis,vis+maxn,0);
    fill(d,d+maxn,inf);
    priority_queue<node>q;
    q.push(node(0,0));
    while(q.size())
    {
        node t=q.top();q.pop();
        if(vis[t.v]) continue;
        vis[t.v]=1;
        ans+=t.dist;
        for(LL i=0;i<G[t.v].size();i++)
        {
            edge e=G[t.v][i];
            if(vis[e.to]) continue;
            if(e.len<d[e.to]) d[e.to]=e.len,q.push(node(e.to,e.len));
        }
    }
    return ans;
}

