        eg[egn].v = nd[i + 1].id;
    }
    sort(eg + 1, eg + 1 + egn, cmp3);
    long long ans = 0;
    int tmp = 0;
    for(int i = 1;i <= egn;i++)
    {
        if(tmp >= nn - 1)
