        int u = pr(eg[i].u);
        int v = pr(eg[i].v);
        long long w = eg[i].w;
        if(u != v)
        {
            con(u, v);
            ans += w;
            con(u, v);
        }
    }
    printf("%lld\n", ans);
    return 0;
}

