#define MAX_N 100010
struct UF {
	int par[MAX_N],rank[MAX_N];

	void init(int n){
		for(int i = 0; i < n; i++){
			par[i] = i;
			rank[i] = 0;
		}
	}

	int find(int x){
		if(par[x] == x){
			return x;
		}else{
			return par[x] = find(par[x]);
		}
	}

	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;

		if(rank[x] < rank[y]){
			par[x] = y;
		}else{
			par[y] = par[x];
			if(rank[x] == rank[y]) rank[y]++;
		}
	}

	bool same(int x, int y){
		return find(x) == find(y);
	}
};

int main(){
	int n; cin>>n;
	vector<PP> v(n);
	rep(i, n){
		cin>>v[i].fst.fst>>v[i].fst.snd;
		v[i].snd = i;
	}
	UF uf;
	uf.init(n);
	sort(all(v));
	vector<PP2> d(2*n-2);
	rep(i, n-1) d[i] = PP2(v[i+1].fst.fst-v[i].fst.fst, P(v[i+1].snd, v[i].snd));
	rep(i, n) swap(v[i].fst.fst, v[i].fst.snd);
	sort(all(v));
	rep(i, n-1) d[i+n-1] = PP2(v[i+1].fst.fst-v[i].fst.fst, P(v[i+1].snd, v[i].snd));
	sort(all(d));
	ll res = 0;
	rep(i, 2*n-2){
		int u = d[i].snd.fst, v = d[i].snd.snd;
		if(!uf.same(u, v)){
			uf.unite(u, v);
			res += d[i].fst;
		}
	}
	cout<<res<<endl;
	return 0;
}

