} p[100005];

vector< pair<int, pair<int, int> > > q;

bool cmpx(point a, point b)
{
	if (a.x != b.x) return a.x > b.x;
	else return a.y > b.y;
}

bool cmpy(point a, point b)
{
	if (a.y != b.y) return a.y > b.y;
	else return a.x > b.x;
}

int up[100005];

void makesets()
{
	for (int i = 0; i < 100001; i++)
	{
		up[i] = -1;
	}
}

int Find(int x)
{
	if (up[x] < 0) return x;
	int root = Find(up[x]);
	up[x] = root;
	return root;
}

void Union(int x, int y)
{
	if (Find(x) == Find(y)) return;
	if (up[x] < up[y])
	{
		up[x] += up[y];
		up[y] = x;
	}
	else
	{
		up[y] += up[x];
		up[x] = y;
	}
}

int n;

