const int N = 1e5 + 10;

struct DSU
{
	int rank[N];
	int anc[N];
	DSU() : rank()
	{
		for (int i = 0; i < N; ++i)
			anc[i] = i;
	}
	int get(int x)
	{
		return x == anc[x] ? x : anc[x] = get(anc[x]);
	}
	bool unite(int a, int b)
	{
		a = get(a);
		b = get(b);
		if (a == b)
			return false;
		if (rank[a] < rank[b])
			swap(a, b);
		if (rank[a] == rank[b])
			++rank[a];
		anc[b] = a;
		return true;
	}
} dsu;

int n;
pii x[N], y[N];

struct Rec
{
	int cost;
	int a, b;
	Rec(int cost, int a, int b) : cost(cost), a(a), b(b) {}
	bool operator< (const Rec& r) const
	{
		return cost < r.cost;
	}
};

void solve()
{
	scanf("%d", &n);
	for (int i = 0; i < n; ++i)
	{
		scanf("%d%d", &x[i].first, &y[i].first);
		x[i].second = y[i].second = i;
	}
	sort(x, x + n);
	sort(y, y + n);
	vector<Rec> recs;
	for (int i = 1; i < n; ++i)
	{
		recs.emplace_back(x[i].first - x[i - 1].first, x[i].second, x[i - 1].second);
		recs.emplace_back(y[i].first - y[i - 1].first, y[i].second, y[i - 1].second);
	}
	sort(recs.begin(), recs.end());
	int cnt = 1;
	ll ans = 0;
	for(auto r : recs)
		if (dsu.unite(r.a, r.b))
		{
			ans += r.cost;
			++cnt;
		}
	if (cnt != n)
		throw;
	printf("%lld\n", ans);
}

