const double EPS = 1e-9;

const int DX[]={1,0,-1,0},DY[]={0,-1,0,1};
vector<pair<LL, int>> x_and_idx, y_and_idx;

struct UnionFind {
    vector<LL> data;
    UnionFind(LL size) : data(size, -1) { }

    bool unionSet(LL x, LL y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }

    bool findSet(LL x, LL y) {
        return root(x) == root(y);
    }

    LL root(LL x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    LL size(LL x) {
        return -data[root(x)];
    }
};

void solve(long long N, std::vector<long long> x, std::vector<long long> y){
    REP(i, N) {
        x_and_idx.PB(MP(x[i], i));
        y_and_idx.PB(MP(y[i], i));
    }
    UnionFind uf(N);

    sort(ALL(x_and_idx));
    sort(ALL(y_and_idx));

    vector<pair<LL, pair<int, int> > > memo;
    REP(i, N) {
        LL now = x_and_idx[i].first;
        REP1(cnt, 20) {
            if(N <= cnt+i || now == x_and_idx[i+cnt].first) break;
            memo.PB(MP(abs(x[x_and_idx[i].second] - x[x_and_idx[i+cnt].second]), MP(x_and_idx[i].second, x_and_idx[i+cnt].second)));
        }
        if(i+1 != N && x_and_idx[i].first == x_and_idx[i+1].first) {
            uf.unionSet(x_and_idx[i].second, x_and_idx[i+1].second);
        }

        REP(i, N) {
            LL now = y_and_idx[i].first;
            REP1(cnt, 20) {
                if(N <= cnt+i || now == y_and_idx[i+cnt].first) break;
                memo.PB(MP(abs(y[y_and_idx[i].second] - y[y_and_idx[i+cnt].second]), MP(y_and_idx[i].second, y_and_idx[i+cnt].second)));
            }
        }
        if(i+1 != N && y_and_idx[i].first == y_and_idx[i+1].first) {
            uf.unionSet(y_and_idx[i].second, y_and_idx[i+1].second);
        }
    }
    sort(ALL(memo));
    LL ans = 0;
    REP(i, memo.size()){
        if(uf.size(0) == N) break;
        pair<LL, pair<int, int> > now = memo[i];
        if(uf.findSet(now.second.first, now.second.second)) continue;
        ans += now.first;
        uf.unionSet(now.second.first, now.second.second);
    }

    cout << ans << endl;
}

