  }
  sort(xres, xres + n);
  sort(yres, yres + n);
  for (int i = 0; i < n - 1; i++) {
    edge tmp;
    tmp.u = xres[i].second;
    tmp.v = xres[i + 1].second;
    tmp.cost = abs(xres[i + 1].first - xres[i].first);
    es[i] = tmp;
  }
  for (int i = n - 1; i < 2 * n - 2; i++) {
    edge tmp;
    tmp.u = yres[i - n + 1].second;
    tmp.v = yres[i - n + 2].second;
    tmp.cost = abs(yres[i - n + 1].first - yres[i - n + 2].first);
    es[i] = tmp;
  }
