int findu(int u){
    return rep[u] = (rep[u] == u ? u : findu(rep[u]));
}

void join(int a, int b){
    a = findu(a);
    b = findu(b);
    if (a == b)
        return;
    if (sz[a] < sz[b])
        swap(a, b);
    rep[b] = a;
    sz[a] += sz[b];
    nc--;
}
void mst(){
    sort(p, p + M);
    for (int i = 0; i < M; i++){
       int a = p[i].second.first;
       int b = p[i].second.second;
       if (rep[a] != rep[b])
            join(a, b);
       else
        sum += p[i].first;
    }
}

