class disjoint_set {
private:
    int pa[MAX_N];
    int rnk[MAX_N];
public:
    void init(void)
    {
        memset(pa, 0, sizeof(pa));
        memset(rnk, 0, sizeof(rnk));
        for (int i = 0; i < n; i++) {
            pa[i] = i;
            rnk[i] = 0;
