        if (pa[x] == x) return x;
        else return pa[x] = _find(pa[x]);
    }
    void unite(int x, int y)
    {
        x = _find(x);
        y = _find(y);
        if (x == y) return;
        if (rnk[x] < rnk[y]) pa[x] = y;
        else {
            pa[y] = x;
            if (rnk[x] == rnk[y]) rnk[x]++;
        }
    }
    bool same(int x, int y)
    {
        return (_find(x) == _find(y));
    }
};

