    vector<int[2]> r(n);
    for (int i = 0; i < n; i++) {
        cin >> r[i][0] >> r[i][1];
    }

    vector<Edge> e;
    e.reserve(n * 2);
    vector<int> p(n);

    for (int j = 0; j < 2; j++) {
        for (int i = 0; i < n; i++) {
            p[i] = i;
        }
        sort(p.begin(), p.end(), [&](int i0, int i1) {
            return r[i0][j] < r[i1][j];
        });

        for (int i = 1; i < n; i++) {
            e.push_back({ p[i], p[i - 1], abs(r[p[i]][j] - r[p[i - 1]][j]) });
        }
    }

    sort(e.begin(), e.end());
    UnionFind uf(e.size());
    int c = 0, k = 0;

    for (const Edge& o : e) {
        if (uf.same(o.i, o.j)) continue;
        uf.unite(o.i, o.j);
        c += o.c;
        if (++k == n - 1) break;
    }

    cout << c << endl;

    return 0;
}

