	ll ans = 0ll;
	for(int i=0;i<es.size();i++){
		int a = es[i].from;
		int b = es[i].to;
		int c = es[i].cost;
		if(uf.same(a,b))continue;
		uf.unite(a,b);
		ans += (ll)c;
	}
	cout << ans << endl;
	return 0;
}

