			par_sz[a]._1 = findSet(par_sz[a]._1);
		return par_sz[a]._1;
	}
	int unionSet(int a, int b) noexcept
	{
		a = findSet(a); b = findSet(b);
		if(a == b) return 0;
		if(par_sz[a]._2 < par_sz[b]._2) swap(a,b);
		par_sz[a]._2 += par_sz[b]._2;
		par_sz[b]._1 = par_sz[a]._1;
		return 1;
	}
};

const int MAX_N {100005};

