	};
	using T3 = tuple<int,int,int>;
	MIN_PQ(T3) Q;
	VI A(N);

	auto f = [&](auto func)
	{
		iota(ALL(A),0);
		sort(ALL(A), func);
		FOR(i,1,N) Q.emplace(dist(A[i-1], A[i]), A[i-1], A[i]);
	};
	f([&](int a, int b) {return X[a] < X[b];});
	f([&](int a, int b) {return Y[a] < Y[b];});

	UnionFind U(N);
	int sol {0};
	while(not Q.empty())
	{
		int d, a, b;
		tie(d,a,b) = Q.top();
		Q.pop();

		if(U.unionSet(a,b)) sol += d;
	}
