inline void PUSHR(int i)
{
	int ret=INF,tmp;
	rr[i].first--;
	rr[i].second++;
	if(rr[i].first>0) 
	{
		if(dis(po[indr[rr[i].first]],po[i])<ret) ret=dis(po[indr[rr[i].first]],po[i]),tmp=1;
	}
