	}
	if(tmp==1) 
	{
		rr[i].second--;
		q.push(MP(-ret,MP(i,indr[rr[i].first])));
	}
	else if(tmp==2)
	{
		rr[i].first++;
		q.push(MP(-ret,MP(i,indr[rr[i].second])));
	} 
}

inline void PUSHC(int i)
