class UnionFind
{
   private:
      vector<int> par, myrank;
   public:
      UnionFind(int n) {
         par.resize(n);
         myrank.resize(n, 0);
         for (int i = 0; i < n; i++) {
            par[i] = i;
         }
      }
      int find(int x) {
         if (par[x] == x) return x;
         return par[x] = find(par[x]);
      }
      void unite(int x, int y) {
         x = find(x);
         y = find(y);
         if (x == y) return;
         if (myrank[x] < myrank[y]) {
            par[x] = y;
         } else {
            par[y] = x;
            if(myrank[x] == myrank[y]) myrank[x]++;
         }
      }
      bool same(int x, int y) {
         return find(x) == find(y);
      }
};
int kruskal(const vector<edge>& E, int N) {
   UnionFind uni(N);
   vector<edge> E_tmp(E.size());
   copy(E.begin(), E.end(), E_tmp.begin());
   SORT(E_tmp);
   int sum = 0;
   for(int i = 0; i < E_tmp.size(); i++) {
      edge e = E_tmp[i];
      if (!uni.same(e.from, e.to)) {
         uni.unite(e.from, e.to);
         sum += e.cost;
      }
   }
   return sum;
}

