struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) {}
    bool unionSet(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) { return root(x) == root(y); }
    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
    int size(int x) { return -data[root(x)]; }
};

int main() {
    int n;
    in(n);

    vector<pair<int64_t, int>> x(n), y(n);

    for (int i : rep(0, n)) {
        in(x[i].first, y[i].first);
        x[i].second = i;
        y[i].second = i;
    }

    sort(x);
    sort(y);

    struct E {
        int64_t cost, v1, v2;
    };

    vector<E> es(2 * n);

    for (int i : rep(1, n)) {
        es[i].cost = x[i].first - x[i - 1].first;
        es[i].v1 = x[i].second;
        es[i].v2 = x[i - 1].second;
    }

    for (int i : rep(1, n)) {
        es[n + i].cost = y[i].first - y[i - 1].first;
        es[n + i].v1 = y[i].second;
        es[n + i].v2 = y[i - 1].second;
    }

    sort(es, [](auto e1, auto e2) { return e1.cost < e2.cost; });

    UnionFind uf(n);

    int64_t ans = 0;

    for (int i : rep(0, 2 * n)) {
        auto e = es[i];

        if (uf.findSet(e.v1, e.v2)) {
            continue;
        }

        uf.unionSet(e.v1, e.v2);
        ans += e.cost;
    }

    out(ans);
}

