struct UnionFind
{
    vector< int > data;

    UnionFind(int sz){
        data.assign(sz, -1);
    }

    bool unite(int x, int y){
        x = root(x), y = root(y);
        if(x == y) return false;
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }

    int root(int k){
        if(data[k] < 0) return(k);
        return (data[k] = root(data[k]));
    }

    int size(int k){
        return -data[root(k)];
    }
};

int Kruskal(Edges &E, int V){
    sort(All(E), [](const edge &a, const edge &b) {
        return (a.cost < b.cost);
    });

    UnionFind MST(V);
    int res = 0;
    for(auto e: E){
        if(MST.unite(e.from, e.to)) res += e.cost;
    }

    return res;
}


