class disjoint_set {
private:
    int pa[MAX_N];
    int rnk[MAX_N];
public:
    void init(void)
    {
        memset(pa, 0, sizeof(pa));
        memset(rnk, 0, sizeof(rnk));
        for (int i = 0; i < n; i++) {
            pa[i] = i;
            rnk[i] = 0;
        }
    }
    int _find(int x)
    {
        if (pa[x] == x) return x;
        else return pa[x] = _find(pa[x]);
    }
    void unite(int x, int y)
    {
        x = _find(x);
        y = _find(y);
        if (x == y) return;
        if (rnk[x] < rnk[y]) pa[x] = y;
        else {
            pa[y] = x;
            if (rnk[x] == rnk[y]) rnk[x]++;
        }
    }
    bool same(int x, int y)
    {
        return (_find(x) == _find(y));
    }
};

int abs(int a)
{
    return a >= 0? a: -a;
}

bool cmp_x(point a, point b)
{
    return a.co.x < b.co.x || a.co.x == b.co.x && a.co.y <= b.co.y;
}

bool cmp_y(point a, point b)
{
    return a.co.y < b.co.y || a.co.y == b.co.y && a.co.x <= b.co.x;
}

bool cmp_edge(edge a, edge b)
{
    return a.w <= b.w;
}

int mst(void)
{
    disjoint_set ds;
    ds.init();
    int res = 0;
    for (int i = 0; i < 2 * (n - 1); i++) {
        edge e = edgeset[i];
        if (!ds.same(e.u, e.v)) {
            ds.unite(e.u ,e.v);
            res += e.w;
        }
    }
    return res;
}

