pii xx[200007], yy[200007];

int root(int what)
{
	if(fa[what]==what)
		return what;
	return fa[what] = root(fa[what]);
}

int gaoshi(int wha,int whb)
{
	if(root(wha)==root(whb))
		return 0;
	fa[root(wha)] = root(whb);
	return 1;
}

int dist(int wha,int whb)
{
	return min(abs(x[wha] - x[whb]), abs(y[wha] - y[whb]));
}

int main()
{
	scanf("%d", &n);
	for (int i = 0; i < n; i++)
	{
		scanf("%d%d", x + i, y + i);
		fa[i] = i;
		xx[i] = mp(x[i], i);
		yy[i] = mp(y[i], i);
	}
	sort(xx, xx + n);
	sort(yy, yy + n);
	set<pair<int, pii> > sp;
	for (int i = 0; i < n - 1; i++)
	{
		sp.insert(mp(dist(xx[i].second, xx[i + 1].second), mp(xx[i].second, xx[i + 1].second)));
		sp.insert(mp(dist(yy[i].second, yy[i + 1].second), mp(yy[i].second, yy[i + 1].second)));
