{
	if(par[aa]==aa)
		return aa;
	return par[aa]=parent(par[aa]);
}
int union_(int aa,int bb)
{
	if(parent(aa)!=parent(bb))
		par[parent(aa)]=parent(bb);
	return 0;
}
int main()
{
