	for(i=1;i<v.size();i++)
		vvv.pb(mp(abs(v[i-1].fi-v[i].fi),mp(v[i-1].se,v[i].se)));
	for(i=1;i<vv.size();i++)
		vvv.pb(mp(abs(vv[i-1].fi-vv[i].fi),mp(vv[i-1].se,vv[i].se)));
