using namespace std;
const int M = 1e5 + 10;
int f[M];
int find(int x) {
    if(x == f[x]) return f[x];
    int tmp = find(f[x]);
    return f[x] = tmp;
}
struct TnT {
    int x , y , pos , num;
}T[M] , GT[M << 1];
bool cmp1(TnT a , TnT b) {
    return a.x < b.x;
}
bool cmp2(TnT a , TnT b) {
    return a.y < b.y;
}
bool cmp3(TnT a , TnT b) {
    return a.num < b.num;
}
int main() {
    int n;
    scanf("%d" , &n);
    for(int i = 1 ; i <= n ; i++) {
        scanf("%d%d" , &T[i].x , &T[i].y);
        T[i].pos = i;
    }
    for(int i = 1 ; i <= n ; i++) f[i] = i;
    sort(T + 1 , T + 1 + n , cmp1);
    int cnt = 0;
    for(int i = 1 ; i < n ; i++) {
        GT[++cnt].x = T[i].pos , GT[cnt].y = T[i + 1].pos , GT[cnt].num = T[i + 1].x - T[i].x;
    }
    sort(T + 1 , T + 1 + n , cmp2);
    for(int i = 1 ; i < n ; i++) {
        GT[++cnt].x = T[i].pos , GT[cnt].y = T[i + 1].pos , GT[cnt].num = T[i + 1].y - T[i].y;
    }
    int sum = 0;
    sort(GT + 1 , GT + 1 + cnt , cmp3);
    for(int i = 1 ; i <= cnt ; i++) {
        GT[i].x = find(GT[i].x) , GT[i].y = find(GT[i].y);
        if(GT[i].x != GT[i].y) {
            f[GT[i].x] = GT[i].y;
            sum += GT[i].num;
        }
    }
    printf("%d\n" , sum);
    return 0;
}

#include <iostream>
#include <vector>
#include <tuple>
#include <algorithm>
#include <queue>

using namespace std;

class adjacency_list
{
public:
	adjacency_list(size_t n)
		: g(n)
	{}

	void add_edge(int src, int dst, long long weight)
	{
		g[src].push_back({ dst, weight });
	}

	long long prim_minimum_spanning_tree() const
	{
		const int n = g.size();
		long long ans = 0;
		vector<bool> visited(n, false);
		priority_queue<edge> q;

		q.push({ 0, 0 });
		while (!q.empty()) {
			auto e = q.top();
			q.pop();
			if (visited[e.dst]) {
				continue;
			}
			visited[e.dst] = true;
			ans += e.weight;
			for (auto &f : g[e.dst]) {
				if (!visited[f.dst]) {
					q.push(f);
				}
			}
		}
		return ans;
	}
private:

	struct edge
	{
		int dst;
		long long weight;

		bool operator<(const edge &other) const
		{
			return tie(other.weight, dst) < tie(weight, other.dst);
		}
	};

private:
	vector<vector<edge>> g;
};

int main()
{
	int N;
	cin >> N;
	adjacency_list g(N);
	vector<tuple<int, int, int>> v(N);  // (id, x, y)
	for (int i = 0; i < N; ++i) {
		int x, y;
		cin >> x >> y;
		v[i] = tie(i, x, y);
	}
	// sort by x
	sort(v.begin(), v.end(), [](const auto &a, const auto &b) {
		return get<1>(a) < get<1>(b);
	});
	for (int i = 0; i < N; ++i) {
		if (0 < i) {
			int a = get<0>(v[i - 1]);
			int b = get<0>(v[i]);
			int w = abs(get<1>(v[i - 1]) - get<1>(v[i]));
			g.add_edge(a, b, w);
			g.add_edge(b, a, w);
		}
		if (i + 1 < N) {
			int a = get<0>(v[i]);
			int b = get<0>(v[i + 1]);
			int w = abs(get<1>(v[i]) - get<1>(v[i + 1]));
			g.add_edge(a, b, w);
			g.add_edge(b, a, w);
		}
	}

	// sort by y
	sort(v.begin(), v.end(), [](const auto &a, const auto &b) {
		return get<2>(a) < get<2>(b);
	});
	for (int i = 0; i < N; ++i) {
		if (0 < i) {
			int a = get<0>(v[i - 1]);
			int b = get<0>(v[i]);
			int w = abs(get<2>(v[i - 1]) - get<2>(v[i]));
			g.add_edge(a, b, w);
			g.add_edge(b, a, w);
		}
		if (i + 1 < N) {
			int a = get<0>(v[i]);
			int b = get<0>(v[i + 1]);
			int w = abs(get<2>(v[i]) - get<2>(v[i + 1]));
			g.add_edge(a, b, w);
			g.add_edge(b, a, w);
		}
	}

	cout << g.prim_minimum_spanning_tree() << endl;
}

