};

struct uf {
  int n;
  VI p;
  uf(int n) : n(n), p(n) {
    REP(i,0,n) {
      p[i] = i;
    }
  }
  int root(int x) {
    if(p[x] == x) return x;
    return p[x] = root(p[x]);
  }
  void unite(int x, int y) {
    p[x] = root(y);
  }
  bool find(int x, int y) {
    return root(x) == root(y);
  }
};

