	E(int aa, int bb, int cc) {
		a = aa; b = bb; c = cc;
	}
	E() {}
};

bool comp(E i, E j) {
	return i.c < j.c;
}
struct UnionFind {
	vector<int> par;
	vector<int> ran;

	UnionFind(int n) {
		par.resize(n);
		ran.resize(n);
		REP(i, n) {
			par[i] = i;
			ran[i] = 0;
		}
	}

	int root(int a) {
		return par[a] == a ? a : par[a] = root(par[a]);
	}

	bool same(int x, int y) {
		return root(x) == root(y);
	}

	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if (x == y)return;
		if (ran[x] < ran[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (ran[x] == ran[y]) ran[x]++;
		}
	}
};
