        g.pb(mp(abs(y[i].ff - y[i + 1].ff), mp(y[i].ss, y[i + 1].ss)));
    sort(all(g));
    vi tree_id(n, 0);
    for(int i = 0; i < n; i++)
        tree_id[i] = i;
    ll m = g.size();
    ll cost = 0;
    for(int i=0; i < m; i++) {
        int a = g[i].second.first,  b = g[i].second.second,  l = g[i].first;
        if (tree_id[a] != tree_id[b]) {
            cost += l;
            int old_id = tree_id[b],  new_id = tree_id[a];
            for(int j = 0; j < n; j++)
                if (tree_id[j] == old_id)
                    tree_id[j] = new_id;
        }
    }
    cout << cost;
    return 0;
}

