const int N = (1e5)+5;  // check the limit, man
int par[N],lev[N],tot[N];
void makeset(int n)
{
    fill(par,par+n,-1);
    fill(lev,lev+n,0);
    fill(tot,tot+n,1);
    return;
}
int findset(int x)
{
    int y=x;
    while(par[y]>=0)
        y=par[y];
    if(x!=y)
        par[x]=y;
    return y;
}
int combine(int a,int b)
{
    a=findset(a);
    b=findset(b);
    if(a!=b)
    {
        if(lev[a]>lev[b])
            swap(a,b);
        par[a]=b,tot[b]+=tot[a];
        if(lev[a]==lev[b])
            lev[b]++;
        return 1;
    }
    return 0;
}
void solve()
{
    int n,i,m,a,b,d;
    in(n);
    vii point(n);
    rep(i,n)
        inp(point[i]);
    makeset(n);
    sort(all(point));
    vector<triple> v(n);
    rep(i,n)
        v[i]=mt(point[i].S,point[i].F,i);
    sort(all(v));
    vector<triple> edge;
    rep(i,n-1)
        edge.pb(mt(point[i+1].F-point[i].F,i,i+1));
    rep(i,n-1)
        edge.pb(mt(tf(v[i+1])-tf(v[i]),tt(v[i]),tt(v[i+1])));
    sort(all(edge));
    m=edge.size();
    ll ans=0;
    rep(i,m)
    {
        tie(d,a,b)=edge[i];
        if(combine(a,b))
            ans+=d;
    }
    llout(ans);

}
