template <typename T>
struct kruskal
{
  vector<int> par, rank_;
  int V;
  kruskal(int V_) : V(V_)
  {
    par.resize(V);
    iota(begin(par), end(par), 0);
    rank_.assign(V, 0);
  };

  int root(int x) { return par[x] == x ? x : par[x] = root(par[x]); }

  bool same(int x, int y) { return root(x) == root(y); }

  void unite(int x, int y)
  {
    x = root(x);
    y = root(y);
    if (x == y)
      return;

    if (rank_[x] < rank_[y])
    {
      par[x] = y;
    }
    else
    {
      par[y] = x;
      if (rank_[x] == rank_[y])
        rank_[x]++;
    }
  }

  struct edge
  {
    int u, v;
    T cost;
  };

  vector<edge> E;

  void add_E(int s, int t, T w)
  {
    E.push_back({s, t, w});
  }

  T calc()
  {
    sort(E.begin(), E.end(), [](edge &e1, edge &e2) { return e1.cost < e2.cost; });
    T res = 0;
    for (auto e : E)
    {
      if (!same(e.u, e.v))
      {
        unite(e.u, e.v);
        res += e.cost;
      }
    }
    return res;
  }
};
#pragma endregion

