};

template<typename T>
struct edge {
	int from, to;
	T cost;
};

template<typename T>
T kruskal(vector<edge<T>> &edges, int V) {
	sort(edges.begin(), edges.end(), [](const edge<T> &a, const edge<T> &b) {
		return a.cost < b.cost;
	});
	UnionFind unionFind(V);
	T res = 0;
	for (edge<T> &e: edges) {
		if (unionFind.unite(e.to, e.from)) {
			res += e.cost;
		}
	}
	return res;
}


