vector<int> f(1000000);

void Stworz()
{
    for (int i = 0; i < 1000000; ++i)
        f[i] = i;
}

int Find(int a)
{
    if (f[a] == a)
        return a;
    int fa = Find(f[a]);
    f[a] = fa;
    return fa;
}

void Union(int a, int b)
{
    int fa = Find(a);
    int fb = Find(b);
    if (fa != fb)
        f[fa] = fb;
}

