ll prim(int k){
    priority_queue<ii, vector<ii>, greater<ii> > q;
    ll u;
    long long minimumCost = 0;
    ii p;
    q.push(mp(0, k));
    while(!q.empty())
    {
        p = q.top();
        q.pop();
        k = p.second;
        if(marked[k] == true)
            continue;
        minimumCost += p.fi;
        marked[k] = true;
        for(ll i = 0;i < v[k].size();++i)
        {
            u = v[k][i].se;
            if(marked[u] == false)
                q.push(v[k][i]);
        }
    }
    return minimumCost;
}

