  sort(road.begin(), road.end(), [](const auto& a, const auto& b){ return a[0]<b[0]; });
  ll cost = 0;
  ll use = 0;
  for (int i=0;;i++){
    if (use==n-1) break;
    if (!same(road[i][1], road[i][2])){
      use++;
      cost += road[i][0];
      unite(road[i][1], road[i][2]);
    }
  }
  cout << cost << endl;
}

