            int fi = find(i);
            int fj = find(j);
            auto pa = mp(fi, fj);
            if(fi != fj) {
                if (costs.count(pa) && costs[pa] < cost) {
                    continue;
                }
                costs[pa] = cost;
                p.push_back(make_pair(cost, make_pair(i, j)));
            }
        }
    }

    sort(p.begin(), p.end());

    int sum = 0;
    for (int i = 1; i < n;) {
        auto mm = p.front();
        if(find(mm.second.first) != find(mm.second.second)){
            unio(mm.second.first, mm.second.second);
            sum += mm.first;
            i++;
        }
        p.pop_front();
    }

    cout << sum << endl;
    return 0;
}

