ll rep[100001] , sz[100001];
ll find(ll u)
{
    return rep[u] == u ? u : rep[u] = find(rep[u]);
}
bool join(ll a , ll b)
{
    a = find(rep[a]) , b = find(rep[b]);
    if (a == b)
        return false;
    if (sz[a] < sz[b])
        swap(a , b);
    sz[a] += sz[b];
    rep[b] = a;
    return true;
}
int main()
{
    ll n;
