    sort(vy.begin() , vy.end());
    for (int i = 1; i < n; i++)
        mop[vx[i].first - vx[i-1].first].push_back({vx[i].second , vx[i-1].second});
    for (int i = 1; i < n; i++)
        mop[vy[i].first - vy[i-1].first].push_back({vy[i].second , vy[i-1].second});
