set<pii > s;

void insertX(int x, int id) {
  if(!sx.size()) return;
  it = sx.lower_bound(mp(x, id));
  if(it == sx.end()) {
    pii p = *sx.rbegin();
    s.insert(mp(abs(p.FF - x), p.SS));
    return;
  }
  s.insert(mp(abs((*it).FF - x), (*it).SS));
  if(it == sx.begin()) return;
  it--;
  s.insert(mp(abs((*it).FF - x), (*it).SS));
}

void insertY(int x, int id) {
  if(!sy.size()) return;
  it = sy.lower_bound(mp(x, id));
  if(it == sy.end()) {
    pii p = *sy.rbegin();
    s.insert(mp(abs(p.FF - x), p.SS));
    return;
  }
  s.insert(mp(abs((*it).FF - x), (*it).SS));
  if(it == sy.begin()) return;
  it--;
  s.insert(mp(abs((*it).FF - x), (*it).SS));
}

