	return min(abs(a.x-b.x),abs(a.y-b.y));
}
vector<int> up;
int fp(int u){
	if(up[u]<0) return u;
	else return up[u] = fp(up[u]);
}
void unite(int u,int v){
	int x = fp(u);
	int y = fp(v);
	if(x!=y) up[x]=y;
}
signed main() {
