	for(auto it = p.begin();it!=prev(p.end());it++){
		int d = dist(*it,*next(it));
		pq.push({d,*it,*next(it)});
	}
	sort(p.begin(),p.end(),[](ii lhs,ii rhs){return lhs.y<rhs.y;});
