int p[N];
int getf(int x)
{
    int i=x,j;
    while(p[i]!=i)i=p[i];
    while(p[x]!=i){j=p[x];p[x]=i;x=j;}
    return i;
}
void merge(int a,int b)
{
    a=getf(a);b=getf(b);
    p[a]=b;
}
int main()
{
