signed main() {
	int N, cnt = 0;
	cin >> N;
	//入力を取る、既にx座標もしくはy座標が登録されている点は登録された点からコスト0で行けるので消す
	for (int i = 0; i < N; i++) {
		int inX, inY;
		cin >> inX >> inY;
		if (xPos[inX] == 0 && yPos[inY] == 0) {
			xPos[inX]++;
			yPos[inY]++;
			XtoCnt[inX] = cnt;
			YtoCnt[inY] = cnt;
			CntToX[cnt] = inX;
			CntToY[cnt] = inY;
			XtoY[inX] = inY;
			YtoX[inY] = inX;
			x.push_back(inX);
			y.push_back(inY);
			cnt++;
		}
	}
	sort(x.begin(), x.end());
	sort(y.begin(), y.end());

	Graph g(x.size());
	//グラフを構築
	for (int i = 0; i < x.size() - 1; i++) {
		int yPos = XtoY[x[i]], yPos2 = XtoY[x[i+1]];
		int costX = abs(x[i] - x[i + 1]), costY = abs(yPos - yPos2);
		add_edge(g, XtoCnt[x[i]], XtoCnt[x[i + 1]], min(costX, costY));

		int xPos = YtoX[y[i]], xPos2 = YtoX[y[i+1]];
		costY = abs(y[i] - y[i + 1]); costX = abs(xPos - xPos2);
		add_edge(g, YtoCnt[y[i]], YtoCnt[y[i + 1]], min(costX, costY));
	}
	cout << kruskal(g).first << "\n";

	return 0;
}

