ll dijkstra(vector<Edge>* g, ll n){
    set<ll> nodes;
    nodes.insert(0);

    ll sum = 0;
    priority_queue<Edge> que;
    for(auto e : g[0])  que.push({e.to, e.cost});

    while((ll)nodes.size() < n){
        Edge edge = que.top(); que.pop();
        if(0 < nodes.count(edge.to))   continue;

        nodes.insert(edge.to);
        for(auto e : g[edge.to])   que.push({e.to, e.cost});

        sum += edge.cost;
    }

    return sum;
}

