int f(int a) {
    if (p[a] != a)
        p[a] = f(p[a]);
    return p[a];
}

void merge(int a, int b) {
    int ar = f(a);
    int br = f(b);
    if (ar == br)
        return;
    if (r[ar] < r[br])
        p[ar] = br;
    else if (r[ar] > r[br])
        p[br] = ar;
    else {
        p[br] = ar;
        r[ar] = r[ar] + 1;
    }
    total += min(abs(x[a] - x[b]), abs(y[a] - y[b]));
}

void add_edge(int u, int v) {
    if (f(u) == f(v))
        merge(u, v);
}

