void prim() {
    ll i, u;
    for(i=0; i<N; i++) {
        d[i]=INF;
        color[i]=WHITE;
    }
    priority_queue<P> PQ;
    PQ.push(P(0, 0));
    d[0]=0;

    while(PQ.size()) {
        P f=PQ.top(); PQ.pop();
        u=f.second;

        color[u]=BLACK;
