	}

	for(int i = 1; i < c.size(); i++) {
		v[valc[c[i - 1]]].push_back({c[i] - c[i - 1], valc[c[i]]});
		v[valc[c[i]]].push_back({c[i] - c[i - 1], valc[c[i - 1]]});
