}
struct disjoint_set {
	vector<int> tree;
	disjoint_set(int n) {
		tree.resize(n, -1);
	}
	int find(int idx) {
		if (tree[idx] == -1)return idx;
		return tree[idx] = find(tree[idx]);
	}
	void Union(int a, int b) {
		int A = find(a);
		int B = find(b);
		if (A == B)return;
		tree[B] = A;
	}
};
