void prim(){
  int start, index_i, index_j, add;
  vector < int > s;
  Edge min_cost;
  bool used[M]={0};

  for(int i=0; i<n; i++){
    sort(edge[i].begin(), edge[i].end());
  }

  start=0;
  s.push_back(start);
  used[start]=true;
  for(int i=0; i<n-1; i++){
