    int sl=s.size();
    for(int j=0; j<sl; j++){
    	int l=edge[s[j]].size();
      for(int k=0; k<l; k++){
	if(used[edge[s[j]][k].to]==false && edge[s[j]][k].cost < min_cost.cost){
	  min_cost=edge[s[j]][k];
	  add=edge[s[j]][k].to;
	  index_i=s[j];
	  index_j=k;
	}
      }
    }
    edge[index_i][index_j].used=true;
    //edge[index_j][index_i].used=true;
    s.push_back(add);
    used[add]=true;
  }

}

class Point{
public:
  int id, x, y;
};

bool comp_x(Point a, Point b){
    return a.x < b.x;
}

bool comp_y(Point a, Point b){
    return a.y < b.y;
}

int main(int argc, char* argv[]){
	cin.tie(0);
	ios::sync_with_stdio(0);
	cout.precision(10);

	int x, y;

	cin>>n;
	vector<Point> p(n);

	edge.resize(n);
	for(int i=0; i<n; i++){
		cin>>p[i].x>>p[i].y;
		p[i].id=i;
	}


	int cost;
	sort(p.begin(), p.end(), comp_x);
	for(int i=0; i<n-1; i++){
		int j=i+1;
		while(j<n && p[i+1].x-p[i].x == p[j].x-p[i].x){
			cost=min(abs(p[i].x-p[i+1].x), abs(p[i].y-p[i+1].y));
			edge[p[i].id].push_back((Edge){p[i].id, p[i+1].id, cost, false});
			edge[p[i+1].id].push_back((Edge){p[i+1].id, p[i].id, cost, false});
			j++;
		}
	}
	for(int i=n-1; i>0; i--){
		int j=i-1;
		while(j>=0 && p[i].x-p[i-1].x == p[j].x-p[i].x){
			cost=min(abs(p[i].x-p[i-1].x), abs(p[i].y-p[i-1].y));
			edge[p[i].id].push_back((Edge){p[i].id, p[i-1].id, cost, false});
			edge[p[i-1].id].push_back((Edge){p[i-1].id, p[i].id, cost, false});
			j--;
		}
	}

	sort(p.begin(), p.end(), comp_y);
	for(int i=0; i<n-1; i++){
		int j=i+1;
		while(j<n && p[i+1].y-p[i].y == p[j].y-p[i].y){
			cost=min(abs(p[i].x-p[i+1].x), abs(p[i].y-p[i+1].y));
			edge[p[i].id].push_back((Edge){p[i].id, p[i+1].id, cost, false});
			edge[p[i+1].id].push_back((Edge){p[i+1].id, p[i].id, cost, false});
			j++;
		}
	}
	for(int i=n-1; i>0; i--){
		int j=i-1;
		while(j>=0 && p[i].y-p[i-1].y == p[j].y-p[i].y){
			cost=min(abs(p[i].x-p[i-1].x), abs(p[i].y-p[i-1].y));
			edge[p[i].id].push_back((Edge){p[i].id, p[i-1].id, cost, false});
			edge[p[i-1].id].push_back((Edge){p[i-1].id, p[i].id, cost, false});
			j--;
		}
	}

	prim();

	int c=0;
	for(int i=0; i<edge.size(); i++){
		int l=edge[i].size();
		for(int j=0; j<l; j++){
			if(edge[i][j].used){
				c+=edge[i][j].cost;
			}
		}
	}

	cout<<c<<endl;

	return 0;
}

