llong prim(int start) {
  fill(d, d + n + 1, INT_MAX);

  priority_queue<pair<llong, int> > q;
  d[start] = 0;
  q.push(make_pair(0, start));
  llong res = 0;

  while (!q.empty()) {
    int dist = -q.top().first;
    int a = q.top().second;
    q.pop();
    if (dist > d[a]) continue;
    res += dist;
    visited[a] = true;

    foreach(it, adj[a]) {
      int b = it->first;
      llong w = it->second;
      if (!visited[b] && w < d[b]) {
        d[b] = w;
        q.push(make_pair(-w, b));
      }
    }
  }

  return res;
}

