 座標 (a,b) にある街と座標 (c,d) にある街の間に道を造るのには、min(|a−c|,|b−d|) 円かかります。
 街と街の間以外に、道を造ることはできません。

 任意の 2 つの街の間を、道を何本か通って行き来できるようにするためは、最低で何円必要でしょうか。

=================================================================

解説=============================================================

================================================================
*/
struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

struct edge{
    ll u,v,cost;
    edge(){}
    edge(ll u,ll v,ll cost):u(u),v(v),cost(cost){}
    bool operator < (const edge& o) const{
        return cost < o.cost;
    }
    bool operator > (const edge& o) const{
        return cost > o.cost;
    }
};

ll solve(){
    ll N; cin >> N;
    vector<pll> p(N);
    for(int i = 0; i < N;i++) cin >> p[i].first >> p[i].second;
    vector<pll> xs(N),ys(N);
    for(int i = 0; i < N;i++){
        xs[i] = {p[i].first,i};
        ys[i] = {p[i].second,i};
    }

    sort(xs.begin(),xs.end()); sort(ys.begin(),ys.end());
    UnionFind uf(N);
    ll ret = 0;

    priority_queue<edge,vector<edge>,greater<edge>> pq;
    for(int i = 0; i < N-1;i++){
        pq.push(edge(xs[i].second,xs[i+1].second,xs[i+1].first-xs[i].first));
        pq.push(edge(ys[i].second,ys[i+1].second,ys[i+1].first-ys[i].first));
    }

    while(!pq.empty()){
        auto e = pq.top(); pq.pop();
        if(uf.findSet(e.u, e.v)) continue;

        ret += e.cost;
        uf.unionSet(e.u, e.v);
    }

    return ret;
}
int main(void) {
	cin.tie(0); ios::sync_with_stdio(false);
    cout << solve() << endl;
	return 0;
}

