    es.reserve(2 * N);
    rep(i, N) {
        P p;
        cin >> p.first >> p.second;
        if (ids.count(p)) continue;
        int n = ids.size();
        ids[p] = n;
        pos.push_back(p);
    }
    N = pos.size();
    add();
    // cout << es.size() << endl;
    sort(all(es));
    UnionFind uf(N);
    long long ans = 0;
    for (auto e : es) {
        if (!uf.same(e.from, e.to)) {
            ans += e.cost;
            uf.unite(e.from, e.to);
        }
    }
    cout << ans << endl;

    return 0;
}

