        return x;
    }
    else{
        return par[x] = find(par[x]);
    }
}

// xとyの属する集合を併合
void unite(int x, int y){
    x = find(x);
    y = find(y);
    if(x == y)  return;

    if(rank_u[x] < rank_u[y]){
        par[x] = y;
    }
    else{
        par[y] = x;
        if(rank_u[x] == rank_u[y])  rank_u[x]++;
    }
}

//xとyが同じ集合に属するかどうか
