		r[i] = 0; 
	} 
}

int find(int p){ 
	if(parent[p] == p) return p; 
	else return parent[p] = find(parent[p]); 
} 
void uni(int p, int q){ 
	p = find(p); 
	q = find(q); 
	if(r[p] < r[q]) parent[p] = q, size[q] += size[p]; 
	else parent[q] = p, size[p] += size[q]; 
	if(r[p] == r[q]) r[p]++; 
}


