bool cmp2(const roads &a, const roads &b) {
	return a.y < b.y;
}

bool cmp3(const roads &a, const roads &b) {
	return a.id < b.id;
}

void init() {
	for (int i = 1; i <= n; i++)
		par[i] = i;
}

int find(int x) {
	if (x == par[x])return x;
	return par[x] = find(par[x]);
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)return;
	par[x] = y;
}

bool same(int x, int y) {
	return find(x) == find(y);
}

int kruskal() {
	int sum = 0;
	init();
	for (int i = 0; i<cnt; i++) {
		roads r = road2[i];
		if (r.id == 0)unite(r.x, r.y);
		if (!same(r.x, r.y)) {
			unite(r.x, r.y);
			sum += r.id;
		}
	}
	return sum;
}

