int cfind (int x)
{
    if (x == cpar[x]) return x;
    return cpar[x] = cfind (cpar[x]);
}

bool uni (int a, int b)
{
    a = cfind (a);
    b = cfind (b);
    if (a == b) return false;
    cpar[a] = b;
    return true;
}

int main()
