		b[i*2+1].first=ty[i+1].first-ty[i].first;
		b[i*2+1].second.first=ty[i].second;
		b[i*2+1].second.second=ty[i+1].second;
	}
	sort(b,b+2*n);
	long long ans=0;
	int c=0;
	int x1,y1;
	for (int i=0;i<2*n;i++){
		x1=b[i].second.first;
		y1=b[i].second.second; 
		if (fnd(fa[x1])==fnd(fa[y1])){
			continue;
		}
		else{
			fa[fnd(x1)]=fnd(y1);
			c++;
			ans+=zdl(x1,y1);
			if (c==n-1){
				break;
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}

