{
	for(int i=0; i<maxn; i++)
	{
		par[i]=i;
	}
}
int find(int x)
{
	if(par[x]!=x)
	{
		return par[x]=find(par[x]);
	}
	return x;
}
bool unite(int x,int y)
{
	int fax=find(x),fay=find(y);
	if(fax==fay)return 1;
	if(fax==y)return 0;
	par[fax]=fay;
	return 1;
}
bool same(int x,int y)
{
	if(find(x)==find(y))return 1;
	return 0;
}
