    vy.push_back(P(y,i));
  }
  sort(vx.begin(),vx.end());
  sort(vy.begin(),vy.end());
  int cnt=0;
  for(int i=1;i<vx.size();i++){
    int u=vx[i-1].second;
    int v=vx[i].second;
    int cost=vx[i].first-vx[i-1].first;
    es[cnt++]=(edge){u,v,cost};
  }

  for(int i=1;i<vy.size();i++){
    int u=vy[i-1].second;
    int v=vy[i].second;
    int cost=vy[i].first-vy[i-1].first;
    es[cnt++]=(edge){u,v,cost};
  }
  E=cnt;
  cout<<kruskal()<<endl;

  return 0;
}

