	for(i=1; i<n; i++) bn[++bb].a=node[i].id,bn[bb].b=node[i+1].id,bn[bb].c=node[i+1].y-node[i].y;
	sort(bn+1,bn+bb+1);
	for(i=1; i<=bb; i++)
	{
		if(ff(bn[i].a)==ff(bn[i].b)) continue;
		fa[ff(bn[i].a)]=ff(bn[i].b);
		ans+=bn[i].c;
	}
	cout<<ans;
}

