		yplace y;
		y.node = i;
		y.x = L;
		y.y = R;
		xp.push_back(x);
		yp.push_back(y);
	}
	sort(xp.begin(), xp.end());
	sort(yp.begin(), yp.end());
	vector<Edge>edge;
	for (int i = 0; i < N - 1; i++) {
		Edge e;
		e.l = xp[i].node;
		e.r = xp[i + 1].node;
		e.cost = min(abs(xp[i].x - xp[i + 1].x), abs(xp[i].y - xp[i + 1].y));
		edge.push_back(e);
		e.l = yp[i].node;
		e.r = yp[i + 1].node;
		e.cost = min(abs(yp[i].x - yp[i + 1].x), abs(yp[i].y - yp[i + 1].y));
		edge.push_back(e);
	}
	sort(edge.begin(), edge.end());
	UnionFind uf(N);
	long long int ans = 0;
	for (auto i : edge) {
		if (uf.Check_Same(i.l, i.r)) {
			continue;
		}
		uf.Unite(i.l, i.r);
		ans += i.cost;
	}
	cout << ans << endl;
	return 0;
}

