struct Edge {
    ll from;
    ll to;
    ll cost;
    Edge(ll from, ll to, ll cost) : from(from), to(to), cost(cost) {}
};

ll group_of(vector<ll>& union_find, ll idx) {
    ll i = idx;
    for (; union_find[i] != i; i = union_find[i]);
    union_find[idx] = i;
    return i;
}

void unite(vector<ll>& union_find, ll from, ll to) {
    // 多分これだと間に合わない
    union_find[to] = from;
}

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
    cin >> N;
    vector<ll> xidx(N), yidx(N), union_find(N);
    for (ll i = 0; i < N; i++) {
        xidx[i] = i;
        yidx[i] = i;
        union_find[i] = i;
    }

    vector<p> town(N);
    for (ll i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        town[i] = p(x, y);
    }

    sort(xidx.begin(), xidx.end(), [town](ll left, ll right) {
        p l = town[left];
        p r = town[right];
        if (l.first < r.first) {
            return true;
        } else if(l.first == r.first) {
            return l.second < r.second;
        } else {
            return false;
        }
    });

    sort(yidx.begin(), yidx.end(), [town](ll left, ll right) {
        p l = town[left];
        p r = town[right];
        if (l.second < r.second) {
            return true;
        } else if (l.second == r.second) {
            return l.first < r.first;
        } else {
            return false;
        }
    });

    vector<Edge> E;
    for (ll i = 0; i < N - 1; i++) {
        ll d = town[xidx[i + 1]].first - town[xidx[i]].first;
        E.push_back(Edge(xidx[i], xidx[i + 1], d));
    }
    for (ll i = 0; i < N - 1; i++) {
        ll d = town[yidx[i + 1]].second - town[yidx[i]].second;
        E.push_back(Edge(yidx[i], yidx[i + 1], d));
    }

    sort(E.begin(), E.end(), [](Edge l, Edge r) {
        return l.cost < r.cost;
    });

    ll ans = 0;
    for (auto&& e : E) {
        ll from_group = group_of(union_find, e.from);
        ll to_group = group_of(union_find, e.to);
        if (from_group == to_group) {
            continue;
        }

        // cout << "add" << endl;

        ans += e.cost;
        unite(union_find, from_group, to_group);
        /*
        for (auto&& u : union_find) {
            cout << u << " ";
        }
        cout << endl;
        */
    }

    cout << ans << endl;
    return 0;
}

