int prim() {
    int s = 0;
    used.assign(n, false);
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.emplace(0, s);
    int ret = 0;
    while (!pq.empty()) {
        P p = pq.top();
        pq.pop();
        int v = p.second;
        if (used[v]) continue;
        used[v] = true;
        ret += p.first;
        for (auto &e : G[v]) pq.emplace(e.cost, e.to);
    }
    return ret;
}

