int loadvec(vector<int>& v, int N) {
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin) == NULL) return -1;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}

class UnionFind {
  vector<int> data;
 public:
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

ll solve(int n, vector<int>&x, vector<int>&y) {
    assert(x.size() == n && y.size() == n);

    vector<ii> xx(n), yy(n);
    rep(i, n) {
        xx[i] = ii(x[i], i);
        yy[i] = ii(y[i], i);
    }
    sort(ALL(xx));
    sort(ALL(yy));

    UnionFind uf(n);

    priority_queue<pair<int,ii>> pq;
    rep(i, n-1) {
        pq.push(make_pair(-(xx[i+1].first - xx[i].first),
                          ii(xx[i].second, xx[i+1].second)));
        pq.push(make_pair(-(yy[i+1].first - yy[i].first),
                          ii(yy[i].second, yy[i+1].second)));
    }

    ll cost = 0;
    while (!pq.empty()) {
        int d = -pq.top().first;
        int u = pq.top().second.first, v = pq.top().second.second; pq.pop();
        if (uf.root(u) == uf.root(v)) continue;
        cost += d;
        uf.unionSet(u, v);
        if (uf.size(u) == n) break;
    }
    return cost;
}

