struct Town
{
	LL i;
	LL x;
	LL y;

	Town()
	{
	}

	Town(LL _i, LL _x, LL _y)
	{
		i = _i;
		x = _x;
		y = _y;
	}

	static bool greater_x(const Town& t0, const Town& t1)
	{
		return t0.x < t1.x;
	}
	static bool greater_y(const Town& t0, const Town& t1)
	{
		return t0.y < t1.y;
	}
};

// Union Find
struct UnionFind
{
	const LL N;
	VLL parent;
	VLL rank;

	UnionFind(LL n)
		:N(n)
	{
		parent = VLL(N);
		rank = VLL(N, 0);
		for (size_t i = 0; i < N; i++) {
			parent[i] = i;
		}
	}

	int root(LL i)
	{
		return parent[i] == i ? i : parent[i] = root(parent[i]);
	}

	bool same(LL i, LL j)
	{
		return root(i) == root(j);
	}

	void unite(LL i, LL j)
	{
		i = root(i);
		j = root(j);
		if (i == j) {
			return;
		}

		if (rank[i] < rank[j]) {
			parent[i] = j;
		}
		else {
			parent[j] = i;
			if (rank[i] == rank[j]) {
				rank[i]++;
			}
		}
	}

	bool isOne()
	{
		for (size_t i = 1; i < N; i++) {
			if (!same(0, i)) {
				return false;
			}
		}
		return true;
	}
};

template <typename T>
struct Graph
{
	struct Node
	{
		T value;

		Node(T _value)
		{
			value = _value;
		}
	};

	struct Edge
	{
		LL i;
		LL j;
		LL cost;

		Edge(LL _i, LL _j, LL _cost)
		{
			i = _i;
			j = _j;
			cost = _cost;
		}

		static bool greater(const Edge& e0, const Edge& e1)
		{
			return e0.cost < e1.cost;
		}
	};

	vector<Node> nodes;
	vector<Edge> edges;

	void add(Node node)
	{
		nodes.push_back(node);
	}

	void add(Edge edge)
	{
		edges.push_back(edge);
	}

	LL getMSTLength()
	{
		LL ret = 0;
		sort(edges.begin(), edges.end(), Edge::greater);

		UnionFind uf(nodes.size());
		for (size_t i = 0; i < edges.size(); i++) {
			if (uf.isOne()) {
				break;
			}
			if (!uf.same(edges[i].i, edges[i].j)) {
				uf.unite(edges[i].i, edges[i].j);
				ret += edges[i].cost;
			}
		}
		return ret;
	}
};



