int Find(int x) {
    if (root[x] == -1) return x;
    if (root[x] != x) {
        root[x] = Find(root[x]);
    }
    return root[x];
}

bool Union(int a, int b) {
    int r1 = Find(a), r2 = Find(b);
    if (r1 != r2) {
        root[r1] = r2;
        return true;
    }
    return false;
}

int main() {
