    memset(root, -1, sizeof(root));
    sort(ind, ind + n, cmpx);
    for (int i = 1; i < n; ++i) {
        pq.push({x[ind[i]] - x[ind[i - 1]], ind[i], ind[i - 1]});
    }
    sort(ind, ind + n, cmpy);
