			segment.a = node[i - 1].sign;
			segment.b = node[i].sign;
			segment.dis = node[i].y - node[i - 1].y;
			vec.push_back(segment);
		}
		sort(vec.begin(), vec.end(), cmp);
		LL ans = 0;
		for(int i = 0; i < vec.size(); i++) {
			if(connect(vec[i].a, vec[i].b)) {
				ans += vec[i].dis;
			}
		}
		printf("%lld\n", ans);
	}
	return 0;
}

