int find(int x){return x==par[x]?x:par[x]=find(par[x]);}
bool union_(int u,int v)
{
	u=find(u);
	v=find(v);
	if (u==v) return false;
	par[u]=v;
	return true;
}
int dist(int x,int y)
{
	return min(abs(px[x]-px[y]),abs(py[x]-py[y]));
}
