		}

		if (y[i] == miny) {
			dy = sy[1] - y[i];
		}
		else if (y[i] == maxy) {
			dy = y[i] - sy[N - 2];
		}
		else {
			dy = y[i] - *(upper_bound(all(sy), y[i]) - 2);
			dy = min(dy, *(lower_bound(all(sy), y[i]) + 1) - y[i]);
		}
		//cout << i << " " << dx << " " << dy << endl;
		ans += min(dx, dy);
		mind = min(mind, min(dx, dy));
	}

	cout << ans - mind << endl;

	return 0;
}

