class disjoint_set {
    vector<int> p;
public:
    int count;
    disjoint_set(int n) : p(n, -1), count(0) {}
    int root(int i) { return p[i] >= 0 ? p[i] = root(p[i]) : i; }
    bool same(int i, int j) { return root(i) == root(j); }
    int size(int i) { return -p[root(i)]; }
    void merge(int i, int j) {
        count++;
        i = root(i), j = root(j);
        if (i == j) return;
        if (p[i] > p[j]) swap(i, j);
        p[i] += p[j], p[j] = i;
    }
    int size(int i, int j) {
        if(same(i,j)) return size(i);
        else return size(i) + size(j);
    }
};

int main(){
    int n; cin >> n;
    using P = pair<int,long>;
    vector<P> h,w;
    rep(i,n){
        int x,y; cin >> x >> y;
        x--;y--;
        h.emplace_back(x,i);
        w.emplace_back(y,i);
    }
    sort(all(h));
    sort(all(w));

    /* cerr << "h : " << h << endl; */
    /* cerr << "w : " << w << endl; */
    using T = tuple<int,int,int>;
    vector<T> h2,w2;
    rep(i,n-1){
        h2.emplace_back(h[i+1].first-h[i].first, h[i].second, h[i+1].second);
        w2.emplace_back(w[i+1].first-w[i].first, w[i].second, w[i+1].second);
    }
    sort(all(h2));
    sort(all(w2));
    int m = h2.size();

    disjoint_set uf(n);
    ll ans = 0;
    int i=0,j=0;
    while(i < m && j < m){
        ll H = LINF;
        ll W = LINF;

        if(i<m){
            int l,x,y;
            tie(l,x,y) = h2[i];
            while(i<m && uf.same(x,y)){
                i++;
                if(i==m) break;
                tie(l,x,y) = h2[i];
            }
            if(i<m){
                tie(l,x,y) = h2[i];
                H = l;
            }
        }
        if(j<m){
            int l,x,y;
            tie(l,x,y) = w2[j];
            while(j<m && uf.same(x,y)){
                j++;
                if(j==m) break;
                tie(l,x,y) = w2[j];
            }
            if(j<m){
                tie(l,x,y) = w2[j];
                W = l;
            }
        }

        if(H == LINF && W == LINF){
            break;
        }

        int l,x,y;
        if(H < W){
            tie(l,x,y) = h2[i];
            ans += l;
            uf.merge(x,y);
        }else{
            tie(l,x,y) = w2[j];
            ans += l;
            uf.merge(x,y);
        }
    }
    cout << ans << endl;
}

