int find(int x) {
  return fa[x] == x ? x : (fa[x] = find(fa[x]));
}

void mrg(int x, int y) {
  x = find(x), y = find(y);
  if (x != y) {
    fa[x] = y;
  }
}

Edge get(set <Edge> &a) {
  auto it = a.begin();
  while (it != a.end()) {
    auto e = *it;
    if (find(e.a) != find(e.b)) {
      return e;
    }
    it = a.erase(it);
  }
  return Edge{-1, -1, -1};
}

Edge get(set < pair <int, int> > &st, pair <int, int> x) {
  auto it = st.lower_bound(x);
  if (it == st.begin()) {
    return Edge{-1, -1, -1};
  }
  auto itx = it--;
  itx++;
  if (itx == st.end()) {
    return Edge{-1, -1, -1};
  }
  Edge a;
  a.w = itx->first - it->first;
  a.a = itx->second;
  a.b = it->second;
  return a;
}

void go(int a) {
  Edge nx = get(st, make_pair(x[a], a));
  Edge ny = get(st2, make_pair(y[a], a));
  st.erase(make_pair(x[a], a));
  st2.erase(make_pair(y[a], a));
  if (nx.w != -1) {
    stx.insert(nx);
  }
  if (ny.w != -1) {
    sty.insert(ny);
  }
}

void erase(set <Edge> &a) {
  auto e = *a.begin();
  a.erase(a.begin());
  mrg(e.a, e.b);
  //go(e.a);
  //go(e.b);
}

