        points[sort_p[i]].edge.push_back({sort_p[i - 1], points[sort_p[i]].y - points[sort_p[i - 1]].y});

    bool connected[100000]{};
    long long sum{};
    connected[0] = true;
    for (auto &e: points[0].edge)
        points[e.first].distance = e.second;
    for (int i = 1; i < n; i++)
