class DSU {
	std::vector<int> dat;

public:
	DSU(int n) : dat(n, -1) {}

	bool unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y)	return false;
		if (dat[x] > dat[y]) {
			std::swap(x, y);
		}
		dat[x] += dat[y];
		dat[y] = x;
		return true;
	}

	int find(int x) {
		if (dat[x] < 0) {
			return x;
		}
		return dat[x] = find(dat[x]);
	}
};

int main() {
