LL cost(pair<LL,LL> A,pair<LL,LL> B){
	LL ret = LINF;
	ret = min(ret,abs(A.first-B.first) );
	ret = min(ret,abs(A.second-B.second) );
	return ret;
}
void solve(){
	int N;
	cin >> N;
	vector< pair<LL,LL> > posXY(N),posYX(N);
	for(int i=0;i<N;++i){
		cin >> posXY[i].first >> posXY[i].second;
