	if( posXY[0] == posXY[N-1] ){
		//全て同じ位置
		cout << 0 << endl;
		return;
	}
	///
	//重複チェック
	vector< pair<LL,LL> > v = posXY;
	UNIQUE( v );
	int NUM = v.size();//位置が異なる町の数
