	priority_queue< vector<LL>
		, vector< vector<LL> > , greater< vector<LL> > > que;
	pair<LL,LL> A,B;
	vector<LL> temp(5);

	//////
	map< pair<LL,LL>,int> index;
	int No = 0;
	for(int i=0;i<N;++i){
