			index[ posXY[i] ] = No;
			++No;
		}
	}
	UnionFind uf( No );
	//////
	for(int i=0;i<N;++i){
		if( i > 0 ){
			A = posXY[i-1];
			B = posXY[i];
			LL res = cost( A, B );
			if( A > B ){
				swap(A,B);
			}
			temp[0] = res;
			temp[1] = A.first;
			temp[2] = A.second;
			temp[3] = B.first;
			temp[4] = B.second;
			que.push( temp );
		}
		if( i+1 < N ){
			A = posXY[i];
			B = posXY[i+1];
			LL res = cost( A, B );
			if( A > B ){
				swap(A,B);
			}
			temp[0] = res;
			temp[1] = A.first;
			temp[2] = A.second;
			temp[3] = B.first;
			temp[4] = B.second;
			que.push( temp );
		}
		///////////////YX逆
		if( i > 0 ){
			A = posYX[i-1];swap(A.first,A.second);
			B = posYX[i];swap(B.first,B.second);
			LL res = cost( A, B );
			if( A > B ){
				swap(A,B);
			}
			temp[0] = res;
			temp[1] = A.first;
			temp[2] = A.second;
			temp[3] = B.first;
			temp[4] = B.second;
			que.push( temp );
		}
		if( i+1 < N ){
			A = posYX[i];swap(A.first,A.second);
			B = posYX[i+1];swap(B.first,B.second);
			LL res = cost( A, B );
			if( A > B ){
				swap(A,B);
			}
			temp[0] = res;
			temp[1] = A.first;
			temp[2] = A.second;
			temp[3] = B.first;
			temp[4] = B.second;
			que.push( temp );
		}
	}

	LL ans = 0;
	map< pair<LL,LL>, int > MAP;
	int inside = 0;
	while( !que.empty() ){
		temp = que.top();que.pop();
		A.first = temp[1];
		A.second = temp[2];
		B.first = temp[3];
		B.second = temp[4];

		if( uf.same( index[A], index[B] ) ){
		}else{
			//
			ans += temp[0];
			uf.add( index[A],index[B] );
		}
	}
	cout << ans << endl;
}
