using namespace std;

class City{
public:
    int ID;
    int X, Y;

    bool operator<(const City &c) const{
        if(X < c.X){
            return true;
        }else if(X > c.X){
            return false;
        }else if(Y < c.Y){
            return true;
        }
        return false;
    }
};

bool cmp_Y(const City &a, const City &b){
    if(a.Y < b.Y){
        return true;
    }else if(a.Y > b.Y){
        return false;
    }else if(a.X < b.X){
        return true;
    }
    return false;
}

long edge_cost(City a, City b){
    return min(abs(a.X-b.X), abs(a.Y-b.Y));
}

class Edge{
public:
    int to, from;
    long cost;

    void set(int t, int f, long c){
        to = t;
        from = f;
        cost = c;
    }

    bool operator<(const Edge &e) const{
        if(cost < e.cost){
            return true;
        }
        return false;
    }
};


vector<long> vertex;

long root(long x) {
    if(vertex[x]<0){
        return x;
    }
    return vertex[x] = root(vertex[x]);
}

void unite(long x, long y) {
    x = root(x);
    y = root(y);

    if (x == y){
        return;
    }
    if(-vertex[x] < -vertex[y]){
        swap(x, y);
    }
    vertex[x] -= -vertex[y];
    vertex[y] = x;
}

bool same(long x, long y) {
    return root(x) == root(y);
}
long size(long x) {
    return -vertex[root(x)];
}


