    bool operator< (const Node &r) const{
        return cost > r.cost;
    }
};


ll dijkstra(vector<Edge>* g, ll n){
    ll INF = pow(10, 10);

    set<ll> nodes;
    nodes.insert(0);

    ll sum = 0;

    while((ll)nodes.size() < n){
        ll next = 0;
        ll cost = INF;
        for(auto src : nodes){
            for(auto e : g[src]){
                if(0 < nodes.count(e.to))   continue;
                if(e.cost < cost){
                    next = e.to;
                    cost = e.cost;
                }
            }
        }

        nodes.insert(next);
        sum += cost;
    }

    return sum;
}

int main(){
    ll n;
    cin >> n;
    vector<ll> x(n);
    vector<ll> y(n);
    rep(i, n)   cin >> x[i] >> y[i];


    vector<Edge> g[n];

    rep(src, n){
        rep(sink, n){
            if(src == sink) continue;

            ll xCost = abs(x[src] - x[sink]);
            ll yCost = abs(y[src] - y[sink]);
            g[src].push_back({sink, min(xCost, yCost)});
        }
    }


    cout << dijkstra(g, n) << endl;


    return 0;
}

