    UnionFind uf(N);
    int cost = 0;
    REP(i, (N - 1) * 2) {
        auto e = edges[i];
        if (!uf.same(e.second.first, e.second.second)) {
            uf.unite(e.second.first, e.second.second);
            cost += e.first;
        }
        if (uf.set_size(0) == N) break;
    }
    cout << cost << endl;
    return 0;
}


