        xlst.push_back(make_pair(x, i));
        ylst.push_back(make_pair(y, i));
    }
    sort(xlst.begin(), xlst.end());
    sort(ylst.begin(), ylst.end());

    make_graph(xlst);
    make_graph(ylst);

    used.resize(N, false);

    priority_queue<P, vector<P>, greater<P> > q;
    q.push(make_pair(0, 0));
    int weight_sum = 0;
    while (!q.empty())
    {
        P p = q.top();
        q.pop();
        if (used[p.second]) continue;
        used[p.second] = true;
