constexpr static int MAXN = 2e5;

int n;
int x[MAXN], y[MAXN];

int64_t total = 0;
int p[MAXN], r[MAXN];

int f(int a) {
    if (p[a] != a)
        p[a] = f(p[a]);
    return p[a];
}

void merge(int a, int b) {
    int ar = f(a);
    int br = f(b);
    if (ar == br)
        return;
    if (r[ar] < r[br])
        p[ar] = br;
    else if (r[ar] > r[br])
        p[br] = ar;
    else {
        p[br] = ar;
        r[ar] = r[ar] + 1;
    }
    total += min(abs(x[a] - x[b]), abs(y[a] - y[b]));
}

int main() {
    cin >> n;
    vector <pair <int, int>> xv, yv;
    for (int i = 0; i < n; i++) {
