    this->from = from;
    this->to = to;
    this->cost = cost;
  }
};

// 昇順ソート
bool cmp(const T &a, const T &b) { return a.cost < b.cost; }

void solve(long long N, std::vector<long long> x, std::vector<long long> y) {
  vector<pll> xi;
  vector<pll> yi;
  rep(i, 0, N) {
    xi.push_back(mp(x[i], i));
    yi.push_back(mp(y[i], i));
  }

  sort(all(xi));
  sort(all(yi));

  vector<T> edges;
  rep(i, 0, N - 1) {
    ll xi1 = xi[i].sc;
    ll xi2 = xi[i + 1].sc;
    ll cost = min(abs(x[xi1] - x[xi2]), abs(y[xi1] - y[xi2]));
    edges.push_back(T(xi1, xi2, cost));

    ll yi1 = yi[i].sc;
    ll yi2 = yi[i + 1].sc;
    cost = min(abs(x[yi1] - x[yi2]), abs(y[yi1] - y[yi2]));
    edges.push_back(T(yi1, yi2, cost));
  }

  // 最小全域木(クラスカル法)
  vb checked(N);
  ll ans = 0;
  sort(all(edges), cmp);
  rep(i, 0, edges.size()) {
    ll from = edges[i].from;
    ll to = edges[i].to;
    ll cost = edges[i].cost;

    if (!checked[from] || !checked[to]) {
      checked[from] = true;
      checked[to] = true;
      ans += cost;
    }
  }

  print(ans);
}

