// n要素で初期化
void init(int n){
	for(int i = 0; i < n; i++){
		par[i] = i;
		rank[i] = 0;
	}
}

// 木の根を求める
int find(int x){
	if(par[x] == x){
		return x;
	}
	return par[x] = find(par[x]);
}

// xとyの属する集合を併合
void unite(int x, int y){
	int x_par = find(x);
	int y_par = find(y);
	if(x_par == y_par){
		return;
	}

	if(rank[x_par] < rank[y_par]){
		par[x_par] = y_par;
	}else{
		par[y_par] = x_par;
		if(rank[x_par] == rank[y_par]){
			rank[x_par]++;
		}
	}
}

bool same(int x, int y){
	return (find(x) == find(y));
}

