vector<int> uf;

int find(int x){
    if(uf[x] == x){
        return x;
    }else{
        return uf[x] = find(uf[x]);
    }
}

void unio(int x, int y){
    uf[find(x)] = uf[find(y)];
}

int main(){
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int xx,yy;
        cin >> xx >> yy;
        x.push_back(xx);
        y.push_back(yy);
    }

    for (int i = 0; i < n; i++) {
        uf.push_back(i);
    }

    for (int i = 0; i < n; i++) {
        for (int j = i+1; j < n; j++) {
            int cost = min(abs(x[i] - x[j]) , abs(y[i]-y[j]));
            p.push_back(make_pair(cost, make_pair(i, j)));
        }
    }

    sort(p.begin(), p.end());

    int sum = 0;
    for (int i = 1; i < n;) {
        auto mm = p.front();
        if(find(mm.second.first) != find(mm.second.second)){
            unio(mm.second.first, mm.second.second);
            sum += mm.first;
            i++;
        }
        p.pop_front();
    }

    cout << sum << endl;
    return 0;
}

