struct edge { int u, v, cost; };

bool comp(const edge& e1, const edge& e2) {
		return e1.cost < e2.cost;
}

int N;
vector<P> vx, vy;
vector<edge> es;
int par[100001], rk[100001];
ll res = 0;

void init(int n) {
	rep(i, n) {
		par[i] = i;
		rk[i] = 0;
	}
}

int find(int x) {
	if(par[x] == x) return x;
	else return par[x] = find(par[x]);
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if(x == y) return;

	if(rk[x] < rk[y]) par[x] = y;
	else par[y] = x;
	if(rk[x] == rk[y]) ++rk[x];
}

bool same(int x, int y) {
	return find(x) == find(y);
}

void kruskal() {
	sort(es.begin(), es.end(), comp);
	init(N);
	rep(i, es.size()) {
		edge e = es[i];
		if(!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}
	}
}

