	FOR(i, 1, vx.size()) {
		es.push_back({vx[i - 1].second, vx[i].second, vx[i].first - vx[i - 1].first});
	}
	FOR(i, 1, vy.size()) {
		es.push_back({vy[i - 1].second, vy[i].second, vy[i].first - vy[i - 1].first});
	}
	kruskal();
	printf("%lld\n", res);
	return 0;
}

