class UNION_FIND
{
  private:
    vector<int> par, myrank;
  public:
    UNION_FIND(int n) {
      par = vector<int>(n);
      myrank = vector<int>(n,0);
      for (int i = 0; i < n; i++) {
        par[i] = i;
      }
    }
    int find(int x) {
      if (par[x] == x) return x;
      return par[x] = find(par[x]);
    }
    void unite(int x, int y) {
      x = find(x);
      y = find(y);
      if (x == y) return;
      if (myrank[x] < myrank[y]) {
        par[x] = y;
      } else {
        par[y] = x;
        if(myrank[x] == myrank[y]) myrank[x]++;
      }
    }
    bool same(int x, int y)
    {
      return find(x) == find(y);
    }
};

int prim(const vector< vector<edge> >& G)
{
  int sum = 0;
  vector<bool> used(G.size(), false);
  priority_queue<P, vector<P>, greater<P> > que;
  que.push(P(0, 0));
  while (!que.empty()) {
    int cost = que.top().first;
    int from = que.top().second;
    que.pop();
    if (used[from]) continue;
    used[from] = true;
    sum += cost;
    for (int i = 0; i < G[from].size(); i++) {
      edge e = G[from][i];
      if (!used[e.to]) {
        que.push(P(e.cost, e.to));
      }
    }
  }
  return sum;
}



signed main()
{
  int N; cin >> N;
  vec< pair<int,int> > x(N), y(N);
  rep(i, 0, N) {
    int a, b; cin >> a >> b;
    x[i] = MP(a, i);
    y[i] = MP(b, i);
  }
  SORT(x); SORT(y);

  vec< vec<edge> > G(N, vec<edge>());
  rep(i, 0, N-1) {
    int dist = abs(x[i+1].first - x[i].first);
    int u = x[i].second, v = x[i+1].second;
    G[u].PB((edge){ v, dist });
    G[v].PB((edge){ u, dist });
  }
  rep(i, 0, N-1) {
    int dist = abs(y[i+1].first - y[i].first);
    int u = y[i].second, v = y[i+1].second;
    G[u].PB((edge){ v, dist });
    G[v].PB((edge){ u, dist });
  }

  cout << prim(G) << endl;

  return 0;
}

