	sort(all(y));
	SET(done, 0);
	FOR (i, x.sz) {
		int idx = x[i].second;
		if (i)
			closest[idx].pb(x[i - 1].second);
		if (i < x.sz - 1)
			closest[idx].pb(x[i + 1].second);
	}

	FOR (i, y.sz) {
		int idx = y[i].second;
		if (i)
			closest[idx].pb(y[i - 1].second);
		if (i < y.sz - 1)
			closest[idx].pb(y[i + 1].second);
	}

	LL ret = 0LL;
	heap.push(make_pair(0, 0));
	while (!heap.empty()) {
		pair<int, int> el = heap.top();
		heap.pop();
		int idx = el.second, dist = el.first;
		if (done[idx])
			continue;
		done[idx] = true;
		ret -= dist;
		FOR (i, closest[idx].sz) {
			int w = closest[idx][i];
			if (done[w])
				continue;
			LL d = min(abs(p[idx].first - p[w].first), abs(p[idx].second - p[w].second));
