int prim(){
  for(int i=0;i<N;i++){
    used[i] = false;
  }

  ll res = 0;

  priority_queue<pi, vector<pi>, greater<pi> >Q;
  Q.push(pi(0, 0));

  while(!Q.empty()){
    pi q = Q.top(); Q.pop();
    int p = q.second;
    int cost = q.first;
    if(used[p]) continue;

    res += cost;
    used[p] = true;

    for(int i=0;i<G[p].size();i++){
      pi next = G[p][i];
      Q.push(pi(next.second, next.first));
    }
  }

  return res;
}

