ll kruskal(vector<edge>  es) {
    sort(es.begin(), es.end(), comp);
    UnionFind uf;
    uf.init(V);
    ll res = 0;
    for (ll i=0; i<es.size(); ++i) {
        edge e = es[i];
        if (!uf.same(e.u, e.v)) {
            uf.unite(e.u, e.v);
            res += e.cost;
        }
    }
    return res;
}


