			dis_x[box_x[i] % MOD] = box_x[i + 1] / MOD - box_x[i] / MOD;
			dis_y[box_y[i] % MOD] = box_y[i + 1] / MOD - box_y[i] / MOD;
			continue;
		}
		if (i == N - 1) {
			dis_x[box_x[i] % MOD] = box_x[i] / MOD - box_x[i - 1] / MOD;
			dis_y[box_y[i] % MOD] = box_y[i] / MOD - box_y[i - 1] / MOD;
