		auto ecid1 = ex_to_ecid[i - 1];
		auto ecid2 = ex_to_ecid[i];
		auto dist = x_decode[i] - x_decode[i - 1];
		edges.pb(edge{ ecid1, ecid2, abs(dist) });
	}
}

