// Union-Find 木 (Verified: AtCoder Typical Contest 001 B)
struct UnionFind {
private:
    const int n;
    int __size;
    vector<int> uf;
public:
    // 初期化 UnionFind uni(n) のように宣言すれば良い
    UnionFind(int _n) : n(_n), __size(_n), uf(_n, -1) {}
    // find (木の根を求める)
    int find(int x) {return (uf[x] < 0) ? x : uf[x] = find(uf[x]);}
    // x と y が同じ集合に属するかどうか
    bool same(int x, int y) {return find(x) == find(y);}
    // x が属する集合の要素数
    int size(int x) {return -uf[find(x)];}
    // 集合はいくつあるか
    int size()      {return __size;}
    // x と y の属する集合を併合
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if(x == y) return;
        __size--;
        if(uf[y] < uf[x]) swap(x, y);
        uf[x] += uf[y]; uf[y] = x;
    }
};

signed main() {
    int N; cin >> N;
    vector<Elem> vp(N);
    rep(i,0,N) {
        int x, y;
        cin >> x >> y;
        vp[i] = Elem{x, y, i};
    }

    priority_queue<Edge> q;
    // x
    sort(vp.begin(), vp.end(), cmp_x);
    rep(i,1,N) {
        int l = vp[i-1].idx, r = vp[i].idx;
        int c = vp[i].x - vp[i-1].x;
        q.push(Edge{l, r, c});
    }

    // y
    sort(vp.begin(), vp.end(), cmp_y);
    rep(i,1,N) {
        int l = vp[i-1].idx, r = vp[i].idx;
        int c = vp[i].y - vp[i-1].y;
        q.push(Edge{l, r, c});
    }

    // MST
    int ans = 0;
    UnionFind uf(N);
    while(!q.empty()) {
        Edge cur = q.top(); q.pop();
        if(uf.same(cur.l, cur.r)) continue;
        uf.unite(cur.l, cur.r);
        ans += cur.cost;
    }
    cout << ans << endl;
    return 0;
}

