struct UF {
	vector<ll> par, sz, rank;
	UF(ll n) : par(n), sz(n), rank(n) {
		REP(i, n) {
			par[i] = i;
			sz[i] = 1;
			rank[i] = 0;
		}
	}
	ll find(ll x) {
		return par[x] == x ? x : par[x] = find(par[x]);
	}
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if (x != y) {
			if (rank[x] < rank[y]) {
				par[x] = y;
				sz[y] += sz[x];
			} else {
				par[y] = x;
				sz[x] += sz[y];
				if (rank[x] == rank[y]) {
					rank[x]++;
				}
			}
		}
	}
	bool same(ll x, ll y) {
		return find(x) == find(y);
	}
	ll size(ll n) {
		return sz[find(n)];
	}
};

