    for (auto it=y.begin(); it!=y.end(); it++) {
        if (it !=y.begin()) {
            plan.push_back({*(it->second.begin()), *(prev(it)->second.begin()), it->first - prev(it)->first});
        }
        const auto &v = it->second;
        REP (i, SZ(v) - 1) {
            mrg(v[i], v[i+1]);
        }
    }

    sort(plan.begin(), plan.end());

    for (const auto &p : plan) {
        if (mrg(p.u, p.v)) {
            ans += p.cost;
        }
    }

    cout << ans << endl;
    return 0;
}

