signed main() {
  ll n,xx,yy,d,r=0; // rは最終的に出力したい変数
  cin >> n;
  vpl4 x(n),y(n),l(n); // x座標と街番号のペア, y座標と街番号のペア, i番目の街のx・y座標
  //vll c(2*n-2); // i番目のどの木に属しているか(i番目の初期値はi) ←外に出しました
  IOTA(c,0); // ↑の初期値設定

  // x座標とy座標それぞれについてソートする
  REP(i,n){
    cin >> xx >> yy;
    x[i] = mp(xx,i);
    y[i] = mp(yy,i);
    l[i] = mp(xx,yy);
  }
  SORT(x);
  SORT(y);

  // x座標が近いもの、y座標が近いもの同士で辺をつくりsにいれる
  vector<pair<ll,pair<ll,ll> > > s; // 各辺について、座標の差(=コストである可能性が高い)と「街番号のペア」のペア
  REP(i,n-1){
    s.pb(mp(x[i+1].fi-x[i].fi,mp(x[i].se,x[i+1].se)));
  }
  REP(i,n-1){
    s.pb(mp(y[i+1].fi-y[i].fi,mp(y[i].se,y[i+1].se)));
  }

  // sを「座標の差」順にソート
  SORT(s);

  // 違う木に属している(=cの値が異なる)ときは、rにコストを追加した上でcの値を更新していく
  REP(i,2*n-2){
    if(chk(c,c[s[i].se.fi])!=chk(c,c[s[i].se.se])){
      r+=s[i].fi;
      c[s[i].se.fi]=c[s[i].se.se];
    }
  }
  cout << r;
  return 0;
}

