int kruskal(int V, int E) {
  sort(es, es + E, cmp);
  UnionFind<int> uf(V);
  int res = 0;
  rep(i, 0, E) {
    edge e = es[i];
    if (!uf.issame(e.from, e.to)) {
      uf.unite(e.from, e.to);
      res += e.cost;
    }
  }
  return res;
}

