		mark[p]=1;
		po_x.erase(arr[p].fi); ne_x.erase(-arr[p].fi);
		po_y.erase(arr[p].se); ne_y.erase(-arr[p].se);

		mypair=*po_x.upper_bound(arr[p].fi);
		pq.push(mp(abs(arr[p].fi-mypair.fi),mypair.se));

		mypair=*po_y.upper_bound(arr[p].se);
		pq.push(mp(abs(arr[p].se-mypair.fi),mypair.se));
		mypair=*ne_x.upper_bound(-arr[p].fi);
		pq.push(mp(abs(arr[p].fi+mypair.fi),mypair.se));
		mypair=*ne_y.upper_bound(-arr[p].se);
		pq.push(mp(abs(arr[p].se+mypair.fi),mypair.se));
	}

	pr(ans);
	re 0;
	// Hack it if you can :)
}
