vector<ll> x(1e5+5);
vector<ll> y(1e5+5);

ll dijkstra(vector<Edge>* g, ll n){
    ll INF = pow(10, 10);


    vector<bool> visited(n, false);
    visited[0] = true;

    ll sum = 0;
    ll lx = x[0];
    ll lxN = 0;
    ll rx = x[0];
    ll rxN = 0;
    ll uy = y[0];
    ll uyN = 0;
    ll dy = y[0];
    ll dyN = 0;

    ll len = 1;
    while(len < n){
        ll next = 0;
        ll cost = INF;
        set<ll> v;
        v.insert(lxN);
        v.insert(rxN);
        v.insert(uyN);
        v.insert(dyN);

        for(auto src : v){
            if(!visited[src])   continue;
            for(auto e : g[src]){
                if(visited[e.to])   continue;
                if(e.cost < cost){
                    next = e.to;
                    cost = e.cost;
                }
            }
        }

        len++;
        visited[next] = true;

        if(x[next] < lx){
            lx = x[next];
            lxN = next;
        }
        if(rx < x[next]){
            rx = x[next];
            rxN = next;
        }
        if(y[next] < dy){
            dy = y[next];
            dyN = next;
        }
        if(uy < y[next]){
            uy = y[next];
            uyN = next;
        }

        sum += cost;
    }

    return sum;
}

