int parent(int u)
{
    if (u == par[u])
        return u;
    else
        return par[u] = parent(par[u]);
}

void joint(int u, int v)
{
    if (rank[u] > rank[v])
    {
        par[v] = u;
        rank[u] += rank[v];
    }
    else
    {
        par[u] = v;
        rank[v] += rank[u];
    }
}

