bool cmp1(const struct node &u, const struct node &v) {
    return u.x < v.x;
}

bool cmp2(const struct node &u, const struct node &v) {
    return u.y < v.y;
}

bool cmp3(const struct node &u, const struct node &v) {
    return u.x < v.x;
}

int pre[N];

int find(int x) {
    int r, i, j;
    r = x;
    while(pre[r] != r) {
        r = pre[r];
    }
    i = x;
    while(pre[i] != r) {
        j = pre[i];
        pre[i] = r;
        i = j;
    }
    return r;
}

bool mx(int x, int y) {
    int fx = find(x);
    int fy = find(y);
    if(fx != fy) {
        pre[fx] = fy;
        return true;
    }
    return false;
}

