        ans[cnt].id1 = maps[i].id;
        ans[cnt].id2 = maps[i-1].id;
    }
    sort(ans+1, ans+1+cnt, cmp3);
    int k = 0;
    LL answer = 0;
    for(int i=1; i<=cnt; i++) {
        if(mx(ans[i].id1, ans[i].id2)) {
            k++;
            answer += ans[i].x;
            if(k == n-1)
                break;
        }
    }

    printf("%lld\n", answer);
}

