int Kruskal(Graph&g){
    vector<Edge> es;
    REP(i,g.size()){
      REP(j,g[i].size()){
        es.PB(g[i][j]);
      }
    }
    sort(es.begin(),es.end(),[](const Edge&a,const Edge&b){
      return a.wei<b.wei;
    });
    REP(i,g.size())par[i]=i;
    int sum=0;
    REP(i,es.size()){
      if(root(es[i].src)!=root(es[i].dst)){
        sum+=es[i].wei;
        unite(es[i].src,es[i].dst);
      }
    }
    return sum;
}

