// http://algoogle.hadrori.jp/algorithm/prim.html
typedef pair<ll, int> pii; // (cst, to)

ll prim() {
    priority_queue<pii, vector<pii>, greater<pii> > que;
    vector<bool> used(N, false);
    que.push(pii(0,0));
    ll ret = 0;
    while(!que.empty()) {
        ll cst = que.top().first;
        int v = que.top().second;
        que.pop();
        if(used[v]) continue;
        used[v] = true;
        ret += cst;
        for(int i = 0; i < N; i++)
            que.push(pii(cost(v, i), i));
    }
    return ret;
}

