template<class TAT>
inline void read(TAT &res){
	char c; res = 0;
	bool neg = false;
	while(c = getchar(), c != '-' && (c < '0' || c > '9'));
	if(c == '-') neg = true, c = getchar();
	do res = (res*10) + (c^48);
	while(c = getchar(), c >= '0' && c <= '9');
	if(neg) res = -res;
}
