const int MAX_N = 100010;

int par[MAX_N];
int myrank[MAX_N];

void init(int n)
{
    for (int i=0; i<n; i++) {
        par[i] = i;
        myrank[i] = 0;
    }
}

int find(int x)
{
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}

void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if (x == y) return;

    if (myrank[x] < myrank[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (myrank[x] == myrank[y]) myrank[x]++;
    }
}

bool same(int x, int y)
{
    return find(x) == find(y);
}

