	fo(i,2,n+1)
		pq.push(mp(-(temp[i].F-temp[i-1].F),mp(temp[i].S,temp[i-1].S)));
	while(!pq.empty())
	{
		t = pq.top();
		pq.pop();
		a = root(t.S.F);
		b = root(t.S.S);
		if(a != b)
		{
			ans -= t.F;
			merge(a,b);
		}
	}
	cout << ans;
	// Code ends here

	// clk = clock() - clk;
	// cout << fixed << setprecision(6) << "Time: " << ((double)clk)/CLOCKS_PER_SEC << "\n";
	return 0;
}

