struct UnionFind {
    vector<int> data;
    UnionFind(int size) : data(size, -1) { }
    bool unionSet(int x, int y) {
        x = root(x); y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y]; data[y] = x;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
};

int main(void){
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n; cin >> n;
    using Elem = tuple<int, int>;
    vector<Elem> xs(n), ys(n);
    rep(i, n){
        int x, y; cin >> x >> y;
        xs[i] = Elem(x, i);
        ys[i] = Elem(y, i);
    }
    sort(_all(xs));
    sort(_all(ys));

    using Edge = tuple<int, int, int>;
    vector<Edge> edges;
    auto f = [&](vector<Elem>& p){
        rep(i, n - 1){
            int v, x; tie(x, v) = p[i];
            int nv, nx; tie(nx, nv) = p[i + 1];
            edges.emplace_back(Edge(nx - x, v, nv));
        }
    };
    f(xs); f(ys);
    sort(_all(edges));

    UnionFind uf(n);
    ll res = 0LL;
    for(auto& e : edges){
        int a, b, cost; tie(cost, a, b) = e;
        if(uf.findSet(a, b)) continue;
        uf.unionSet(a, b);
        res += cost;
    }

    cout << res << endl;

    return 0;
}

