	for (int i = 0; i < n; i++) {
		cin >> p[i].first >> p[i].second;
		for (int j = i - 1; j >= 0; j--) {
			es.push_back(edge(i, j, min(abs(p[i].first - p[j].first), abs(p[i].second - p[j].second))));
		}
	}
	for (int i = 0; i < n; i++) {
		father[i] = i;
	}
	cout << kruskal() << endl;
	return 0;
}

