struct UnionFind {
	vector<int> par;
	UnionFind(int n) :par(n) {
		for (int i = 0; i < n; i++) {
			par[i] = i;
		}
	}
	int root(int x) {
		return par[x] == x ? x : par[x] = root(par[x]);
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	void merge(int x, int y) {
		int rx = root(x), ry = root(y);
		if (rx == ry)return;
		par[rx] = ry;
	}
};

