struct DisjointSet {
	int sets;
	int* parent;
	int* members;

	void init (int n) {
		sets = n;
		parent = new int[n];
		members = new int[n];
		for (int i=0; i<n; i++) {
			parent[i] = i;
			members[i] = 0;
		}
	}

	int find (int a) {
		if (a == parent[a]) return a;
		return parent[a] = find(parent[a]);
	}

	bool joined (int a, int b) {
			return find(a) == find(b);
	}

	void join (int a, int b){
		if (joined(a, b)) return;
		members[find(b)] += members[find(a)];
		parent[find(a)] = find(b);
		sets--;
	}
};

