    sort(es,es+M,comp);
    UnionFind tree(N);
    ll res=0;
    for(int i=0;i<M;i++){
        edge e=es[i];
        if(!tree.same(e.u,e.v)){
            tree.unite(e.u,e.v);
            res+=e.cost;
        }
    }
    return res;
}

