	if(par[u] < 0)
		return u;

	return par[u] = root(par[u]);
}

void merge(int u, int v) {
	u = root(u); v = root(v);
	if(u == v)
		return;

	if(par[u] > par[v])
		u ^= v ^= u ^= v;

	par[u] += par[v];
	par[v] = u;
}

signed main() {
	int n;
	std::cin >> n;

	std::pair<int, int> helpx[n], helpy[n];

	for(int i = 0; i < n; i++) {
