		edges.push_back({helpy[i].first - helpy[i-1].first, {helpy[i].second, helpy[i-1].second}});
	}

	std::sort(edges.begin(), edges.end());

	int ans = 0;

	for(int i = 0; i < edges.size(); i++) {
		int u = edges[i].second.first;
		int v = edges[i].second.second;
		int w = edges[i].first;

		if(root(u) != root(v))
			ans += w;

		merge(u, v);
	}

