int findfa(int x) {
	if (x == fa[x])return x;
	return fa[x] = findfa(fa[x]);
}

void merge(int u, int v) {
	int p = findfa(u);
	int q = findfa(v);
	if (p != q) {
		fa[p] = q;
	}
}

bool chk(int x, int y) {
	if (findfa(x) == findfa(y))return true;
	else return false;
}

