vector<tuple<ll,int,int>> e;

int getroot(int u){
	return u==par[u]?u:par[u]=getroot(par[u]);
}

bool joint(int u,int v){
	u=getroot(u);
	v=getroot(v);
	if(u==v) return false;
	if(r[u]>r[v]) r[u]+=r[v],par[v]=u;
	else r[v]+=r[u],par[u]=v;
	return true;
}

