//1-indexed DSU
struct DSU {
    int n;
    vector<int> siz, par;
    int init_calls;
    DSU() {
	init_calls = 0;
    }
    void init(int n) {
	assert(++init_calls == 1);
	this->n=n;
	siz.resize(n+10, 1);
	par.resize(n+10);
	for (int i=1; i<=n; i++) par[i] = i;
    }
    int parent(int x) {
	assert(init_calls == 1);
	assert(x>=1 && x<=n);
	if (x == par[x]) return x;
	return par[x] = parent(par[x]);
    }
    bool join(int x, int y) {
	assert(init_calls == 1);
	x = parent(x);
	y = parent(y);
	if (x == y) return false;
	if (siz[x]<siz[y]) swap(x,y);
	par[y] = x;
	siz[x] += siz[y];
	return true;
    }
    void clear() {
	init_calls = 0;
	n = 0;
	siz.clear();
	par.clear();
    }
};


