void Union(int x,int y){
	x=Find(x);
	y=Find(y);
	if(x==y)return;
	if(ranka[x]<ranka[y]){
    parent[x]=y;
  }else{
		parent[y]=x;
		if(ranka[x]==ranka[y])ranka[x]++;
	}
}
