void update(int x,int mn,int pos)
{
    for(int i=x;i>0;i-=lowbit(i))
    {
        if(bit[i].mn > mn)
        {
            bit[i].mn = mn;
            bit[i].pos = pos;
        }
    }
}
int query(int x)
{
    int mn = INF,pos = -1;
    for(int i = x;i<=pn;i+=lowbit(i))
    {
        if(bit[i].mn < mn)
        {
            mn = bit[i].mn;
            pos = bit[i].pos;
        }
    }
    return pos;
