class UnionFind {
    vector<int> par, Size;

  public:
    UnionFind(int n) : par(n), Size(n) {
        rep(i, n) {
            par[i] = i;
            Size[i] = 1;
        }
    }

    int root(int x) {
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    bool same(int x, int y) { return root(x) == root(y); }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y) return;
        if(Size[x] > Size[y]) {
            Size[x] += Size[y];
            par[y] = x;
        } else {
            Size[y] += Size[x];
            par[x] = y;
        }
    }

    int size(int x) { return Size[root(x)]; }
};

