		p py; py.x = t; py.idx = i;
		xy[1][i] = py;
	}
	sort(xy[0], xy[0] + N);
	sort(xy[1], xy[1] + N);
	repi(i, 0, 2) {
		repi(j, 1, N) {
			ll cost = xy[i][j].x - xy[i][j - 1].x;
			e e1, e2;
			e1.cost = e2.cost = cost;
			e1.to = xy[i][j].idx, e2.to = xy[i][j - 1].idx;
			vc[xy[i][j - 1].idx].push_back(e1);
			vc[xy[i][j].idx].push_back(e2);
		}
	}
	cout << prim() << endl;
	return 0;
}

