        return cost > r.cost;
    }
};

ll dijkstra(ll n){
    set<ll> nodes;
    nodes.insert(0);

    ll sum = 0;
    priority_queue<Edge> que;
    rep(to, n){
        if(to == 0)   continue;
        ll xCost = abs(x[0] - x[to]);
        ll yCost = abs(y[0] - y[to]);
        que.push({to, min(xCost, yCost)});
    }

    ll len = 1;
    while(len < n){
        Edge edge = que.top(); que.pop();
        if(0 < nodes.count(edge.to))   continue;

        nodes.insert(edge.to);
        len++;
        rep(to, n){
            if(to == edge.to)   continue;
            ll xCost = abs(x[edge.to] - x[to]);
            ll yCost = abs(y[edge.to] - y[to]);
            que.push({to, min(xCost, yCost)});
        }

        sum += edge.cost;
    }

    return sum;
}

