bool cmp(S a,S b)
{
    return a.x<b.x;
}

bool cmp1(Bian a,Bian b)
{
    return a.len<b.len;
}

int N;

int visit[MAX] = {0};

int Find(int x)
{
    if(visit[x]==x)
        return x;
    else
        return visit[x] = Find(visit[x]);
}

int mix(int x,int y)
{
    int Tx = Find(x);
    int Ty = Find(y);
    if(Tx!=Ty)
    {
        visit[Tx] = Ty;
        return 1;
    }
    return 0;

}


