    sort(A+1,A+1+N,cmp);sort(B+1,B+1+N,cmp);
    for(int i = 1;i <N;i++)
    {
        biao[num].x = A[i].wei;
        biao[num].y = A[i+1].wei;
        biao[num++].len = A[i+1].x - A[i].x;
        biao[num].x = B[i].wei;
        biao[num].y = B[i+1].wei;
        biao[num++].len = B[i+1].x - B[i].x;
    }
