bool unit(int x, int y) {
  int px = get(x), py = get(y);
  if (px == py) return 0;
  if (lvl[px] > lvl[py]) p[py] = px;
  else if (lvl[py] > lvl[px]) p[px] = py;
  else p[px] = py, lvl[px]++;
  return 1;
}
