struct UnionFind{
	vector<int> elems;
	UnionFind(int n):elems(n){
		for(int i=0;i<n;i++){
			elems[i] = i;
		}
	}
	bool same(int a, int b){
		return parent(a) == parent(b);
	}
	void unite(int a, int b){
		elems[parent(a)] = parent(b);
	}
private:
	int parent(int a){
		if(a == elems[a]){
			return a;
		}
		return elems[a] = parent(elems[a]);
	}
};

