#include <bits/stdc++.h>
using namespace std;
class disjoint_set {
  public:
    vector<int> rank, p;
    disjoint_set(){};
    disjoint_set (int size) {
      rank.resize(size, 0);
      p.resize(size, 0);
      for (int i = 0; i < size; i++) {
        makeSet(i);
      }
    }
    void makeSet (int x) {
      p[x] = x;
      rank[x] = 0;
    }
    bool same (int x, int y) {
      return find_set(x) == find_set(y);
    }
    void unite (int x, int y) {
      link(find_set(x), find_set(y));
    }
    void link (int x, int y) {
      if (rank[x] > rank[y]) {
        p[y] = x;
      } else {
        p[x] = y;
        if (rank[x] == rank[y]) {
          rank[y]++;
        }
      }
    }
    int find_set (int x) {
      if (x != p[x]) {
        p[x] = find_set(p[x]);
      }
      return p[x];
    }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int n;
  cin >> n;
  disjoint_set ds(n);
  vector<pair<int, int>> x(n);
  vector<pair<int, int>> y(n);
  for (int i = 0; i < n; i++) {
    int a, b;
