    y[i] = {b, i};
  }
  sort(x.begin(), x.end());
  sort(y.begin(), y.end());
  priority_queue<pair<int, pair<int, int>>, vector<pair<int, pair<int, int>>>, greater<pair<int, pair<int, int>>>> pq;
  for (int i = 1; i < n; i++) {
    {
      int u, v, d;
      d = x[i].first - x[i - 1].first;
      u = x[i - 1].second;
      v = x[i].second;
      pq.push({d, {u, v}});
    }
    {
      int u, v, d;
      d = y[i].first - y[i - 1].first;
      u = y[i - 1].second;
      v = y[i].second;
      pq.push({d, {u, v}});
    }
  }
  int cnt = 0;
  int ans = 0;
  while (!pq.empty()) {
    auto e = pq.top();
    pq.pop();
    int dst = e.first;
    int one = e.second.first;
    int ant = e.second.second;
    if (ds.same(one, ant)) {
      continue;
    }
