//            if(minq<min(road[i].x,road[i].y))
//                minq=min(road[i].x,road[i].y);
            road[i].id=i;
        }
        cnt=0;
        for(int i=1;i<n;i++){
            for(int j=i+1;j<=n;j++){
                int mins=mind(road[i],road[j]);
                road2[cnt].x=road[i].id;
                road2[cnt].y=road[j].id;
                road2[cnt++].id=mins;
            }
        }
