Edge E[100010];
int m;
int kruskal(){
	sort(E+1,E+m+1,[](const Edge&x,const Edge&y){return x.c<y.c;});
	init(n);
	int res=0;
	for(int i=1;i<=m;i++){
		Edge cur=E[i];
		if(!same(cur.u,cur.v)){
			unite(cur.u,cur.v);
			res+=cur.c;
			// cout<<cur.u<<' '<<cur.v<<' '<<cur.c<<endl;
		}
	}
	return res;
}
int main(){
