	for(int i=2;i<=n;i++){
		int d=abs(co[i-1].u-co[i].u);
		int pri=co[i-1].id,nxi=co[i].id;
		E[++m]=(Edge){nxi,pri,d};
		E[++m]=(Edge){pri,nxi,d};
	}
	sort(co+1,co+n+1,[](const coo&x,const coo&y){return x.v<y.v;});
	// sort(a+1,a+n+1,[=](const int&x,const int&y){return co[x].S<co[y].S;});
