const int MAX_N=1e5+1;
pair<LL,int> X[MAX_N],Y[MAX_N];
int N;

struct UF {
public:
  int groupNum;
  UF(int N) {
    uf=vector<int>(N);
    rank=vector<int>(N);
    for(int i=0; i<N; ++i) uf[i]=i,rank[i]=0;
    groupNum=N;
  }

  int find(int i) {
    return uf[i]==i?i:uf[i]=find(uf[i]);
  }

  bool same(int x, int y) {
    return find(x)==find(y);
  }

  void unite(int x, int y) {
    x=find(x);
    y=find(y);
    if(x==y) return;
    groupNum--;

    if (rank[x]==rank[y]) {
      uf[x]=y;
      rank[y]++;
      return;
    }

    if (rank[x]<rank[y]) {
      uf[x]=y;
    } else {
      uf[y] =x;
      if(rank[x]==rank[y]) ++rank[x];
    }
  }
private:
  vector<int> rank;
  vector<int> uf;
};

LL solve() {
  sort(X,X+N),sort(Y,Y+N);
//  dump(N);
  vector<tuple<LL,int,int>> XX,YY;
  REP(i,N-1) {
    XX.emplace_back(X[i+1].first-X[i].first,X[i+1].second,X[i].second);
    YY.emplace_back(Y[i+1].first-Y[i].first,Y[i+1].second,Y[i].second);
//    dump4(i,get<0>(XX[i]),get<1>(XX[i]),get<2>(XX[i]));
//    dump4(i,get<0>(YY[i]),get<1>(YY[i]),get<2>(YY[i]));
  }
  sort(XX.begin(),XX.end()),sort(YY.begin(),YY.end());
//  dump(SZ(XX));

  LL res=0;
  UF uf(N+1);
  int i=0,j=0;
  while(i<N-1||j<N-1) {
    tuple<LL,int,int> a={-1,-1,-1};
    if(i>=N-1) a=YY[j++];
    else if(j>=N-1) a=XX[i++];
    else {
      if(XX[i]<YY[j]) a=XX[i++];
      else a=YY[j++];
    }
    LL d; int u,v; tie(d,u,v)=a;
    assert(d!=-1);
//    dump2(i,j);
//    dump3(d,u,v);
    if(uf.same(u,v)) continue;
    res+=d;
    uf.unite(u,v);
  }
  return res;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  cin>>N;
  REP(i,N) {
    int x,y;
    cin>>x>>y;
    X[i]={x,i},Y[i]={y,i};
  }
  cout<<solve()<<endl;

  return 0;
}

