bool Same(int a,int b){
	int k=a;
	while(true){if(p[k]==k)break;k=p[k];}
	while(true){if(p[a]==a)break;a=p[a],p[a]=k;}
	int l=b;
	while(true){if(p[l]==l)break;l=p[l];}
	while(true){if(p[b]==b)break;b=p[b],p[b]=l;}

	if(k==l)return true;
	return false;
}

void Unite(int a,int b){
	int k=a;
	while(true){if(p[k]==k)break;k=p[k];}
	while(true){if(p[a]==a)break;a=p[a],p[a]=k;}
	int l=b;
	while(true){if(p[l]==l)break;l=p[l];}
	while(true){if(p[b]==b)break;b=p[b],p[b]=l;}

	p[k]=p[l];
	return;
}

