class UnionFind
{
   private:
      vector<int> par, myrank;
   public:
      UnionFind(int n) {
         par.resize(n);
         myrank.resize(n, 0);
         for (int i = 0; i < n; i++) {
            par[i] = i;
         }
      }
      int find(int x) {
         if (par[x] == x) return x;
         return par[x] = find(par[x]);
      }
      void unite(int x, int y) {
         x = find(x);
         y = find(y);
         if (x == y) return;
         if (myrank[x] < myrank[y]) {
            par[x] = y;
         } else {
            par[y] = x;
            if(myrank[x] == myrank[y]) myrank[x]++;
         }
      }
      bool same(int x, int y) {
         return find(x) == find(y);
      }
};
int kruskal(vector<edge>& E, int N) {
   vector<bool> used(N, false);
   UnionFind uni(used.size());
   SORT(E);
   int sum = 0;
   for(int i = 0; i < E.size(); i++) {
      edge e = E[i];
      if (!uni.same(e.from, e.to)) {
         uni.unite(e.from, e.to);
         sum += e.cost;
         used[i] = true;
      }
   }
   return sum;
}

