   }

   SORT(x); SORT(y);
   V<edge> E;
   REP(i, N-1) {
      E.PB((edge){ x[i].second, x[i+1].second, x[i+1].first - x[i].first });
      E.PB((edge){ y[i].second, y[i+1].second, y[i+1].first - y[i].first });
   }

   int ans = kruskal(E, N);
   cout << ans << endl;

   return 0;
}

