const int MAXN = 1e5 + 6;
const ll INF = 2e18;


pair<int, int> p[MAXN];
ll answer = 1e18;
int n;

void go(){
	vector<int> x_y[MAXN];
	vector<int> y_x[MAXN];

	set<int> y;
	set<int> x;
	sort(p, p + n);
	for(int i = 0; i < n; i++){
		cin >> p[i].first >> p[i].second;
		x_y[p[i].first].push_back(p[i].second);
		y_x[p[i].second].push_back(p[i].first);
	}
	ll ans = 0;
	for(auto x : x_y[p[0].first]){
		y.insert(x);
	}
	for(auto y : y_x[p[0].second]){
		x.insert(y);
	}



	for(int i = 1 ; i < n; i++){
		auto cur = p[i];
		auto l = y.lower_bound(p[i].second);
		auto ll = x.lower_bound(p[i].first);

		if(l == y.end()) l--;
		if(ll == x.end()) ll--;

		if(*l != p[i].second || *ll != p[i].first){
			int m1 = abs(p[i].second - *l);
			if(l != y.begin()){
				l--;
				m1 = min(m1, abs(p[i].second - *l));
			}

			int m2 = abs(p[i].first - *ll);
			if(ll != x.begin()){
				ll--;
				m2 = min(m2, abs(p[i].first - *ll));
			}
			ans += min(m1, m2);
		}

		if(y.count(p[i].second) == 0){
			for(auto x : x_y[p[i].first]){
				y.insert(x);
			}
		}

		if(x.count(p[i].first) == 0){
			for(auto y : y_x[p[i].second]){
				x.insert(y);
			}
		}

	}

	answer = min(ans, answer);
}
int main() {
	#ifdef LOCAL
	setIn("in.txt");
	setOut("out.txt");
	#endif

	cin >> n;

	go();
	for(int i = 0; i < n; i++){
		swap(p[i].first, p[i].second);
	}
	go();
	cout << answer;
}

