};

ll group_of(vector<ll>& union_find, ll idx) {
    ll i = idx;
    for (; union_find[i] != i; i = union_find[i]);
    return i;
}

void unite(vector<ll>& union_find, ll from, ll to) {
    // 多分これだと間に合わない
    union_find[to] = from;
}

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N;
