    vector<ll> xidx(N), yidx(N), union_find(N);
    for (ll i = 0; i < N; i++) {
        xidx[i] = i;
        yidx[i] = i;
        union_find[i] = i;
    }

    vector<p> town(N);
    for (ll i = 0; i < N; i++) {
        ll x, y;
        cin >> x >> y;
        town[i] = p(x, y);
    }

    sort(xidx.begin(), xidx.end(), [town](ll left, ll right) {
        p l = town[left];
        p r = town[right];
        if (l.first < r.first) {
            return true;
        } else if(l.first == r.first) {
            return l.second < r.second;
        } else {
            return false;
        }
    });

    sort(yidx.begin(), yidx.end(), [town](ll left, ll right) {
        p l = town[left];
        p r = town[right];
        if (l.second < r.second) {
