struct item
{
	int typ, x, cur, d;

	item(){}
	item(int typ, int x, int cur, int d): typ(typ), x(x), cur(cur), d(d){}

	bool operator <(const item &a) const{ return d > a.d; }
};

HEAP<item> heap;

int main()
{
	scf(n);
	rep(i, n) scf(pnt[i].X, pnt[i].Y), par[i] = i;
	sort(pnt, pnt + n);
	rep(i, n) pnt2[i] = mp(pnt[i].Y, i);
	sort(pnt2, pnt2 + n);
	rep(i, n)
	{
		id[pnt2[i].Y] = i;
		b[i] = pnt2[i].X;
		a[i] = pnt[i].X;
	}
	a[n] = b[n] = iinf;
	rep(i, n)
	{
		item foo = item(0, i, i + 1, a[i + 1] - a[i]);
		heap.push(foo);
		foo = item(1, i, i + 1, b[i + 1] - b[i]);
		heap.push(foo);
	}
	int tot = n; LL ans = 0;
	while(tot > 1)
	{
