  for(int i=0;i<n;i++) {
    ll tx=ax[i], ty=ay[i];
    auto it=x.find({tx,i});
    it++;
    if(it!=x.end()){
      g.add(i,(*it).se,(*it).fi-tx);
    }
    it--;
    if(it!=x.begin()){
      it--;
      g.add(i,(*it).se,tx-(*it).fi);
    }

    auto yt=y.find({ty,i});
    yt++;
    if(yt!=y.end()){
      g.add(i,(*yt).se,(*yt).fi-ty);
    }
    yt--;
    if(yt!=y.begin()){
      yt--;
      g.add(i,(*yt).se,ty-(*yt).fi);
    }
  }
  prims pr(g);
  cout<<pr.calc()<<endl;


