ll dijkstra(ll n){
    ll sum = 0;
    priority_queue<Edge> que;
    ll INF = 1e10;
    vector<ll> memo(n, INF);
    memo[0] = INF;
    rep(to, n){
        if(to == 0)   continue;
        ll xCost = abs(x[0] - x[to]);
        ll yCost = abs(y[0] - y[to]);
        memo[to] = min(xCost, yCost);
    }

    rep(times, n-1){
        ll next = 0;
        ll cost = INF;
        rep(i, n){
            if(memo[i] < cost){
                next = i;
                cost = memo[i];
            }
        }

        memo[next] = INF;
        sum += cost;

        rep(to, n){
            if(to == next)      continue;
            if(memo[to] == INF) continue;
            ll xCost = abs(x[next] - x[to]);
            ll yCost = abs(y[next] - y[to]);
            memo[to] = min(memo[to], min(xCost, yCost));
        }
    }

    return sum;
}

