class UnionFind {
public:
	explicit UnionFind(int N) : root(N, -1) {}
	int getRoot(int v){ return root[v] == -1 ? v : root[v] = getRoot(root[v]); }
	void merge(int a, int b){
		int p = getRoot(a), q = getRoot(b);
		if(p != q) root[q] = p;
	}
private:
	vector<int> root;
};

int main(){
