void weighted_union(ll A, ll B)
{
    ll root_A = root(A);
    ll root_B = root(B);
    if(size[root_A] < size[root_B ])
    {
        dsu[ root_A ] = dsu[root_B];
        size[root_B] += size[root_A];
    }
    else
    {
        dsu[ root_B ] = dsu[root_A];
        size[root_A] += size[root_B];
    }
    return;
}

