struct union_find {
    vll data;

    union_find(ll &size) : data(size, -1) {  }

    ll root(ll &x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    bool merge(ll x, ll y) {
        if ((x = root(x)) == (y = root(y))) return false;

        if (data[x] > data[y]) std::swap(x, y);

        data[x] += data[y], data[y] = x;

        return true;
    }
};

