vector<ll> Parent, Rank;
ll R;

void init() {
  Parent.resize(N, -1);
  Rank.resize(N, 0);
}
ll root(ll v) {
  if (Parent[v] == -1) return v;
  return Parent[v] = root(Parent[v]);
}
bool same(ll u, ll v) { return root(u) == root(v); }
void unite(ll u, ll v) {
  u = root(u);
  v = root(v);
  if (u == v) return;
  if (Rank[u] < Rank[v]) swap(u, v);
  Parent[v] = u;
  if (Rank[u] == Rank[v]) ++Rank[u];
}
int main() {
