const int maxn=100005;
int n;
class EDGE{
public:
	int from,to,m;
};
bool cmp(EDGE x,EDGE y){
	return x.m<y.m;
}
ll ans;
vector<EDGE>edge;
vector<pii>X,Y;
int f[maxn];

int Find(int x){
	return f[x]==x?x:f[x]=Find(f[x]);
}

void Union(int x,int y){
	x=Find(x);y=Find(y);
	if(x!=y)f[x]=y;
}

int main(){
	scanf("%d",&n);
	REP(i,n){
		int x,y;
		scanf("%d%d",&x,&y);
		X.push_back(mk(x,i));
		Y.push_back(mk(y,i));
		f[i]=i;
	}
	sort(X.begin(),X.end());
	rep(i,X.size()-1)
	edge.push_back((EDGE){X[i].se,X[i+1].se,X[i+1].fi-X[i].fi});
	sort(Y.begin(),Y.end());
	rep(i,Y.size()-1)
	edge.push_back((EDGE){Y[i].se,Y[i+1].se,Y[i+1].fi-Y[i].fi});
	sort(edge.begin(),edge.end(),cmp);
	rep(i,edge.size()){
		EDGE x=edge[i];
		if(Find(x.from)==Find(x.to))continue;
		Union(x.from,x.to);
		ans+=x.m;
	}
	printf("%lld",ans);
	return 0;
}

