int n, m;
struct town
{
	int x, y, id;
} p[100010];

struct edge
{
	int u, v, cost;
} q[200010];

int par[100010], sz[100010];

int find_parent(int v)
{
	if (par[v] == v)
		return v;
	return par[v] = find_parent(par[v]);
}

bool unite(int u, int v)
{
	u = find_parent(u);
	v = find_parent(v);
	if (u == v)
		return false;
	if (sz[u] < sz[v])
		swap(u, v);
	sz[u] += sz[v];
	par[v] = u;
	return true;
}

