void init() {
  cin >> n;
  r.resize(n);
  for (int i = 0; i < n; i++) {
    cin >> r[i].first.first >> r[i].first.second;
    r[i].first.first--;
    r[i].first.second--;
    r[i].second = i;
  }
  sort(r.begin(), r.end());
  for (int i = 0; i < n - 1; i++) {
    int x1 = r[i].first.first, y1 = r[i].first.second;
    int x2 = r[i + 1].first.first, y2 = r[i + 1].first.second;
    int r1 = r[i].second, r2 = r[i + 1].second;
    M[r1].push_back(make_pair(min(abs(x2 - x1), abs(y2 - y1)), r2));
    M[r2].push_back(make_pair(min(abs(x2 - x1), abs(y2 - y1)), r1));
  }
  sort(r.begin(), r.end(), cmp1);
  for (int i = 0; i < n - 1; i++) {
    int x1 = r[i].first.first, y1 = r[i].first.second;
    int x2 = r[i + 1].first.first, y2 = r[i + 1].first.second;
    int r1 = r[i].second, r2 = r[i + 1].second;
    M[r1].push_back(make_pair(min(abs(x2 - x1), abs(y2 - y1)), r2));
    M[r2].push_back(make_pair(min(abs(x2 - x1), abs(y2 - y1)), r1));
  }
}



void prim(int s) {
  priority_queue<pii, vector<pii>, greater<pii> > pq;
  int used_cnt = 0;
  mincost[s] = 0;
  pq.push(make_pair(0, s));
  int i;
  while (used_cnt < n) {
    int u;
    pii f;
    while (true) {
      f = pq.top();
      pq.pop();
      u = f.second;
      if (!used[u]) {
	break;
      }
    }
    mincost[u] = f.first;
    for (i = 0; i < M[u].size(); i++) {
      int v = M[u][i].second;
      int c = M[u][i].first;
      pq.push(make_pair(c, v));
    }
    used[u] = true;
    used_cnt++;
  }
}

void ans() {
  ll sum = 0;
  for (int i = 0; i < n; i++) {
    sum += mincost[i];
  }
  cout << sum << endl;
}

void solve() {
  init();
  prim(0);
  ans();
  return;
}

int main() {
  solve();
}

