void init(int n) {
  for(int i = 0; i < n; i++) {
    p[i] = i;
    rank[i] = 0;
  }
}

int Find(int x) {
  return p[x] == x ? x : (p[x] = Find(p[x]));
}

void Union(int x, int y) {
  int a = Find(x);
  int b = Find(y);
  if(a == b) return;
  if(rank[x] > rank[y])  p[y] = x;
  else {
    p[x] = y;
    if(rank[x] == rank[y]) rank[x]++;
  }
}



