using namespace std;

class DSU {
 public:
  int n;
  vector<int> parent;

  DSU(int _n) : n(_n) {
    parent.resize(n);
    for (int i = 0; i < n; i++) {
      parent[i] = i;
    }
  }

  int find(int x) {
    if (x == parent[x]) {
      return x;
    }
    return parent[x] = find(parent[x]);
  }

  bool merge(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) {
      return false;
    }
    parent[x] = y;
    return true;
  }

};

int main() {
  ios_base::sync_with_stdio(false);
