struct unionfind {
  vector<int> par;
  vector<int> rank;
  unionfind(int n) {
    par = vector<int>(n);
    rank = vector<int>(n);
    rep(i,0,n)
    { //0オリジン
      par[i] = i;
      rank[i] = 1;
    }
  }

  int find(int x) {
    if (par[x] == x) {
      return x;
    }
    return par[x] = find(par[x]);
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }

  void unite(int x, int y) { //rank[x] > rank[y]を保つ
    x = find(x);
    y = find(y);
    if (x == y) {
      return;
    }
    if (rank[x] < rank[y]) {
      swap(x, y);
    }
    par[y] = x;
    rank[x] += rank[y];
    rank[y] = 0;
  }

  int size(int x) {
    return rank[x];
  }
};

struct edge {
  int from, to;
  double cost;
  edge(int from, int to, double cost) {
    this->from = from;
    this->to = to;
    this->cost = cost;
  }

  edge() {
    *this = edge(-1, -1, -1);
  }

  bool operator<(const edge& e) const {
    return cost < e.cost;
  }
};

class Graph {
public:
  static ll kruskal(vector<edge>& es, int n) {
    sort(all(es));
    ll min_cost = 0;
    unionfind uf(n);
    rep(i,0,(int)es.size())
    {
      edge &e = es[i];
      if (!uf.same(e.from, e.to)) {
        min_cost += e.cost;
        uf.unite(e.from, e.to);
      }
    }
    return min_cost;
  }
};

int N;
typedef pair<int, int> P;
const int MAX_N = 100010;
vector<P> X, Y;
int dx[MAX_N], dy[MAX_N];
vector<edge> G;
void solve() {
  cin >> N;
  rep(i,0,N)
  {
    int x, y;
    cin >> x >> y;
    X.push_back(P(x, i));
    Y.push_back(P(y, i));
  }
  std::sort(all(X));
  std::sort(all(Y));
  rep(i,1,N)
  {
    dx[i] = X[i].first - X[i - 1].first;
    dy[i] = Y[i].first - Y[i - 1].first;
    G.push_back(edge(X[i].second, X[i - 1].second, dx[i]));
    G.push_back(edge(Y[i].second, Y[i - 1].second, dy[i]));
  }
  cout << Graph::kruskal(G, N) << endl;
}

int main() {
  solve();
}

