template <typename T>
class UF{
public:
	vector<T> par,rank;

	UF(T n){
		par.resize(n);
		rank.resize(n);
		for(T i=0;i<n;i++){
			par[i]=i;
			rank[i]=0;
		}
	}

	T find(T x){
		if(par[x]==x)
			return x;
		else
			return par[x]=find(par[x]);
	}

	bool unite(T x, T y){
		x=find(x);
		y=find(y);
		if(x==y) return false;

		if(rank[x]<rank[y])
			par[x]=y;
		else{
			par[y]=x;
			if(rank[x] == rank[y]) rank[y]++;
		}

		return true;
	}

	bool same(T x, T y){
		return find(x)==find(y);
	}

};

