const int N = 1e5 + 1, MOD = 1e9 + 7;

int parent[N], sz[N], rnk[N];

void init() {
	memset(rnk, 0, sizeof rnk);
	for (int i = 0; i < N; ++i) {
		parent[i] = i;
		sz[i] = 1;
	}
}

int root(int node) {
	while (node != parent[node]) {
		parent[node] = parent[parent[node]];
		node = parent[node];
	}
	return node;
}

bool join(int u, int v) {
	u = root(u);
	v = root(v);

	if (u == v)
		return false;

	if (rnk[u] < rnk[v])
		swap(u, v);

	rnk[u] += rnk[u] == rnk[v];
	sz[u] += sz[v];

	parent[v] = u;
	return true;
}

int find(int u, int v) {
	return root(u) == root(v);
}

