int main() {
	int n;
	cin >> n;
	vector<point> map(n + 1);
	for (int i = 1; i <= n; ++i) {
		cin >> map[i].x >> map[i].y;
	}
	map[1].used = true;
	priority_queue<PAIR, vector<PAIR>, greater<PAIR> > que;
	for (int i = 2; i <= n; ++i) {
		int num = count(map, 1, i);
		map[i].nfast = num;
		que.push(PAIR(num, i));
	}
	long long ans = 0;
	while (!que.empty()) {
		PAIR du = que.top(); que.pop();
		if (map[du.second].used)continue;
		map[du.second].used = true;
		ans += du.first;
		for (int i = 1; i <= n; ++i) {
			if (map[i].used)continue;
			int num = count(map, du.second, i);
			if (map[i].nfast > num) {
				que.push(PAIR(num, i));
				map[i].nfast = num;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

