  int cost=0;
  vector<pair<int,P>> vec;

  REP(i,n-1)vec.pb(mp(abs(a[i].first-a[i+1].first),mp(a[i].second,a[i+1].second)));
  REP(i,n-1)vec.pb(mp(abs(b[i].first-b[i+1].first),mp(b[i].second,b[i+1].second)));
  UnionFind uni(n);
  sort(ALL(vec));
  REP(i,vec.size()){
    if(!uni.Same(vec[i].second.first,vec[i].second.second)){
      uni.Unite(vec[i].second.first,vec[i].second.second);
      cost+=vec[i].first;
      bool flag=false;
      REP(i,n){if(!uni.Same(0,i))break;if(i==n-1)flag=true;}if(flag)break;
    }
  }
  COUT(cost);

  return 0;
}

