int par[MAX]; //親
int ran[MAX]; // 木の深さ

void init(int n) //union^findの初期化
{
	for (int i = 0; i < n; i++) {
		par[i] = i;
		ran[i] = 0;
	}
}

int finds(int x) // 根を求める
{
	if (par[x] == x) {
		return (x);
	}
	else {
		return (par[x] = finds(par[x]));
	}
}


void unite(int x, int y) //集合を結合
{
	x = finds(x);
	y = finds(y);

	if (x == y)return;

	if (ran[x] < ran[y]) {
		par[x] = y;
	}
	else {
		par[y] = x;
		if (ran[x] == ran[y]) ran[x]++;
	}

}

bool same(int x, int y) //同じ集合か判断
{
	return finds(x) == finds(y);
}

struct edge {
	// 頂点u,v 間において
	int u;
	int v;
	int cost;
};

bool comp(const edge &e1, const edge & e2) {
	return e1.cost < e2.cost;
}



int kruskal(int V, int E, edge es[]) //V...頂点数、E...辺の数
{
	sort(es, es + E, comp);
	init(V);
	int res = 0;
	for (int i = 0; i < E; i++) {
		edge e = es[i];
		if (!same(e.u, e.v)) {
			unite(e.u, e.v);
			res += e.cost;
		}

	}
	return res;

}

int sig(int V) //頂点数に対する辺の数を返す
{
	int i;
	int ans = 0;
	for (i = 1; i < V; i++) {
		ans = ans + i;
	}

	return (ans);
}

int costen(pair<int, int> a, pair<int, int> b)
{
	return min(fabs(a.first - b.first), fabs(a.second - b.second));

}


