pair<int, int> find_closest(pair<int, int> p){
  auto it1 = psx.lower_bound({p.first, -2000000000});
  auto it2 = it1;
  if(it2 != psx.begin())
    it2--;
  auto it3 = psy.lower_bound({p.second, -2000000000});
  auto it4 = it3;
  if(it4 != psy.begin())
    it4--;
  pair<int, int> result = *it2;
  if(it1 != psx.end() && dist(*it1, p) < dist(result, p))
    result = *it1;
  if(it3 != psy.end() && dist({it3 -> second, it3 -> first}, p) < dist(result, p))
    result = {it3 -> second, it3 -> first};
  if(dist({it4 -> second, it4 -> first}, p) < dist(result, p))
    result = {it4 -> second, it4 -> first};
  return result;
}

