void init_union_find(int n) {
    for (int i = 0; i <= n; ++i) {
        par[i] = i;
        rank_t[i] = 0;
    }
}

int find_root(int x) {
    return par[x] == x ? x : par[x] = find_root(par[x]);
}

bool same(int x, int y) {
    return find_root(x) == find_root(y);
}

void unite(int x, int y) {
    x = find_root(x);
    y = find_root(y);
    if (x == y) return;

    if (rank_t[x] < rank_t[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rank_t[x] == rank_t[y]) rank_t[x]++;
    }
}

