	vector<pll> P(N);
	for (int i = 0; i < N;i++) {
		ll x, y; cin >> x >> y;
		P[i] = { x,y };
	}
	//vector<vector<ll>> G(N, vector<ll>(N,0));
	priority_queue<edge> pq;
	for (int i = 0; i < N;i++) {
		for (int j = i + 1;j < N;j++) {
			ll cost = min(abs(P[i].first - P[j].first), abs(P[i].second - P[j].second));
			//G[i][j] = G[j][i] = cost;
			pq.push(edge(i, j, cost));
		}
	}
	UnionFind uf(N);
	set<ll> used;
	ll ans = 0;
	while (!pq.empty()) {
		auto e = pq.top(); pq.pop();
		if (uf.findSet(e.from, e.to)) continue;
		uf.unionSet(e.from, e.to);
		used.insert(e.from); used.insert(e.to);
		ans += e.cost;
		if (used.size() == N)break;
	}
	cout << ans << endl;


	return 0;
}

