int par[MAX_N];
int rank[MAX_N];

void init_union_find(int n) {
  for (int i = 0; i < n; i++) {
    par[i] = i;
    rank[i] = 0;
  }
}

int find_union_find(int x){
  if (par[x] == x) {
    return x;
  } else {
    return par[x] = find_union_find(par[x]);
  }
}

void unite_union_find(int x, int y) {
  x = find_union_find(x);
  y = find_union_find(y);
  if ( x == y) return;

  if (rank[x] < rank[y] ) {
    par[x] = y;
  } else {
    par[y] = x;
    if (rank[x] == rank[y]) {
      rank[x]++;
    }
  }

}

bool same_union_find(int x, int y) {
  return find_union_find(x) == find_union_find(y);
}

struct edge{int u,v, cost;};

bool comp(const edge& e1, const edge& e2) {
  return e1.cost < e2.cost;
}


edge es[MAX_E];
int V,E;

int kruskal() {
  sort(es, es+E, comp);
  init_union_find(V);
  int res=0;
  for(int i=0;i<E;++i) {
    edge e =es[i];
    if(!same_union_find(e.u,e.v)){
      unite_union_find(e.u, e.v);
      res += e.cost;
    }
  }
  return res;
}


