#define ABS(x) (x)>0?(x):-(x)
#define MIN(x,y) (x)>(y)?(y):(x)

int main(void) {
	int n;
	int *x,*y,*cost;
	int** data;
	bool *flg;

	scanf("%d",&n);

	x = (int*)malloc(n*sizeof(int));
	y = (int*)malloc(n*sizeof(int));
	cost = (int*)malloc(n*sizeof(int));
	flg = (bool*)malloc(n*sizeof(bool));
	data = (int**)malloc(n*sizeof(int*));
	for (int i = 0;i < n;i++) {
		scanf("%d %d",&x[i],&y[i]);
		data[i] = (int*)malloc(n*sizeof(int));
	}

	for (int i = 0;i < n;i++) {
		for (int j = i+1;j < n;j++) {
			data[i][j] = MIN(ABS(x[i]-x[j]),ABS(y[i]-y[j]));
			data[j][i] = data[i][j];
		}
	}

	long long int ans = 0;
	int now = 0,tmp,min,minp;

	for (int i = 0;i < n;i++) {
		cost[i] = -1;
		flg[i] = false;
	}
	flg[0] = true;

	while(1) {
		min = -1;
		minp = -1;
		for (int i = 0;i < n;i++) {
			if (i == now || flg[i]) {
				continue;
			}

			tmp = (cost[i] == -1 ? data[now][i] : MIN(data[now][i],cost[i]));
			cost[i] = tmp;
			if (min == -1 || (min != -1 && min > tmp)) {
				min = tmp;
				minp = i;
			}
		}

		if (minp == -1) {
			break;
		}

		flg[minp] = true;
		ans += cost[minp];
		now = minp;
	}

	printf("%lld\n",ans);

	return 0;
}

#include <stdio.h>
int par[1000000],rank[1000000];
void init(int n){
    int i;
    for(i=0;i<n;i++){
        par[i]=1;
        rank[i]=0;
    }
}
int root(int x){
    if(par[x]==x) return x;
    return root(par[x]);
}
void combsort(int a[],int b[],int c[],int n){
    int i,h=n/1.3,swaped,tmp;
    if(h==0) h=1;
    while(h!=0||swaped!=0){
        swaped=0;
        if(h==0) h=1;
        if(h==10||h==9) h=11;
        for(i=0;i<n-h;i++){
            if(a[i]>a[i+h]){
                tmp=a[i];
                a[i]=a[i+h];
                a[i+h]=tmp;
                if(b!=NULL){
                    tmp=b[i];
                    b[i]=b[i+h];
                    b[i+h]=tmp;
                }
                if(c!=NULL){
                    tmp=c[i];
                    c[i]=c[i+h];
                    c[i+h]=c[i];
                }
                swaped=1;
            }
        }
        h=h/1.3;
    }
}
void unite(int x,int y){
    x=root(x);
    y=root(y);
    if(x!=y){
        int rx=rank[x],ry=rank[y];
        if(rx<ry){
            par[x]=y;
        }else{
            par[y]=x;
        }
        if(rx==ry) rank[x]++;
    }
}
int same(int x,int y){
    if(root(x)==root(y)) return 1;
    return 0;
}
int main(void){
    int n,i,cnt=0,sum=0;
    int x[1000000],y[1000000],n1[1000000],n2[1000000];
    int from[2000000],to[2000000],cost[2000000]={0};
    scanf("%d",&n);
    for(i=0;i<n;i++){
        scanf("%d%d",&x[i],&y[i]);
        n1[i]=i;
        n2[i]=i;
    }
    combsort(x,n1,NULL,n);
    combsort(y,n2,NULL,n);
    for(i=1;i<n;i++){
        from[cnt]=n1[i-1];
        to[cnt]=n1[i];
        cost[cnt]=x[i]-x[i-1];
        cnt++;
        from[cnt]=n2[i-1];
        to[cnt]=n2[i];
        cost[cnt]=y[i]-y[i-1];
        cnt++;
    }
    combsort(cost,from,to,cnt);
    init(cnt);
    for(i=0;i<cnt;i++){
        if(same(from[i],to[i])==0){
            unite(from[i],to[i]);
            sum+=cost[i];
        }
    }
    printf("%d\n",n2[0]);
    return 0;
}

