		e[i].num = v[i + 1].x - v[i].x;
		e[i].x = v[i].num;
		e[i].y = v[i + 1].num;
	}
	sort(v, N, compare_ms_y);
	for(i = 0; i < N - 1; i++){
		e[N - 1 + i].num = v[i + 1].y - v[i].y;
		e[N - 1 + i].x = v[i].num;
		e[N - 1 + i].y = v[i + 1].num;
	}
	sort(e, 2 * (N - 1), compare_ms_num);
	union_find *uf = make_union_find(N);
	for(i = 0; i < 2 * (N - 1); i++){
		if(root_uf(e[i].x, uf) != root_uf(e[i].y, uf)){
			combine_uf(e[i].x, e[i].y, uf);
			ans += e[i].num;
		}
	}
	printf("%d\n", ans);
