		rank[i] = 0;
	}
}

int uf_find(int x){
	if (parent[x] == x) {
		return x;
	} else {
		return parent[x] = uf_find(parent[x]);
	}
}

int uf_unite(int x, int y){
	x = uf_find(x);
	y = uf_find(y);
	if (x == y) return 1;

	if (rank[x] < rank[y]) {
		parent[x] = y;
	} else {
		parent[y] = x;
		if (rank[x] == rank[y]) rank[x]++;
	}
}

