				costs[verts[i].num] = cost_tmp;
		}else if(i == N-1){
			cost_tmp = verts[i].y - verts[i-1].y;
			if(cost_tmp < costs[verts[i].num])
				costs[verts[i].num] = cost_tmp;
		}
	}

	for(i=0; i<N; i++){
		total_cost += costs[i];
	}

	return total_cost;
}

