//O(ElogE)
ll saishou[200010];
void kurasukaru(G g){
	ufinit(g.vcnt);
	rep(i,0,g.ecnt){
		if(!same(g.e[i].s,g.e[i].g)){
			uni(g.e[i].s,g.e[i].g);
			saishou[i]=1;
		}
	}
}

