//Union-Find
int *par;
int *rank;
void union_init(int size){
	int i;
	par=calloc(size,sizeof(int));
	rank=calloc(size,sizeof(int));
	FOR(i,0,size) par[i]=i;
	return;
}
int root(int a){
	if(par[a]==a) return a;
	else{
		par[a]=root(par[a]);
		return par[a];
	}
}
int is_same(int a,int b){
	return root(a)==root(b);
}
void unite(int a,int b){
	a=root(a);
	b=root(b);
	if(a==b) return;
	if(rank[a]>rank[b])
	    par[b]=a;
	else{
		par[a]=b;
		if(rank[a]==rank[b]) rank[b]++;
	}
	return;
}
void delete_union(){
	free(par);
	free(rank);
	return;
}

typedef struct{
	int s,t,cost;
} Edge;
int comp(const void *a,const void *b){
	return ((Edge*)a)->cost > ((Edge*)b)->cost?1:-1;
};
ll kruscal(Edge *edge,int V,int E){
	int i,cnt=0;
	ll res=0;
	Edge e;
	qsort(edge,E,sizeof(Edge),comp);
	union_init(V);
	FOR(i,0,E){
		e=edge[i];
		if(!is_same(e.s,e.t)){
			unite(e.s,e.t);
			res+=e.cost,cnt++;
		}
	}
	delete_union();
	return cnt==V-1?res:-1;
}
