		for (int j = i+1;j < n;j++) {
			data[i][j] = MIN(ABS(x[i]-x[j]),ABS(y[i]-y[j]));
			data[j][i] = data[i][j];
		}
	}

	long long int ans = 0;
	int now = 0,tmp,min,minp;

