fun solve(c: Case) {
    val n = c.long().toInt()
    val towns = (0 until n).map { ind -> c.intList().let { Town(ind, it[0], it[1]) }}
    val edges = towns.sortedBy { it.x }.zipWithNext().map {
        Kruskal.Edge(it.first.id, it.second.id, it.second.x - it.first.x)
    } + towns.sortedBy { it.y }.zipWithNext().map {
        Kruskal.Edge(it.first.id, it.second.id, it.second.y - it.first.y)
    }
    c.println(Kruskal.solve(n, edges))
}

data class Town(val id: Int, val y: Int, val x: Int)

object Kruskal {
    fun solve(nodeSize: Int, edges: List<Edge>): Long {
        val unionFind = UnionFind(nodeSize)
        var cost = 0L
        edges.sortedBy { it.cost }.forEach { edge ->
            if (unionFind.same(edge.from, edge.to)) return@forEach
            unionFind.unite(edge.from, edge.to)
            cost += edge.cost
        }
        return cost
    }

    data class Edge(val from: Int, val to: Int, val cost: Int)

    private class UnionFind(n: Int) {
        val par = (0 until n).toMutableList()
        fun root(x: Int): Int = if (par[x] == x) x else root(par[x]).also { par[x] = it }
        fun same(x: Int, y: Int): Boolean = root(x) == root(y)
        fun unite(x: Int, y: Int) {
            if (root(x) != root(y)) par[root(x)] = root(y)
        }
    }
}

