class FastScanner(private val input: InputStream = System.`in`) {
    private val sb = StringBuilder()
    private val buffer = ByteArray(4096)
    private var pos = 0
    private var size = 0

    fun nextLong(): Long {
        var c = skipWhitespace()

        val sign = if (c == '-'.toInt()) {
            c = read()
            -1
        } else 1

        var ans = 0L

        while (c > ' '.toInt()) {
            ans = ans * 10 + c - '0'.toInt()
            c = read()
        }

        return sign * ans
    }

    fun nextInt() = nextLong().toInt()

    private fun skipWhitespace(): Int {
        while (true) {
            val c = read()
            if (c > ' '.toInt() || c < 0) return c
        }
    }

    private fun read(): Int {
        while (pos >= size) {
            if (size < 0) return -1
            size = input.read(buffer, 0, buffer.size)
            pos = 0
        }
        return buffer[pos++].toInt()
    }
}

class UnionFind(size: Int) {
    private val parent: IntArray = IntArray(size) { it }
    private val rank = IntArray(size)

    fun find(u: Int): Int {
        if (parent[u] != u) {
            parent[u] = find(parent[u])
        }
        return parent[u]
    }

    fun union(u: Int, v: Int): Int {
        val uRoot = find(u)
        val vRoot = find(v)
        if (uRoot == vRoot) {
            return uRoot
        }
        if (rank[uRoot] == rank[vRoot]) {
            rank[uRoot]++
        }
        return if (rank[uRoot] < rank[vRoot]) {
            parent[uRoot] = vRoot
            vRoot
        } else {
            parent[vRoot] = uRoot
            uRoot
        }
    }
}

