import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner();
        PrintWriter out = new PrintWriter(System.out);
        int n = sc.nextInt();
        Point[] pts = new Point[n];
        for (int i = 0; i < n; i++)
            pts[i] = new Point(sc.nextInt(), sc.nextInt(), i);
        ArrayList<Edge> edges = new ArrayList<>();
        Arrays.sort(pts, new X());
        for (int i = 0; i < n - 1; i++)
            edges.add(new Edge(pts[i].id, pts[i + 1].id, pts[i + 1].x - pts[i].x));
        Arrays.sort(pts, new Y());
        for (int i = 0; i < n - 1; i++)
            edges.add(new Edge(pts[i].id, pts[i + 1].id, pts[i + 1].y - pts[i].y));
        DSU dsu = new DSU(n);
        long ans = 0;
        Collections.sort(edges);
        for (Edge e : edges)
            if (dsu.union(e.v, e.u)) ans += e.cost;
        out.println(ans);
        out.flush();
        out.close();
    }

    static class DSU {
        int n, p[], size[];

        public DSU(int n) {
            this.n = n;
            p = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++)
                p[i] = i;
        }

        int findParent(int x) {
            return p[x] == x ? x : (p[x] = findParent(p[x]));
        }

        boolean union(int x, int y) {
            x = findParent(x);
            y = findParent(y);
            if (x == y) return false;
            if (size[x] >= size[y]) {
                size[x] += size[y];
                p[y] = x;
            } else {
                p[x] = y;
                size[y] += size[x];
            }
            return true;
        }
    }

