            if(!uf.same(from,to)){
                ans += edge[i][2];
                uf.union(from,to);
            }
        }
        out.println(ans);

    }
    public static class UnionFind{  
        int parent[];
        int rank[];

        public UnionFind(int n){
            parent = new int[n];
            rank   = new int[n];

            for(int i = 0;i < n;i++){
                parent[i] = i;
                rank[i]   = 0;
            }        
        }

        boolean same(int x,int y){
            return find(x) == find(y);
        }

        public int find(int x){
            if(parent[x] == x){
               return x;
            }else{
               return parent[x] = find(parent[x]);   
            }        
        }

        public void union(int x,int y){
            x = find(x);
            y = find(y);

            if(x != y){
                if(rank[x] > rank[y]){
                   parent[y] = x; 
                }else{
                   parent[x] = y;
                   if(rank[x] == rank[y]){
                       rank[y]++;
                   }
                }            
            }

            return;
        }

        public int count(int n){
            int ret = 0;
            for(int i = 0;i < n;i++){
                if(i == find(i)){
                    ret++;
                }
            }
            return ret;
        }

      } 

