    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	int N;

	private void solve() {
		// input
		Scanner io = new Scanner(System.in);
		N = io.nextInt();
		PriorityQueue<Point> queX = new PriorityQueue<>();
		PriorityQueue<Point> queY = new PriorityQueue<>();
		Node[] node = new Node[N];

		for(int i=0;i<N;i++){
			int x = io.nextInt();
			int y = io.nextInt();
			queX.add(new Point(x,i));
			queY.add(new Point(y,i));
			node[i] = new Node();
		}

		Point prev = queX.poll();
		Point now;
		while(!queX.isEmpty()){
			now = queX.poll();
			int far = now.dis - prev.dis;
			node[now.id].prevX = new Point (far,prev.id);
			node[prev.id].nextX = new Point (far,now.id);
			prev = now;
		}
		prev = queY.poll();
		while(!queY.isEmpty()){
			now = queY.poll();
			int far = now.dis - prev.dis;
			node[now.id].prevY = new Point (far,prev.id);
			node[prev.id].nextY = new Point (far,now.id);
			prev = now;
		}

		boolean[] fin = new boolean[N];
 		PriorityQueue<Point> queR = new PriorityQueue<>();
 		long ans = 0;

 		fin[0] = true;
 		queR.add(node[0].nextX);
 		queR.add(node[0].prevX);
 		queR.add(node[0].nextY);
 		queR.add(node[0].prevY);

 		while(!queR.isEmpty()){
 			now = queR.poll();
 			if(now.id==-1) break;
 			if(fin[now.id]) continue;

 			ans += now.dis;
 			fin[now.id] = true;
 	 		queR.add(node[now.id].nextX);
 	 		queR.add(node[now.id].prevX);
 	 		queR.add(node[now.id].nextY);
 	 		queR.add(node[now.id].prevY);
  		}

		System.out.println(ans);
	}

	public static void main(String[] args) {
		new Main().solve();
	}
}
