		DSU dsu = new DSU(n);
		Arrays.sort(edges, (a, b) -> a.c - b.c);
		long ans = 0;
		for (edge edge : edges)
			if (dsu.union(edge.u, edge.v))
				ans += edge.c;
		out.println(ans);
		out.close();

	}

	static class DSU {
		int[] p, r;

		DSU(int n) {
			p = new int[n];
			r = new int[n];
			for (int i = 0; i < n; i++)
				p[i] = i;
		}

		boolean union(int x, int y) {
			x = findSet(x);
			y = findSet(y);
			if (x == y)
				return false;
			if (r[x] > r[y]) {
				p[y] = x;
			} else {
				p[x] = y;
				if (r[x] == r[y])
					r[y]++;
			}
			return true;

		}

		int findSet(int x) {
			if (p[x] == x)
				return x;
			else
				return p[x] = findSet(p[x]);
		}
	}

	static class edge {
		int u, v, c;

		edge(int x, int y, int z) {
			u = x;
			v = y;
			c = z;
		}
	}

	static class Scanner {
		BufferedReader br;
