        Arrays.sort(pB);

        for(int i = 0; i < N - 1; ++i) {
            p.add(new Edge(pA[i].id,pA[i+1].id,Math.abs(pA[i].value-pA[i+1].value)));
            p.add(new Edge(pB[i].id,pB[i+1].id,Math.abs(pB[i].value-pB[i+1].value)));
        }
        Collections.sort(p);
        long ret = 0L;
        for(int i = 0; i < p.size(); ++i) {
            Edge e = p.get(i);
            if(!uf.isSame(e.from,e.to)) {
                uf.union(e.from,e.to);
                ret += e.value;
            }
        }
        writer.println(ret);
    }

    static class Edge implements Comparable<Edge> {
        int from;
        int to;
        int value;

        public Edge(int from,int to,int value) {
            this.from = from;
            this.to = to;
            this.value = value;
        }

        @Override
        public int compareTo(Edge o) {
            return this.value - o.value;
        }
    }

    static class UF {
        int N;
        int[] elem;
        int[] rank;

        public UF(int N) {
            this.N = N;
            elem = new int[N];
            rank = new int[N];

            for(int i = 0; i < N; ++i) {
                elem[i] = i;
                rank[i] = 1;
            }
        }

        public int getRoot(int x) {
            if(elem[x] == x) return x;
            else return elem[x] = getRoot(elem[x]);
        }

        public boolean isSame(int x,int y) {
            return getRoot(x) == getRoot(y);
        }

        public void union(int x,int y) {
            int xRoot = getRoot(x);
            int yRoot = getRoot(y);
            if(xRoot == yRoot) return;

            if(rank[xRoot] > rank[yRoot]) {
                rank[xRoot] += rank[yRoot];
                elem[yRoot] = xRoot;
            } else {
                rank[yRoot] += rank[xRoot];
                elem[xRoot] = yRoot;
            }
        }
    }

    static class Pair implements Comparable<Pair> {
        int id;
        int value;

        public Pair(int id,int value) {
            this.id = id;
            this.value = value;
        }

        @Override
        public int compareTo(Pair o) {
            return this.value - o.value;
        }
    }


