class Unionfind{
	int[] number;

	Unionfind(int n){
		number = new int[n];
		for(int i=0;i<n;i++){
			number[i] = i;
		}
	}

	int find(int x){
		if(number[x] == x){
			return x;
		}
		return number[x] = find(number[x]);
	}

	void unite(int x, int y){
		if(number[x] == number[y]){

		}
		else{
			number[find(x)] = number[find(y)];
		}
	}

	boolean same(int x, int y){
		if(number[find(x)] == number[find(y)]){
			return true;
		}
		return false;
	}
}

