        }

        Collections.sort(Y);
        for (int i = 0; i < N-1; ++i) {
            edges.add(new Edge(Y.get(i).id, Y.get(i+1).id, Math.abs(Y.get(i+1).pos - Y.get(i).pos)));
        }

