class Node{
	Node parent = null;

	public Node() {
	}

	public Node(Node _parent) {
		parent = _parent;
	}

	public Node getParent() {
		if(parent==null) return this;
		else {
			Node newParent = parent.getParent();
			parent = newParent;
			return newParent;
		}
	}
}

