    static class DBuilt {
        public void solve(int testNumber, LightScanner in, LightWriter out) {
            int n = in.ints();
            Vec3i[] xd = new Vec3i[n];
            for (int i = 0; i < n; i++) {
                xd[i] = new Vec3i(in.ints(), in.ints(), i);
            }
            Vec3i[] yd = xd.clone();
            IntroSort.sort(xd, Comparator.comparing(c -> c.x));
            IntroSort.sort(yd, Comparator.comparing(c -> c.y));
            Vec3i[] dx = new Vec3i[n - 1], dy = new Vec3i[n - 1];
            for (int i = 0; i < n - 1; i++) {
                dx[i] = new Vec3i(xd[i + 1].x - xd[i].x, xd[i].z, xd[i + 1].z);
                dy[i] = new Vec3i(yd[i + 1].y - yd[i].y, yd[i].z, yd[i + 1].z);
            }
            IntroSort.sort(dx, Comparator.comparing(c -> c.x));
            IntroSort.sort(dy, Comparator.comparing(c -> c.x));
            UnionFind uf = new UnionFind(n);

            int i = 0, j = 0;
            long ans = 0;
            while (i < n - 1 || j < n - 1) {
                if (i < n - 1 && (j == n - 1 || dx[i].x <= dy[j].x)) {
                    if (uf.find(dx[i].y) != uf.find(dx[i].z)) {
                        ans += dx[i].x;
                        uf.union(dx[i].y, dx[i].z);
                    }
                    i++;
                } else {
                    if (uf.find(dy[j].y) != uf.find(dy[j].z)) {
                        ans += dy[j].x;
                        uf.union(dy[j].y, dy[j].z);
                    }
                    j++;
                }
                //System.out.println(ans);
            }
            out.ans(ans).ln();
        }

    }

    static class IntroSort {
        private static int INSERTIONSORT_THRESHOLD = 16;

        private IntroSort() {
        }

        static <T> void sort(T[] a, int low, int high, int maxDepth, Comparator<T> comparator) {
            while (high - low > INSERTIONSORT_THRESHOLD) {
                if (maxDepth-- == 0) {
                    HeapSort.sort(a, low, high, comparator);
                    return;
                }
                int cut = QuickSort.step(a, low, high, comparator);
                sort(a, cut, high, maxDepth, comparator);
                high = cut;
            }
            InsertionSort.sort(a, low, high, comparator);
        }

        public static <T> void sort(T[] a, Comparator<T> comparator) {
            if (a.length <= INSERTIONSORT_THRESHOLD) {
                InsertionSort.sort(a, 0, a.length, comparator);
            } else {
                sort(a, 0, a.length, 2 * BitMath.msb(a.length), comparator);
            }
        }

    }

    static final class ArrayUtil {
        private ArrayUtil() {
        }

        public static <T> void swap(T[] a, int x, int y) {
            T t = a[x];
            a[x] = a[y];
            a[y] = t;
        }

    }

    static final class UnionFind {
        private final int[] groups;
        private final int[] rank;

        public UnionFind(int n) {
            groups = IntStream.range(0, n).toArray();
            rank = new int[n];
        }

        public int find(int i) {
            int ans = groups[i];
            if (ans == i) {
                return i;
            } else {
                return groups[i] = find(ans);
            }
        }

        public boolean union(int x, int y) {
            x = find(x);
            y = find(y);
            if (x == y) {
                return false;
            } else if (rank[x] < rank[y]) {
                groups[x] = y;
            } else if (rank[x] == rank[y]) {
                rank[x]++;
                groups[y] = x;
            } else {
                groups[y] = x;
            }
            return true;
        }

    }

    static class HeapSort {
        private HeapSort() {
        }

        private static <T> void heapfy(T[] a, int low, int high, int i, T val, Comparator<? super T> comparator) {
            int child = 2 * i - low + 1;
            while (child < high) {
                if (child + 1 < high && comparator.compare(a[child], a[child + 1]) < 0) {
                    child++;
                }
                if (comparator.compare(val, a[child]) >= 0) {
                    break;
                }
                a[i] = a[child];
                i = child;
                child = 2 * i - low + 1;
            }
            a[i] = val;
        }

        static <T> void sort(T[] a, int low, int high, Comparator<T> comparator) {
            for (int p = (high + low) / 2 - 1; p >= low; p--) {
                heapfy(a, low, high, p, a[p], comparator);
            }
            while (high > low) {
                high--;
                T pval = a[high];
                a[high] = a[low];
                heapfy(a, low, high, low, pval, comparator);
            }
        }

    }

