public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskD solver = new TaskD();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            Point[] points = new Point[n];
            for (int i = 0; i < n; i++) {
                int x = in.nextInt();
                int y = in.nextInt();
                points[i] = new Point(x, y, i);
            }

            ArrayList<Street> streets = new ArrayList<>();

            Arrays.sort(points, new Comparator<Point>() {

                public int compare(Point o1, Point o2) {
                    return o1.x - o2.x;
                }
            });

            for (int i = 0; i < n - 1; i++) {
                streets.add(new Street(points[i].i, points[i + 1].i, points[i + 1].x - points[i].x));
            }

            Arrays.sort(points, new Comparator<Point>() {

                public int compare(Point o1, Point o2) {
                    return o1.y - o2.y;
                }
            });

            for (int i = 0; i < n - 1; i++) {
                streets.add(new Street(points[i].i, points[i + 1].i, points[i + 1].y - points[i].y));
            }

            Collections.sort(streets);

            long ans = 0;
            UnionFind unionFind = new UnionFind(n);
            for (int i = 0; i < streets.size(); i++) {
                if (!unionFind.isConnected(streets.get(i).s, streets.get(i).t)) {
                    ans += streets.get(i).d;
                    unionFind.union(streets.get(i).s, streets.get(i).t);
                }
            }

            out.println(ans);
        }

        class Street implements Comparable<Street> {
            int s;
            int t;
            int d;

            public Street(int s, int t, int d) {
                this.s = s;
                this.t = t;
                this.d = d;
            }


            public int compareTo(Street o) {
                return d - o.d;
            }

        }

        class Point {
            int x;
            int y;
            int i;

            public Point(int x, int y, int i) {
                this.x = x;
                this.y = y;
                this.i = i;
            }

        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }

    static class UnionFind {
        int[] parent;

        public UnionFind(int size) {
            parent = new int[size];
            Arrays.fill(parent, -1);
        }

        public boolean union(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (parent[y] < parent[x]) {
                    int tmp = y;
                    y = x;
                    x = tmp;
                }
                parent[x] += parent[y];
                parent[y] = x;
                return true;
            }
            return false;
        }

        public boolean isConnected(int x, int y) {
            return root(x) == root(y);
        }

        public int root(int x) {
            return parent[x] < 0 ? x : (parent[x] = root(parent[x]));
        }

    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;
public class Main {
	public static void main(String[] args){
		Main main = new Main();
		main.solveD();
	}

	private void solveD() {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int[] x = new int[N];
		int[] y = new int[N];
		for (int i = 0; i < N; i++) {
			x[i] = sc.nextInt();
			y[i] = sc.nextInt();
		}
		Map<Integer, Integer> distMap = new HashMap<>();
		Set<Integer> connectSet = new HashSet<>();

		connectSet.add(0);
		for (int i = 1; i < N; i++) {
			distMap.put(i, min(abs(x[0] - x[i]), abs(y[0] - y[i])));
		}
		long sumDist = 0L;
		while (connectSet.size() < N) {
			int minDist = 1000000001;
			int minIndex = 0;
			for (int i = 1; i < N; i++) {
				if (connectSet.contains(i)) {
					continue;
				}
				if (minDist > distMap.get(i)) {
					minDist = distMap.get(i);
					minIndex = i;
				}
			}
			sumDist += minDist;
			connectSet.add(minIndex);
			for (int i = 1; i < N; i++) {
				if (connectSet.contains(i)) {
					continue;
				}
				int tmpDist = min(abs(x[minIndex] - x[i]), abs(y[minIndex] - y[i]));
				if (distMap.get(i) > tmpDist) {
					distMap.put(i, tmpDist);
				}
			}
		}
		System.out.println(sumDist);
	}

	private int abs(int n) {
		return n > 0 ? n : -n;
	}

	private int min(int a, int b) {
		return a < b ? a : b;
	}
}

