        	list.add(new Next(p1.now, p2.now, (int)Math.abs(p1.x-p2.x)));
        	p1 = ylist.get(i);
        	p2 = ylist.get(i+1);
        	list.add(new Next(p1.now, p2.now, (int)Math.abs(p1.y-p2.y)));
