        int count = 0;
        int now = 0;
        long ans = 0;
        while(list.size()>now){
        	Next p = list.get(now);
        	if(!flag[p.a] && !flag[p.b]){

        	}
        	else{
        		if(flag[p.a]){
        			flag[p.a] = false;
        			count++;
        		}
        		if(flag[p.b]){
        			flag[p.b] = false;
        			count++;
        		}
