        for (int i = 0; i < N; i++) {
            c[i] = new City(i, in.nextInt(), in.nextInt());
        }
        Road[] roads = new Road[(N - 1) * 2];
        Arrays.sort(c, new Comparator<City>() {
            public int compare(City p1, City p2){
