/// <summary>
    /// 依存:UnionFind
    /// </summary>
class Kruskal
{
    private int num;
    private List<Edge> edges;
    public Kruskal(int num)
    { this.num = num; edges = new List<Edge>(); }
    public void AddEdge(int u, int v, Number weight)
        => edges.Add(new Edge(u, v, weight));
    public Number Execute()
    {
        edges.Sort();
        Number res = 0;
        var uf = new UnionFind(num);
        foreach (var e in edges)
            if (uf.Union(e.from, e.to))
                res += e.cost;
        return res;
    }

    struct Edge : IComparable<Edge>
    {
        public int from;
        public int to;
        public Number cost;
        public Edge(int from,int to,Number cost)
        {
            this.from = from;this.to = to;this.cost = cost;
        }
        public int CompareTo(Edge e)
            => cost.CompareTo(e.cost);
    }
}
public class UnionFind
{
    protected int[] parent, size;
    public virtual int this[int i] { get { return Find(i); } }
    public UnionFind(int num)
    {
        parent = new int[num]; size = new int[num];
        for (var i = 0; i < num; i++) { parent[i] = i; size[i] = 1; }
    }
    protected int Find(int i)
        => i == parent[i] ? i : (parent[i] = Find(parent[i]));
    public int Size(int i)
        => size[Find(i)];
    public virtual bool Union(int v1, int v2)
    {
        v1 = Find(v1); v2 = Find(v2);
        if (v1 == v2) return false;
        if (size[v1] < size[v2])
            swap(ref v1, ref v2);
        parent[v2] = v1;
        size[v1] += size[v2];
        return true;
    }
}
