			public UnionFind(int size) {
				_data = new int[size];
				for (var i = 0; i < size; i++) _data[i] = -1;
			}

			public bool Unite(int x, int y) {
				x = Root(x);
				y = Root(y);

				if (x == y) return x != y;
				if (_data[y] < _data[x]) {
					var tmp = y;
					y = x;
					x = tmp;
				}
				_data[x] += _data[y];
				_data[y] = x;
				return x != y;
			}

			public bool IsSameGroup(int x, int y) {
				return Root(x) == Root(y);
			}

			public int Root(int x) {
				return _data[x] < 0 ? x : _data[x] = Root(_data[x]);
			}
		}

		public class Kruskal
		{
			private List<Tuple<int, int, long>> edgeList;
			private int N { get; set; }
			public Kruskal(int n) {
				N = n;
				edgeList=new List<Tuple<int, int, long>>();
			}

			public void Add(int s, int t, long cost) => edgeList.Add(new Tuple<int, int, long>(s, t, cost));

			public long Run() {
				edgeList.Sort((a, b) => a.Item3.CompareTo(b.Item3));
				var rt = 0L;
				var uf=new UnionFind(N);
				foreach (var tuple in edgeList) {
					var s = tuple.Item1;
					var t = tuple.Item2;
					var cost = tuple.Item3;
					if(uf.IsSameGroup(s,t)) continue;
					uf.Unite(s, t);
					rt += cost;
				}

				return rt;
			}
		}


	}
}
namespace Nakov.IO {
	using System;
	using System.Text;
	using System.Globalization;

	public static class Cin {
		public static string NextToken() {
			StringBuilder tokenChars = new StringBuilder();
			bool tokenFinished = false;
			bool skipWhiteSpaceMode = true;
			while (!tokenFinished) {
				int nextChar = Console.Read();
				if (nextChar == -1) {
					tokenFinished = true;
				} else {
					char ch = (char)nextChar;
					if (char.IsWhiteSpace(ch)) {
						if (!skipWhiteSpaceMode) {
							tokenFinished = true;
							if (ch == '\r' && (Environment.NewLine == "\r\n")) {
								Console.Read();
							}
						}
					} else {
						skipWhiteSpaceMode = false;
						tokenChars.Append(ch);
					}
				}
			}

			string token = tokenChars.ToString();
			return token;
		}

		public static int NextInt() {
			string token = Cin.NextToken();
			return int.Parse(token);
		}
		public static long NextLong() {
			string token = Cin.NextToken();
			return long.Parse(token);
		}
		public static double NextDouble(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				double result = double.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				double result = double.Parse(token);
				return result;
			}
		}
		public static decimal NextDecimal(bool acceptAnyDecimalSeparator = true) {
			string token = Cin.NextToken();
			if (acceptAnyDecimalSeparator) {
				token = token.Replace(',', '.');
				decimal result = decimal.Parse(token, CultureInfo.InvariantCulture);
				return result;
			} else {
				decimal result = decimal.Parse(token);
				return result;
			}
		}

	}
