namespace AtCoder
{
    class Node
    {
        private int m_height = 0;
        private Node m_parent = null;
        public Node Find()
        {
            if (m_parent == null)
            {
                return this;
            }
            else
            {
                Node parent = m_parent.Find();
                m_parent = parent;
                return parent;
            }
        }
        public static void Unite(Node a, Node b)
