    class Solver
    {
        public void Solve()
        {
            var num = Input.num;
            var xy = new Pair<int, int, int>[num];
            for (var i = 0; i < num; i++)
                xy[i] = new Pair<int, int, int>(Input.Next<int>(), Input.Next<int>(), i);
            var k = new Kruskal(num);
            var uf = new UnionFind(num);
            Array.Sort(xy, (a, b) => a.v1 - b.v1);
            for (var i = 0; i < num - 1; i++)
                k.AddEdge(xy[i].v3, xy[i + 1].v3, xy[i + 1].v1 - xy[i].v1);
            Array.Sort(xy, (a, b) => a.v2 - b.v2);
            for (var i = 0; i < num - 1; i++)
                k.AddEdge(xy[i].v3, xy[i + 1].v3, xy[i + 1].v2 - xy[i].v2);
            WriteLine(k.Execute());
        }
    }
    /// <summary>
    /// 依存:UnionFind
    /// </summary>
    class Kruskal
    {
        private int num;
        private List<Pair<int, int, Number>> edges;
        public Kruskal(int num)
        { this.num = num;edges = new List<Pair<int, int, Number>>(); }
        public void AddEdge(int u, int v, Number weight)
            => edges.Add(new Pair<int, int, Number>(u, v, weight));
        public Number Execute()
        {
            edges.Sort((a, b) => a.v3.CompareTo(b.v3));
            Number res = 0;
            var uf = new UnionFind(num);
            foreach (var e in edges)
                if (uf.Union(e.v1, e.v2))
                    res += e.v3;
            return res;
        }
    }
}

public class UnionFind
{
    protected int[] parent, size, rank;
    public UnionFind(int num)
    {
        parent = new int[num]; size = new int[num]; rank = new int[num];
        for (var i = 0; i < num; i++) { parent[i] = i; size[i] = 1; }
    }
    protected int Find(int i)
        => i == parent[i] ? i : (parent[i] = Find(parent[i]));
    public int Parent(int i)
        => Find(i);
    public int Size(int i)
        => size[Find(i)];
    public virtual bool Union(int v1, int v2)
    {
        v1 = Find(v1); v2 = Find(v2);
        if (v1 == v2) return false;
        if (rank[v1] < rank[v2])
            swap(ref v1, ref v2);
        parent[v2] = v1;
        size[v1] += size[v2];
        if (rank[v1] == rank[v2])
            rank[v1]++;
        return true;
    }
    public bool IsSame(int v1, int v2)
        => Find(v1) == Find(v2);
}

