using System;
using System.Text;
using System.Collections.Generic;
using System.Linq;
class Solve{
    public Solve(){}
    StringBuilder sb;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = int.Parse(Console.ReadLine());
        long count = 0;
        long[] X = new long[N];
        long[] Y = new long[N];
        int[] CX = new int[N];
        int[] CY = new int[N];
        for(int i=0;i<N;i++){
            string[] str = Console.ReadLine().Split(' ');
            X[i] = int.Parse(str[0]);
            Y[i] = int.Parse(str[1]);
            CX[i] = i;
            CY[i] = i;
        }
        Array.Sort(X,CX);
        Array.Sort(Y,CY);
        long[] DX = new long[N-1];
        long[] DY = new long[N-1];
        int[] CDX = new int[N-1];
        int[] CDY = new int[N-1];
        for(int i=0;i<N-1;i++){
            DX[i] = X[i+1]-X[i];
            DY[i] = Y[i+1]-Y[i];
            CDX[i] = i;
            CDY[i] = i;
        }
        Array.Sort(DX,CDX);
        Array.Sort(DY,CDY);
        UnionFind U = new UnionFind(N);
        int p = 0;
        int q = 0;
        while(p < N-1 || q < N-1){
            if(q == N-1 || (p < N-1 && (DX[p] < DY[q]))){
                if(!U.Same(CX[CDX[p]],CX[CDX[p]+1])){
                    U.Union(CX[CDX[p]],CX[CDX[p]+1]);
                    count += DX[p];
                }
                p++;
            }
            else{
                if(!U.Same(CY[CDY[q]],CY[CDY[q]+1])){
                    U.Union(CY[CDY[q]],CY[CDY[q]+1]);
                    count += DY[q];
                }
                q++;
            }
        }
        sb.Append(count+"\n");
    }
}
class UnionFind{
    int[] par;
    public UnionFind(int n){
        par = new int[n];
        for(int i=0;i<n;i++){
            par[i] = i;
        }
    }
    public void Union(int x,int y){
        par[Get(x)] = Get(y); 
    }
    public bool Same(int x,int y){
        return Get(x) == Get(y);
    }
    int Get(int x){
        if(x != par[x]){
            par[x] = Get(par[x]);
        }
        return par[x];
    }
}

