        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        pr.Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        var num = Input.num;
        var xy = new Pair<int, int, int>[num];
        for(var i = 0; i < num; i++)
            xy[i] = new Pair<int, int, int>(i, Input.Next<int>(), Input.Next<int>());
        var sx = xy.OrderBy(v => v.v2).ToArray();
        var sy = xy.OrderBy(v => v.v3).ToArray();
        Func<int, int[], Pair<long, int>[]> func = (a, b) =>
           {
               var ps = Enumerable.Repeat(0, a).Select(_ => new Pair<long, int>(long.MaxValue, -1)).ToArray();
               for (var i = 0; i < num - 1; i++)
               {
                   if (b[sx[i].v1] == b[sx[i + 1].v1]) goto SECOND;
                   long w = sx[i + 1].v2 - sx[i].v2;
                   if (ps[b[sx[i].v1]].v1 > w)
                       ps[b[sx[i].v1]] = new Pair<long, int>(w, b[sx[i + 1].v1]);
                   if (ps[b[sx[i + 1].v1]].v1 > w)
                       ps[b[sx[i + 1].v1]] = new Pair<long, int>(w, b[sx[i].v1]);
                   SECOND:;
                   if (b[sy[i].v1] == b[sy[i + 1].v1]) continue;
                   w = sy[i + 1].v3 - sy[i].v3;
                   if (ps[b[sy[i].v1]].v1 > w)
                       ps[b[sy[i].v1]] = new Pair<long, int>(w, b[sy[i + 1].v1]);
                   if (ps[b[sy[i + 1].v1]].v1 > w)
                       ps[b[sy[i + 1].v1]] = new Pair<long, int>(w, b[sy[i].v1]);
               }
               return ps;
           };
        WriteLine(Boruvka(num, func));
    }
    public static long Boruvka(int num, Func<int, int[], Pair<long, int>[]> func)
    {
        var uf = new UnionFind(num);
        var res = 0L;
        var rev = new int[num];
        var parent = new int[num];
        while (true)
        {
            var update = false;
            var c = 0;
            for (var i = 0; i < num; i++)
                if (i == uf.Parent(i))
                {
                    rev[c] = i;
                    parent[i] = c++;
                }
            for (var i = 0; i < num; i++)
                parent[i] = parent[uf.Parent(i)];
            var pair = func(c, parent);
            for (var i = 0; i < c; i++)
                if (pair[i].v2 != -1 && !uf.IsSame(rev[pair[i].v2], rev[i]))
                {
                    uf.Union(rev[pair[i].v2], rev[i]);
                    res += pair[i].v1;
                    update = true;
                }
            if (!update) break;
        }
        return res;
    }
}

public class UnionFind
{
    private int[] _parent, _size, _rank;
    public UnionFind(int num)
    {
        IndependenceNum = num;
        _parent = new int[num]; _size = new int[num]; _rank = new int[num];
        for (var i = 0; i < num; i++) { _parent[i] = i; _size[i] = 1; }
    }
    //独立な集合の数
    public int IndependenceNum { get; private set; }
    private int Find(int i)
        => i == _parent[i] ? i : (_parent[i] = Find(_parent[i]));
    public int Parent(int i)
        => Find(i);
    public int Size(int i)
        => _size[Find(i)];
    public bool Union(int v1, int v2)
    {
        v1 = Find(v1); v2 = Find(v2);
        if (v1 == v2) return false;
        IndependenceNum--;
        if (_rank[v1] > _rank[v2])
        {
            _parent[v2] = v1;
            _size[v1] += _size[v2];
        }
        else
        {
            _parent[v1] = v2;
            _size[v2] += _size[v1];
            if (_rank[v1] == _rank[v2])
                _rank[v2]++;
        }
        return true;
    }
    public bool IsSame(int v1, int v2)
        => Find(v1) == Find(v2);
}


