		public static void Solve(Scanner cin)
		{
			int n = cin.ReadInt();
			var (x, y) = cin.ReadValueArray<int, int>(n);
			var xset = new Set<(int x, int i)>();
			var yset = new Set<(int y, int i)>();
			for (int i = 0; i < n; i++)
			{
				xset.Add((x[i], i));
				yset.Add((y[i], i));
			}
			var pq = new PriorityQueue<(long len, int index1, int index2)>();
			var uf = new UnionFind(n);
			for (int i = 1; i < n; i++)
			{
				pq.Enqueue((xset[i].x - xset[i - 1].x, xset[i].i, xset[i - 1].i));
				pq.Enqueue((yset[i].y - yset[i - 1].y, yset[i].i, yset[i - 1].i));
			}
			int con = 0;
			long ans = 0;
			while (con < n - 1)
			{
				var (nlen, nx, ny) = pq.Dequeue();
				if (!uf.IsSame(nx, ny))
				{
					uf.Unite(nx, ny);
					ans += nlen;
					con++;
				}
			}
			Console.WriteLine(ans);
		}

