struct City
{
    public int id { get; private set; }
    public int x { get; private set; }
    public int y { get; private set; }

    public City(int id, int x, int y)
    {
        this.id = id;
        this.x = x;
        this.y = y;
    }
}

struct Edge
{
    public int a { get; private set; }
    public int b { get; private set; }
    public long cost { get; private set; }

    public Edge(int a, int b, long cost)
    {
        this.a = a;
        this.b = b;
        this.cost = cost;
    }
}

class Program
{
    static int N;
    static List<City> cities;
    static List<Edge> es;

    static void Main()
    {
        /* 入力の受け取り、変数の初期化 */
        N = int.Parse(Console.ReadLine());
        cities = new List<City>();
        for (int i = 0; i < N; i++)
        {
            int[] input = Console.ReadLine().Split().Select(int.Parse).ToArray();
            cities.Add(new City(i, input[0], input[1]));
        }
        es = new List<Edge>();

        /* 街をx順にソートし、隣街との間に辺を張る */
        cities.Sort((a, b) => a.x - b.x);
        for (int i = 0; i < N - 1; i++)
        {
            int s = cities[i].id;
            int g = cities[i + 1].id;
            long l = Math.Abs(cities[i].x - cities[i + 1].x);
            es.Add(new Edge(s, g, l));
        }

        /* 街をy順にソートし、隣街との間に辺を張る */
        cities.Sort((a, b) => a.y - b.y);
        for (int i = 0; i < N - 1; i++)
        {
            int s = cities[i].id;
            int g = cities[i + 1].id;
            long l = Math.Abs(cities[i].y - cities[i + 1].y);
            es.Add(new Edge(s, g, l));
        }

        /* クラスカル法で答えを求める */
        Console.WriteLine(Kruskal());
    }

    /* グラフesに対し、クラスカル法で最小全域木を求め、総コストを返す */
    static long Kruskal()
    {
        es.Sort((a, b) => (a.cost > b.cost) ? 1 : (a.cost == b.cost) ? 0 : -1);

        UF uf = new UF(N);
        long min_cost = 0;

        foreach (var e in es)
        {
            if (!uf.Same(e.a, e.b))
            {
                min_cost += e.cost;
                uf.Unite(e.a, e.b);
            }
        }

        return min_cost;
    }
}

namespace UnionFind
{
    class UF
    {
        private int[] 親; //親[i] : iの親の番号

        public UF(int N) //コンストラクタ、すべてが根として初期化
        {
            親 = new int[N];
            for (int i = 0; i < N; i++)
                親[i] = i;
        }

        public int Root(int x) //xの属する木の根を返す
        {
            if (親[x] == x) return x;
            return 親[x] = Root(親[x]);
        }

        public void Unite(int x, int y) //xとyの木を統合
        {
            int rx = Root(x);
            int ry = Root(y);
            if (rx == ry) return;
            親[rx] = ry;
        }

        public bool Same(int x, int y) //xとyが同じ木に属するかどうかを返す
        {
            return Root(x) == Root(y);
        }
    }
}

