# array and variables are all 0 indexed
class UnionFind
	def initialize(n)
		@parent = Array.new(n){|i| i}
		@rank = Array.new(n){1}
	end
	def find(x)
		par = @parent[x]
		if(par == x)
			return x
		else
			return @parent[x] = find(par)
		end
	end
	def union(x,y)
		root_x = find(x)
		root_y = find(y)
		if(root_x == root_y)
			#ok
			return
		end
		if(@rank[root_x] < @rank[root_y])
			@parent[root_x] = root_y
		elsif(@rank[root_x] == @rank[root_y])
			@parent[root_y] = root_x
			@rank[root_x] += 1
		else
			@parent[root_y] = root_x
		end
	end
	def same_root?(x,y)
		return find(x)==find(y)
	end
end

# e : no directed edges
# n : the number of edges
def kruskal(es,n)
	u = UnionFind.new(n)
	sum = 0
	es.sort{|e1,e2| e1[2] <=> e2[2]}.each{|e|
		if(u.find(e[0]) != u.find(e[1]))
			sum += e[2]
			u.union(e[0],e[1])
		end
	}
	sum
end

