package main

import (
    "fmt"
    "sort"
)

type Tuple struct {
    x, index int
}

type Tuple3 struct {
    i, j, cost int
}

type Tuples []Tuple
type Tuple3s []Tuple3

func (ts Tuples) Len() int {
    return len(ts)
}

func (ts Tuples) Swap(x, y int) {
    ts[x], ts[y] = ts[y], ts[x]
}

func (ts Tuples) Less(i, j int) bool {
    return ts[i].x < ts[j].x
}

func (ts Tuple3s) Len() int {
    return len(ts)
}

func (ts Tuple3s) Swap(x, y int) {
    ts[x], ts[y] = ts[y], ts[x]
}

func (ts Tuple3s) Less(i, j int) bool {
    return ts[i].cost < ts[j].cost
}

var ran, par []int

func initialize(n int) {
    par, ran = make([]int, n), make([]int, n)
    for i := 0; i < n; i++ {
        par[i] = i
        ran[i] = 1
    }
}

func find(x int) int {
    if x == par[x] {
        return x
    }
    par[x] = find(par[x])
    return par[x]
}

func unite(x, y int) bool {
    x = find(x)
    y = find(y)
    if x == y {
        return false
    }

    if ran[x] < ran[y] {
        par[x] = y
    } else {
        par[y] = x
        if ran[x] == ran[y] {
            ran[x]++
        }
    }
    return true
}

func main() {
    var n int
    fmt.Scan(&n)
    x, y := make(Tuples, n), make(Tuples, n)
    for i := 0; i < n; i++ {
        var a, b int
        fmt.Scan(&a, &b)
        x[i] = Tuple {a, i}
        y[i] = Tuple {b, i}
    }
    sort.Sort(x)
    sort.Sort(y)
    costs := make(Tuple3s, 2 * n - 2)
    for i := 1; i < n; i++ {
        costs[2 * i - 2] = Tuple3 {x[i].index, x[i - 1].index, x[i].x - x[i - 1].x}
        costs[2 * i - 1] = Tuple3 {y[i].index, y[i - 1].index, y[i].x - y[i - 1].x}
    }
    sort.Sort(costs)
    count := 0
    ans := 0
    initialize(n)
    for _, t := range costs {
        if count == n - 1 {
            break
        }
        if unite(t.i, t.j) {
            count++
            ans += t.cost
        }
    }
    fmt.Println(ans)
}

