class UnionFind
{
private:
    int[] p;
    int[] rank;

public:
    this(int N)
    {
        p = iota(N).array;
        rank = new int[](N);
    }

    int find_root(int x)
    {
        if(x != p[x]) p[x] = find_root(p[x]);
        return p[x];
    }

    bool same(int x, int y)
    {
        return find_root(x) == find_root(y);
    }

    void unite(int x, int y)
    {
        x = find_root(x);
        y = find_root(y);

        if (x == y) return;

        if (rank[x] < rank[y]) {
            p[x] = y;
        }
        else {
            p[y] = x;

            if (rank[x] == rank[y]) rank[x]++;
        }
    }
}

