		auto p = n.iota.array;

		int root (int v)
		{
			if (p[v] != v)
			{
				p[v] = root (p[v]);
			}
			return p[v];
		}

		bool unite (int u, int v)
		{
			u = root (u);
			v = root (v);
			if (u == v)
			{
				return false;
			}
			p[u] = v;
			return true;
		}

		edges.schwartzSort !(edge => edge.w);
		int res = 0;
		foreach (ref edge; edges)
		{
			if (unite (edge.u, edge.v))
			{
				res += edge.w;
			}
		}
		writeln (res);
	}
}

