        CS[i] = c;
    }
    sort!"a.x < b.x"(CS[0..N]);
    foreach (i; 0..N-1) {
        auto a = CS[i];
        auto b = CS[i+1];
        DSX[i] = D(a.n, b.n, b.x - a.x);
    }
    sort!"a.y < b.y"(CS[0..N]);
    foreach (i; 0..N-1) {
        auto a = CS[i];
        auto b = CS[i+1];
        DSY[i] = D(a.n, b.n, b.y - a.y);
    }
    sort!"a.d < b.d"(DSX[0..N-1]);
    sort!"a.d < b.d"(DSY[0..N-1]);

    auto uft = UFTree!int(N);

    long r;
    for (size_t i, j; i != N-1 && j != N-1;) {
        auto a = long.max, b = long.max;
        if (i < N-1) a = DSX[i].d;
        if (j < N-1) b = DSY[j].d;
        D d;
        if (a < b) {
            d = DSX[i++];
        } else {
            d = DSY[j++];
        }
        if (uft.is_same(d.a, d.b)) continue;
        uft.unite(d.a, d.b);
        r += d.d;
    }

    writeln(r);
}

