fn solve(xys: Vec<(i64, i64)>) -> i64 {
    use std::collections::BinaryHeap;
    use std::cmp::min;

    let n = xys.len();
    let mut used = vec![false; n];
    let mut heap = BinaryHeap::new();

    let mut total = 0;

    heap.push((0i64, 0));

    while !heap.is_empty() {
        let (cost, dest) = heap.pop().unwrap();
        if used[dest] {
            continue
        }

        used[dest] = true;
        let cost = -cost;
        total += cost;

        let (dx,dy) = xys[dest];

        for i in 0..n {
            if !used[i] {
                let (sx,sy) = xys[i];
                let c = min((dx-sx).abs(), (dy-sy).abs());
                heap.push((-c, i));
            }
        }
    }

    total
}

fn main() {
    let n = parse_line!(usize);
    let xys = (0..n).into_iter().map(|_| parse_line!(i64, i64)).collect::<Vec<_>>();

    println!("{}", solve(xys));
}

