        }
    }

    #[allow(dead_code)]
    fn root(&mut self, x: usize) -> usize {
        if self.par[x] < 0 {
            x
        } else {
            let p = self.par[x] as usize;
            self.par[x] = self.root(p) as i32;
            self.par[x] as usize
        }
