        } else {
            if self.size(x) < self.size(y) {
                self.par[y] += self.par[x];
                self.par[x] = y as i32; // usize <-> i32
            } else {
                self.par[x] += self.par[y];
                self.par[y] = x as i32;
            }
            true
        }
    }

    #[allow(dead_code)]
