struct UFTree {
    roots: Vec<usize>,
    ranks: Vec<usize>,
}

impl UFTree {
    fn new(num: usize) -> UFTree {
        let mut rs = vec![0; num];
        for i in 0..num {
            rs[i] = i;
        }

        UFTree {
            roots: rs,
            ranks: vec![1; num],
        }
    }

    fn find(&mut self, v: usize) -> Option<usize> {
        if self.roots.len() <= v {
            None
        }
        else {
            let vr = self.roots[v];

            if vr == v {
                Some(v)
            }
            else if let Some(r) = self.find(vr) {
                self.roots[v] = r;

                Some(r)
            }
            else {
                None
            }
        }
    }

    fn unite(&mut self, u: usize, v: usize) {
        if let (Some(ur), Some(vr)) = (self.find(u), self.find(v)) {
            if ur == vr {
                return;
            }

            if self.ranks[ur] < self.ranks[vr] {
                self.roots[ur] = vr;
            }
            else {
                self.roots[vr] = ur;

                if self.ranks[ur] == self.ranks[vr] {
                    self.ranks[ur] += 1;
                }
            }
        }
    }

    fn same(&mut self, u: usize, v: usize) -> bool {
        if let (Some(ur), Some(vr)) = (self.find(u), self.find(v)) {
            ur == vr
        }
        else {
            false
        }
    }
}

