    cost: i64,
}

fn main() {
    let n = readln();

    let mut xys = vec![];
    let mut xys2 = vec![];

    for i in 0..n {
        let x: Vec<usize> = reads();

        xys.push((x[0], x[1], i));
        xys2.push((x[1], x[0], i));
    }

    xys.sort();

    let mut es = vec![];

    for i in 0..(n - 1) {
        let v1 = xys[i];
        let v2 = xys[i + 1];

        let e = E {u: v1.2, v: v2.2, cost: (v1.0 as i64 - v2.0 as i64).abs()};

        es.push(e);
    }

    xys2.sort();

    for i in 0..(n - 1) {
        let v1 = xys2[i];
        let v2 = xys2[i + 1];

        let e = E {u: v1.2, v: v2.2, cost: (v1.0 as i64 - v2.0 as i64).abs()};

        es.push(e);
    }

    es.sort_by(|&lhs, &rhs| {
        lhs.cost.cmp(&rhs.cost)
    });

    let mut uf = UFTree::new(n);
    let mut res = 0;

    for e in es {
        if !uf.same(e.u, e.v) {
            uf.unite(e.u, e.v);
            res += e.cost;
        }
    }

    println!("{}", res);
}

