                self.rank[x] += 1;
            }
        }
    }
}

fn solve() {
    let n = get!(usize);
    let xys = get!(u64, u64; n);

    let mut xx: Vec<usize> = (0..n).collect();
    let mut yy: Vec<usize> = (0..n).collect();

    xx.sort_by_key(|&i| xys[i].0);
    yy.sort_by_key(|&i| xys[i].1);

    let mut ds = Vec::new();

    for w in xx.windows(2) {
        let i = w[0];
        let j = w[1];
        let d = xys[j].0 - xys[i].0;
        ds.push((d, i, j));
    }
    for w in yy.windows(2) {
        let i = w[0];
        let j = w[1];
        let d = xys[j].1 - xys[i].1;
        ds.push((d, i, j));
    }

    ds.sort();
    let mut uft = UFT::new(n);
    let mut ans = 0;

    for (d, i, j) in ds {
        if uft.root(i) != uft.root(j) {
            uft.merge(i, j);
            ans += d;
        }
    }

    println!("{}", ans);
}

