}

fn main() {
    let n = readln();

    let mut xys = vec![];

    for i in 0..n {
        let x: Vec<usize> = reads();

        xys.push((i, x[0], x[1]));
    }

    let mut vs = xys.clone();

    vs.sort_by(|&lhs, &rhs| {
        lhs.1.cmp(&rhs.1).then(lhs.2.cmp(&rhs.2))
    });

    let mut es = vec![];

    for i in 0..(n - 1) {
        let v1 = vs[i];
        let v2 = vs[i + 1];

        let e = E {u: v1.0, v: v2.0, cost: (v1.1 as i64 - v2.1 as i64).abs()};

        es.push(e);
    }

    vs.sort_by(|&lhs, &rhs| {
        lhs.2.cmp(&rhs.2).then(lhs.1.cmp(&rhs.1))
    });

    for i in 0..(n - 1) {
        let v1 = vs[i];
        let v2 = vs[i + 1];

        let e = E {u: v1.0, v: v2.0, cost: (v1.2 as i64 - v2.2 as i64).abs()};

        es.push(e);
    }

    es.sort_by(|&lhs, &rhs| {
        lhs.cost.cmp(&rhs.cost)
    });

    let mut uf = UFTree::new(n);
